# =========================
# HELPERS
# =========================
def now_iso():
    return datetime.now().isoformat(timespec="seconds")

def california_now():
    if pytz:
        return datetime.now(pytz.timezone("America/Los_Angeles"))
    return datetime.utcnow() - timedelta(hours=7)

def safe_float(x, default=None):
    try:
        if x is None or x == "":
            return default
        return float(x)
    except Exception:
        return default

def safe_int(x, default=None):
    try:
        if x is None or x == "":
            return default
        return int(float(x))
    except Exception:
        return default

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def load_json(path, default):
    try:
        if os.path.exists(path):
            with open(path, "r") as f:
                return json.load(f)
    except Exception:
        pass
    return default

def _safe_json_len(obj):
    try:
        if isinstance(obj, list):
            return len(obj)
        if isinstance(obj, dict):
            return len(obj)
    except Exception:
        pass
    return None

def _is_protected_learning_json(path):
    """Protect core learning/result files from accidental empty/smaller overwrites during redeploys."""
    try:
        name = os.path.basename(str(path or "")).lower()
        protected_names = {
            "auto_result_log.json",
            "long_backtest_rows.json",
            "pitcher_learning.json",
            "true_calibration_engine.json",
            "signal_tracking.json",
            "clv_tracker.json",
            "k_bucket_learning.json",
            "k_pitcher_learning.json",
            "k_confidence_learning.json",
        }
        return name in protected_names
    except Exception:
        return False

def save_json(path, data):
    try:
        # Railway/data-loss guard: never let a restart/update replace a good learning file
        # with an empty or sharply smaller payload. This does not change model math.
        if _is_protected_learning_json(path) and os.path.exists(path):
            try:
                with open(path, "r") as f_old:
                    old_data = json.load(f_old)
                old_len = _safe_json_len(old_data)
                new_len = _safe_json_len(data)
                if old_len is not None and new_len is not None and old_len > 0:
                    # Block empty writes and major accidental shrinkage. Allows normal dedupe/cleanup up to 10%.
                    if new_len == 0 or (old_len >= 50 and new_len < int(old_len * 0.90)):
                        try:
                            st.session_state["safe_save_last_blocked"] = {
                                "path": str(path), "old_len": old_len, "new_len": new_len, "time": now_iso()
                            }
                        except Exception:
                            pass
                        return
                # Always keep a local .bak before replacing protected learning files.
                try:
                    with open(str(path) + ".bak", "w") as f_bak:
                        json.dump(old_data, f_bak, indent=2)
                except Exception:
                    pass
            except Exception:
                pass
        dir_name = os.path.dirname(path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        with open(path, "w") as f:
            json.dump(data, f, indent=2)
    except Exception:
        pass


# =========================
# v72 GITHUB/RAILWAY SAFE LEARNING + K CALIBRATION HELPERS
# =========================
def _safe_learning_row_count(obj):
    """Conservative count for learning payloads used by safe-write guards."""
    try:
        if obj is None:
            return 0
        if isinstance(obj, pd.DataFrame):
            return int(len(obj))
        if isinstance(obj, list):
            return int(len(obj))
        if isinstance(obj, dict):
            # For profile dictionaries, count total samples if present.
            if "samples" in obj:
                return int(safe_float(obj.get("samples"), 0) or 0)
            total = 0
            for v in obj.values():
                if isinstance(v, dict):
                    total += int(safe_float(v.get("samples", v.get("count", 0)), 0) or 0)
                elif isinstance(v, list):
                    total += len(v)
            return int(total)
    except Exception:
        return 0
    return 0

def safe_write_learning_csv(path, df, min_keep_ratio=0.90):
    """Write learning CSV without allowing a redeploy/session bug to wipe a larger file.

    This is intentionally a storage guard only. It does not change projections.
    """
    try:
        if df is None:
            return False
        if not isinstance(df, pd.DataFrame):
            df = pd.DataFrame(df)
        new_n = len(df)
        os.makedirs(os.path.dirname(path), exist_ok=True) if os.path.dirname(path) else None
        if os.path.exists(path):
            try:
                old_df = pd.read_csv(path)
                old_n = len(old_df)
                if old_n > 0 and (new_n == 0 or (old_n >= 50 and new_n < int(old_n * min_keep_ratio))):
                    try:
                        st.session_state["safe_csv_save_last_blocked"] = {
                            "path": str(path), "old_rows": old_n, "new_rows": new_n, "time": now_iso()
                        }
                    except Exception:
                        pass
                    return False
                try:
                    old_df.to_csv(str(path) + ".bak", index=False)
                except Exception:
                    pass
            except Exception:
                pass
        df.to_csv(path, index=False)
        return True
    except Exception:
        return False

def _k_learning_line_bucket(line):
    line = safe_float(line, None)
    if line is None:
        return "NO_LINE"
    if line < 3.5:
        return "<3.5"
    if line < 4.5:
        return "3.5"
    if line < 5.5:
        return "4.5"
    if line < 6.5:
        return "5.5"
    if line < 7.5:
        return "6.5"
    return "7.5+"

def _k_learning_conf_bucket(prob):
    p = safe_float(prob, None)
    if p is None:
        return "UNKNOWN"
    if p <= 1.0:
        p *= 100.0
    if p < 55:
        return "<55"
    if p < 60:
        return "55-60"
    if p < 65:
        return "60-65"
    if p < 70:
        return "65-70"
    return "70+"

def _k_learning_pitcher_key(row):
    return normalize_name((row or {}).get("pitcher") or (row or {}).get("Pitcher") or (row or {}).get("player") or "")

def _k_learning_row_projection(row):
    return safe_float((row or {}).get("final_projection"), safe_float((row or {}).get("projection"), safe_float((row or {}).get("K PROJ"), None)))

def _k_learning_row_actual(row):
    return safe_float((row or {}).get("actual"), safe_float((row or {}).get("actual_k"), safe_float((row or {}).get("Actual K"), None)))

def _k_learning_row_line(row):
    return safe_float((row or {}).get("final_line"), safe_float((row or {}).get("line"), safe_float((row or {}).get("Line"), None)))

def build_k_v72_learning_profiles(results=None, save=True):
    """Build persistent bucket, pitcher, and confidence calibration from graded history.

    It learns model bias classes only from completed K grades. It is deliberately capped
    so it cannot overfit one slate.
    """
    try:
        results = load_json(RESULT_LOG, []) if results is None else (results or [])
        bucket = {}
        pitcher = {}
        conf = {}
        def upd(d, key, err, win, side=None):
            if key not in d:
                d[key] = {"samples": 0, "wins": 0, "err_sum": 0.0, "abs_err_sum": 0.0, "over_samples": 0, "under_samples": 0}
            rec = d[key]
            rec["samples"] += 1
            rec["wins"] += 1 if win else 0
            rec["err_sum"] += float(err)
            rec["abs_err_sum"] += abs(float(err))
            if str(side).upper() == "OVER":
                rec["over_samples"] += 1
            elif str(side).upper() == "UNDER":
                rec["under_samples"] += 1
        usable = 0
        for r in results:
            if not isinstance(r, dict):
                continue
            gr = str(r.get("graded_result") or "").upper()
            if gr not in {"WIN", "LOSS"}:
                continue
            actual = _k_learning_row_actual(r)
            proj = _k_learning_row_projection(r)
            line = _k_learning_row_line(r)
            if actual is None or proj is None:
                continue
            err = float(actual) - float(proj)  # negative = model too high
            win = gr == "WIN"
            side = str(r.get("pick_side") or r.get("model_side") or "").upper()
            bkey = _k_learning_line_bucket(line)
            upd(bucket, bkey, err, win, side)
            ckey = _k_learning_conf_bucket(r.get("fair_probability"))
            upd(conf, ckey, err, win, side)
            pkey = _k_learning_pitcher_key(r)
            if pkey:
                upd(pitcher, pkey, err, win, side)
            usable += 1
        def finish(d, max_adj=0.40):
            out = {}
            for k, rec in d.items():
                n = int(rec.get("samples", 0))
                if n <= 0:
                    continue
                avg_err = rec["err_sum"] / n
                # Capped correction: add correction to projection; if avg_err is negative, lower future projections.
                adj = clamp(avg_err * 0.28, -max_adj, max_adj)
                rec2 = dict(rec)
                rec2["avg_error"] = round(avg_err, 3)
                rec2["mae"] = round(rec["abs_err_sum"] / n, 3)
                rec2["win_rate"] = round(rec["wins"] / n, 4)
                rec2["projection_adjustment"] = round(adj, 3)
                rec2["updated_at"] = now_iso()
                out[k] = rec2
            return out
        profiles = {
            "version": "K_V72_LEARNING_GUARD_DANGER",
            "samples": usable,
            "bucket": finish(bucket, max_adj=0.35),
            "pitcher": finish(pitcher, max_adj=0.30),
            "confidence": finish(conf, max_adj=0.20),
            "updated_at": now_iso(),
        }
        if save:
            save_json(K_BUCKET_LEARNING_FILE, profiles.get("bucket", {}))
            save_json(K_PITCHER_LEARNING_FILE, profiles.get("pitcher", {}))
            save_json(K_CONFIDENCE_LEARNING_FILE, profiles.get("confidence", {}))
        return profiles
    except Exception as e:
        return {"version": "K_V72_LEARNING_GUARD_DANGER", "samples": 0, "bucket": {}, "pitcher": {}, "confidence": {}, "error": str(e)[:160]}

def load_k_v72_learning_profiles():
    try:
        # Prefer persisted files, but rebuild if missing/empty.
        bucket = load_json(K_BUCKET_LEARNING_FILE, {})
        pitcher = load_json(K_PITCHER_LEARNING_FILE, {})
        conf = load_json(K_CONFIDENCE_LEARNING_FILE, {})
        if not bucket and not pitcher and not conf:
            return build_k_v72_learning_profiles(save=True)
        return {"version": "K_V72_LEARNING_GUARD_DANGER", "bucket": bucket or {}, "pitcher": pitcher or {}, "confidence": conf or {}, "samples": _safe_learning_row_count(bucket)+_safe_learning_row_count(pitcher)}
    except Exception:
        return build_k_v72_learning_profiles(save=False)

def apply_k_v72_bucket_pitcher_calibration(mean, sims, pitcher_name=None, line=None, fair_probability=None, enabled=True):
    """Small learning correction from saved GitHub/Railway learning.

    Bucket + pitcher learning can trim or lift projection, but the total effect is capped.
    """
    try:
        if not enabled:
            return mean, sims, {"active": False, "shift": 0.0, "note": "K v72 learning disabled"}
        profiles = load_k_v72_learning_profiles()
        bkey = _k_learning_line_bucket(line)
        pkey = normalize_name(pitcher_name or "")
        ckey = _k_learning_conf_bucket(fair_probability)
        notes = []
        shift = 0.0
        b = (profiles.get("bucket") or {}).get(bkey)
        if isinstance(b, dict) and int(b.get("samples", 0)) >= 12:
            val = safe_float(b.get("projection_adjustment"), 0) or 0
            shift += val * 0.60
            notes.append(f"bucket {bkey} {val:+.2f} ({int(b.get('samples',0))} samples)")
        pr = (profiles.get("pitcher") or {}).get(pkey)
        if isinstance(pr, dict) and int(pr.get("samples", 0)) >= 3:
            val = safe_float(pr.get("projection_adjustment"), 0) or 0
            shift += val * 0.25
            notes.append(f"pitcher memory {val:+.2f} ({int(pr.get('samples',0))} samples)")
        cr = (profiles.get("confidence") or {}).get(ckey)
        if isinstance(cr, dict) and int(cr.get("samples", 0)) >= 10:
            val = safe_float(cr.get("projection_adjustment"), 0) or 0
            shift += val * 0.15
            notes.append(f"confidence bucket {ckey} {val:+.2f}")
        shift = clamp(shift, -0.28, 0.22)
        if abs(shift) < 0.01:
            return mean, sims, {"active": False, "shift": 0.0, "note": "No reliable bucket/pitcher learning adjustment"}
        sims2 = np.clip(np.asarray(sims, dtype=float) + shift, 0, None)
        return float(mean + shift), sims2, {"active": True, "shift": round(float(shift), 3), "note": "; ".join(notes)[:300], "line_bucket": bkey, "confidence_bucket": ckey}
    except Exception as e:
        return mean, sims, {"active": False, "shift": 0.0, "note": f"K v72 learning skipped: {str(e)[:120]}"}

def apply_k_v72_danger_tag(out):
    """Mark risky recommendations as DANGER without removing the side.

    This is intentionally NOT a pass gate. It keeps OVER/UNDER visible but warns "play at your risk".
    """
    try:
        out = dict(out or {})
        side = str(out.get("pick_side") or out.get("model_side") or "").upper()
        if side not in {"OVER", "UNDER"}:
            out["danger_tag"] = ""
            return out
        reasons = []
        fair = safe_float(out.get("fair_probability"), None)
        fair_pct = fair * 100 if fair is not None and fair <= 1 else fair
        abs_edge = safe_float(out.get("abs_edge"), 0) or 0
        line = safe_float(out.get("line"), None)
        conf_bucket = _k_learning_conf_bucket(fair)
        profiles = load_k_v72_learning_profiles()
        cr = (profiles.get("confidence") or {}).get(conf_bucket)
        if isinstance(cr, dict) and int(cr.get("samples", 0)) >= 10:
            wr = safe_float(cr.get("win_rate"), None)
            if wr is not None and wr < 0.48:
                reasons.append(f"confidence bucket {conf_bucket} has {wr*100:.0f}% win rate")
        if fair_pct is not None and fair_pct < 58 and abs_edge < 0.75:
            reasons.append("thin confidence + thin edge")
        if line is not None and 4.5 <= line <= 5.5 and abs_edge < 0.85:
            reasons.append("danger zone 4.5/5.5 bucket")
        vol = safe_float(out.get("volatility_score"), None)
        if vol is not None and vol >= 4.75 and abs_edge < 1.1:
            reasons.append("high volatility with limited edge")
        risk_txt = " ".join([str(out.get(k) or "") for k in ["risk_label", "risk_notes", "rookie_workload_risk", "role_label", "starter_status"]]).upper()
        if any(x in risk_txt for x in ["ROOKIE", "LOW SAMPLE", "OPENER", "BULK", "PITCH_LIMIT", "LIMITED", "HOOK"]):
            if abs_edge < 1.25:
                reasons.append("role/sample risk")
        if reasons:
            out["danger_tag"] = "‼️ DANGER"
            out["danger_note"] = "Play at your risk — " + "; ".join(reasons[:3])
            # Keep OVER/UNDER pick visible. Add warning to labels only.
            ba = str(out.get("bet_action") or "")
            if "DANGER" not in ba and ba and "PASS" not in ba.upper():
                out["bet_action"] = ba + " ‼️ DANGER"
            sig = str(out.get("signal") or "")
            if sig and "DANGER" not in sig and "PASS" not in sig.upper():
                out["signal"] = sig + " ‼️"
            rn = str(out.get("risk_notes") or "")
            out["risk_notes"] = (rn + "; " if rn else "") + out["danger_note"]
        else:
            out["danger_tag"] = ""
            out["danger_note"] = ""
        return out
    except Exception:
        return out

def sync_graded_history_csv_from_result_log():
    """Persist merged graded history to learning_data/graded_history.csv with safe row guard."""
    try:
        results = load_json(RESULT_LOG, [])
        rows = []
        for r in results:
            if not isinstance(r, dict):
                continue
            gr = str(r.get("graded_result") or "").upper()
            if gr not in {"WIN", "LOSS", "NO LINE"}:
                continue
            rows.append({
                "Date": str(r.get("date") or r.get("game_date") or r.get("graded_at") or "")[:10],
                "Pitcher": r.get("pitcher") or r.get("player"),
                "Pick": ("O" if str(r.get("pick_side")).upper()=="OVER" else "U" if str(r.get("pick_side")).upper()=="UNDER" else str(r.get("pick_side") or "")) + (" " + str(r.get("line")) if r.get("line") is not None else ""),
                "Projection": r.get("final_projection", r.get("projection")),
                "Line": r.get("final_line", r.get("line")),
                "Actual_K": r.get("actual", r.get("actual_k")),
                "Actual_IP": r.get("actual_ip"),
                "Result": gr,
                "Source": r.get("grading_source", r.get("actual_result_source", "APP_RESULT_LOG")),
                "UpdatedAt": now_iso(),
            })
        if not rows:
            return False
        df = pd.DataFrame(rows).drop_duplicates(subset=["Date", "Pitcher", "Pick", "Actual_K"], keep="last")
        targets = []
        for base in [os.getcwd(), os.path.dirname(__file__) if "__file__" in globals() else os.getcwd()]:
            targets.append(os.path.join(base, "learning_data", GRADED_HISTORY_CSV_NAME))
        ok = False
        for t in dict.fromkeys(targets):
            ok = safe_write_learning_csv(t, df) or ok
        try:
            st.session_state["v72_graded_history_csv_rows"] = len(df)
        except Exception:
            pass
        return ok
    except Exception:
        return False

# =========================
# SAVED MANUAL ODDS + NO-VIG HELPERS
# =========================
def american_to_implied_prob(price):
    """Convert American odds to implied probability as a decimal."""
    x = safe_float(str(price).replace("+", ""), None)
    if x is None or x == 0:
        return None
    if x > 0:
        return 100.0 / (x + 100.0)
    return abs(x) / (abs(x) + 100.0)

def no_vig_two_way(over_price, under_price):
    """Return no-vig over/under probabilities for a paired two-way market."""
    o = american_to_implied_prob(over_price)
    u = american_to_implied_prob(under_price)
    if o is None or u is None or (o + u) <= 0:
        return {"over": None, "under": None, "vig": None}
    total = o + u
    return {"over": o / total, "under": u / total, "vig": total - 1.0}

def _pct_display(v):
    x = safe_float(v, None)
    if x is None:
        return "—"
    if abs(x) <= 1:
        x *= 100.0
    return f"{x:.1f}%"

def _manual_saved_key(row):
    """Stable key for saved manual odds. Uses pitcher + line so old slates do not fight new lines."""
    return (
        normalize_name((row or {}).get("Pitcher") or (row or {}).get("pitcher") or ""),
        None if safe_float((row or {}).get("Line"), None) is None else round(float(safe_float((row or {}).get("Line"), None)), 2),
    )

def _manual_saved_name_key(row):
    return normalize_name((row or {}).get("Pitcher") or (row or {}).get("pitcher") or "")

def _clean_manual_odds_row(r, keep_blank=False):
    """Clean one manual odds row. Blank odds are ignored unless keep_blank is explicitly True."""
    if not isinstance(r, dict):
        return None
    name = str(r.get("Pitcher") or r.get("pitcher") or "").strip()
    line = safe_float(r.get("Line") if r.get("Line") is not None else r.get("line"), None)
    if not name or line is None:
        return None
    over = _fmt_manual_price(r.get("Over Odds") if r.get("Over Odds") is not None else r.get("over_odds"))
    under = _fmt_manual_price(r.get("Under Odds") if r.get("Under Odds") is not None else r.get("under_odds"))
    if not keep_blank and not over and not under:
        return None
    return {
        "Pitcher": name,
        "Matchup": str(r.get("Matchup") or r.get("matchup") or ""),
        "Line": round(float(line), 1),
        "Over Odds": over,
        "Under Odds": under,
        "Book": str(r.get("Book") or r.get("book") or "Manual"),
        "Saved At": california_now().strftime("%Y-%m-%d %H:%M:%S PT") if "california_now" in globals() else datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }

def load_saved_manual_odds_rows():
    """Load saved manual odds from primary, backup, or local fallback."""
    for path in [SAVED_ODDS_FILE, SAVED_ODDS_BACKUP_FILE, SAVED_ODDS_LOCAL_FILE]:
        rows = load_json(path, [])
        if isinstance(rows, list) and rows:
            cleaned = []
            seen = set()
            for r in rows:
                cr = _clean_manual_odds_row(r, keep_blank=False)
                if not cr:
                    continue
                k = _manual_saved_key(cr)
                if k in seen:
                    continue
                seen.add(k)
                cleaned.append(cr)
            if cleaned:
                return cleaned
    return []

def save_manual_odds_rows(rows):
    """Merge-save manual odds without letting blank rows erase previously saved prices."""
    existing = load_saved_manual_odds_rows()
    merged = {}
    order = []
    for r in existing:
        cr = _clean_manual_odds_row(r, keep_blank=False)
        if not cr:
            continue
        k = _manual_saved_key(cr)
        merged[k] = cr
        order.append(k)

    for r in rows or []:
        cr = _clean_manual_odds_row(r, keep_blank=False)
        if not cr:
            continue
        k = _manual_saved_key(cr)
        prev = merged.get(k, {})
        if not cr.get("Over Odds") and prev.get("Over Odds"):
            cr["Over Odds"] = prev.get("Over Odds")
        if not cr.get("Under Odds") and prev.get("Under Odds"):
            cr["Under Odds"] = prev.get("Under Odds")
        merged[k] = cr
        if k not in order:
            order.append(k)

    cleaned = [merged[k] for k in order if k in merged]
    for path in [SAVED_ODDS_FILE, SAVED_ODDS_BACKUP_FILE, SAVED_ODDS_LOCAL_FILE]:
        save_json(path, cleaned)
    return cleaned

def log_source_request(source, status, message=""):
    rows = load_json(REQUEST_LOG_FILE, [])
    rows.append({
        "time": now_iso(),
        "source": str(source)[:180],
        "status": str(status)[:80],
        "message": str(message)[:350]
    })
    save_json(REQUEST_LOG_FILE, rows[-500:])

def strip_accents(text):
    """Normalize accents so Underdog names like Sánchez match MLB names like Sanchez."""
    try:
        return "".join(
            ch for ch in unicodedata.normalize("NFKD", str(text or ""))
            if not unicodedata.combining(ch)
        )
    except Exception:
        return str(text or "")

def normalize_name(name):
    s = strip_accents(name).lower().strip()
    for ch in [".", ",", "'", "-", "_", " jr", " sr", " ii", " iii", " iv"]:
        s = s.replace(ch, " ")
    return " ".join(s.split())

def name_score(a, b):
    """Robust player-name match.

    Handles full names, abbreviations, and Underdog initial + last-name display:
    - Cristopher Sanchez vs C. Sánchez
    - Gavin Williams vs G. Williams
    - Jacob deGrom vs J. deGrom
    """
    a_norm, b_norm = normalize_name(a), normalize_name(b)
    if not a_norm or not b_norm:
        return 0.0
    if a_norm == b_norm:
        return 1.0
    if a_norm in b_norm or b_norm in a_norm:
        return 0.94

    a_parts, b_parts = a_norm.split(), b_norm.split()
    if a_parts and b_parts:
        a_first, b_first = a_parts[0], b_parts[0]
        a_last, b_last = a_parts[-1], b_parts[-1]

        # Exact last-name + first-initial match, e.g. "Cristopher Sanchez" vs "C Sanchez".
        if a_last == b_last and a_first[:1] == b_first[:1]:
            return 0.93

        # Multi-word last names / particles still get strong credit if the last token and initial match.
        if a_last == b_last:
            return max(0.82, difflib.SequenceMatcher(None, a_norm, b_norm).ratio())

    return difflib.SequenceMatcher(None, a_norm, b_norm).ratio()

def is_pitcher_k_text(text):
    t = str(text or "").lower()
    return (
        "strikeout" in t
        or "strike out" in t
        or "pitcher k" in t
        or t in ["ks", "k", "pitcher strikeouts"]
    ) and not any(bad in t for bad in ["batter", "hitter"])

def is_bad_sport_text(text):
    """Hard block non-MLB/basketball contamination from prop feeds."""
    t = f" {str(text or '').lower()} "
    bad_terms = [
        " nba", " nba_", "basketball", "wnba", "nfl", "football", "nhl",
        "soccer", "tennis", "golf", "college basketball", "ncaab"
    ]
    return any(x in t for x in bad_terms)

def is_bad_k_market_text(text):
    """Reject non-pitcher-K or alternate/novelty markets that can carry misleading values."""
    t = str(text or "").lower()
    bad_terms = [
        "batter", "hitter", "team strikeouts", "fantasy points", "fantasy score",
        "runs+rbi", "hits+runs+rbi", "total bases", "stolen base", "walks allowed",
        "earned runs", "outs recorded", "pitching outs", "hits allowed", "runs allowed",
        "single", "double", "home run", "rbi", "runs scored", "combo", "rival",
        "special", "discount", "alternative", "alt "
    ]
    return any(x in t for x in bad_terms)

@st.cache_data(ttl=300, show_spinner=False)
def safe_get_json(url, params=None, timeout=14, headers=None):
    try:
        h = {
            "User-Agent": "Mozilla/5.0 MLBKPropEngine/refresh-save-build",
            "Accept": "application/json,text/plain,*/*",
        }
        if headers:
            h.update(headers)
        r = requests.get(url, params=params, timeout=timeout, headers=h)
        if r.status_code != 200:
            log_source_request(url, f"HTTP {r.status_code}", r.text[:250])
            return None
        try:
            return r.json()
        except Exception as e:
            log_source_request(url, "BAD_JSON", str(e))
            return None
    except Exception as e:
        log_source_request(url, "REQUEST_ERROR", str(e))
        return None

def baseball_ip_to_float(ip):
    if ip is None:
        return None
    try:
        s = str(ip)
        if "." not in s:
            return float(s)
        whole, frac = s.split(".", 1)
        outs = int(frac[:1]) if frac else 0
        if outs not in [0, 1, 2]:
            return float(s)
        return int(whole) + outs / 3
    except Exception:
        return None

def get_first_stat_split(data):
    if not isinstance(data, dict):
        return None
    stats = data.get("stats") or []
    if not stats or not isinstance(stats[0], dict):
        return None
    splits = stats[0].get("splits") or []
    if not splits or not isinstance(splits[0], dict):
        return None
    return splits[0]

def flatten_json(obj):
    items = []
    if isinstance(obj, dict):
        items.append(obj)
        for v in obj.values():
            items.extend(flatten_json(v))
    elif isinstance(obj, list):
        for x in obj:
            items.extend(flatten_json(x))
    return items

def first_value(d, keys):
    for k in keys:
        if isinstance(d, dict) and k in d and d[k] not in [None, ""]:
            return d[k]
    return None

# =========================
# BETTING MATH
# =========================
def poisson_over_probability(lam, line):
    lam = safe_float(lam, 0)
    line = safe_float(line)
    if line is None or lam <= 0:
        return None
    k = int(math.floor(line))
    prob_under_or_equal = sum((lam ** i) * exp(-lam) / factorial(i) for i in range(k + 1))
    return float(clamp(1 - prob_under_or_equal, 0.001, 0.999))

def american_to_implied(price):
    price = safe_float(price)
    if price is None:
        return None
    if price > 0:
        return 100 / (price + 100)
    return abs(price) / (abs(price) + 100)

def decimal_odds(odds):
    odds = safe_float(odds)
    if odds is None:
        return None
    if odds > 0:
        return 1 + odds / 100
    return 1 + 100 / abs(odds)

def expected_value(prob, odds):
    dec = decimal_odds(odds)
    if prob is None or dec is None:
        return None
    return (prob * (dec - 1)) - (1 - prob)

def kelly_fraction(prob, odds):
    dec = decimal_odds(odds)
    if prob is None or dec is None:
        return 0.0
    b = dec - 1
    q = 1 - prob
    if b <= 0:
        return 0.0
    return float(clamp(((b * prob) - q) / b, 0, 0.25))

def paired_no_vig_probability(rows, target_row):
    price = safe_float(target_row.get("Price"))
    listed = american_to_implied(price)
    if listed is None:
        return None
    provider = str(target_row.get("Provider", target_row.get("Source", ""))).lower()
    line = safe_float(target_row.get("Line"))
    side = str(target_row.get("Side", "")).lower()
    if line is None or not side:
        return listed
    want = "under" if "over" in side else "over" if "under" in side else None
    if not want:
        return listed
    opposite = None
    for r in rows or []:
        if safe_float(r.get("Line")) != line:
            continue
        if str(r.get("Provider", r.get("Source", ""))).lower() != provider:
            continue
        if want in str(r.get("Side", "")).lower():
            opposite = american_to_implied(r.get("Price"))
            break
    if opposite is None:
        return listed
    denom = listed + opposite
    return listed / denom if denom > 0 else listed

