# v11.10 DEEP BULLPEN / UMPIRE LEARNING
# =========================
def context_learn_bucket(value, cuts, labels):
    return calibration_bucket(value, cuts, labels)

def bullpen_context_key_from_usage(usage):
    usage = usage or {}
    label = str(usage.get("label") or "UNKNOWN").upper()
    pitches = safe_float(usage.get("bullpen_pitches"), 0) or 0
    ip = safe_float(usage.get("bullpen_ip"), 0) or 0
    b2b = safe_float(usage.get("back_to_back_relief_appearances"), 0) or 0
    p_bucket = context_learn_bucket(pitches, [120, 180, 240, 300], ["p<=120", "p121-180", "p181-240", "p241-300", "p300+"])
    ip_bucket = context_learn_bucket(ip, [8, 12, 18], ["ip<=8", "ip9-12", "ip13-18", "ip18+"])
    b2b_bucket = context_learn_bucket(b2b, [0, 1, 3], ["b2b0", "b2b1", "b2b2-3", "b2b4+"])
    return f"{label}|{p_bucket}|{ip_bucket}|{b2b_bucket}"

def umpire_context_key(name):
    nm = normalize_name(name or "Unknown").replace(" ", "_")
    return nm or "unknown"

def _load_context_model(path):
    data = load_json(path, {})
    if not isinstance(data, dict):
        return {}
    return data

def _save_context_model(path, data):
    save_json(path, data)

def _smoothed_error_factor(model, key, metric="bf_error", min_samples=10, max_adj=0.03, denominator=22.0):
    rec = (model or {}).get(str(key), {})
    n = int(rec.get("count") or 0)
    if n < min_samples:
        return 1.0, f"learning warming up ({n}/{min_samples})", n
    avg_err = safe_float(rec.get(metric), 0.0) or 0.0
    # shrink toward 0 so a few outliers do not swing projections.
    reliability = n / (n + CONTEXT_PRIOR_STRENGTH)
    pct = clamp((avg_err / max(denominator, 1.0)) * reliability, -max_adj, max_adj)
    return float(1.0 + pct), f"learned {metric} {avg_err:+.2f}, n={n}, rel={reliability:.2f}", n

def bullpen_learning_bf_factor(usage):
    """Learns whether bullpen states caused BF to be over/under-projected."""
    if not usage or not usage.get("available"):
        return 1.0, "Bullpen learning neutral: usage unavailable", None
    key = bullpen_context_key_from_usage(usage)
    model = _load_context_model(BULLPEN_LEARNING_FILE)
    factor, note, n = _smoothed_error_factor(
        model,
        key,
        metric="bf_error",
        min_samples=BULLPEN_LEARN_MIN_SAMPLES,
        max_adj=BULLPEN_LEARN_MAX_BF_ADJ,
        denominator=22.0,
    )
    factor = float(clamp(factor, 1.0 - BULLPEN_LEARN_MAX_BF_ADJ, 1.0 + BULLPEN_LEARN_MAX_BF_ADJ))
    return factor, f"Bullpen learning x{factor:.3f} [{key}] {note}", key

def umpire_learning_k_factor(name):
    """Learns if a specific umpire has caused K projection bias in graded games."""
    if not name or str(name).lower() == "unknown":
        return 1.0, "Umpire learning neutral: unknown umpire", None
    key = umpire_context_key(name)
    model = _load_context_model(UMPIRE_LEARNING_FILE)
    factor, note, n = _smoothed_error_factor(
        model,
        key,
        metric="k_error",
        min_samples=UMPIRE_LEARN_MIN_SAMPLES,
        max_adj=UMPIRE_LEARN_MAX_K_ADJ,
        denominator=5.0,
    )
    factor = float(clamp(factor, 1.0 - UMPIRE_LEARN_MAX_K_ADJ, 1.0 + UMPIRE_LEARN_MAX_K_ADJ))
    return factor, f"Umpire learning x{factor:.3f} [{key}] {note}", key

def _update_context_avg(model, key, fields):
    if key is None:
        return model
    key = str(key)
    rec = model.get(key, {"count": 0})
    old_n = int(rec.get("count") or 0)
    new_n = old_n + 1
    rec["count"] = new_n
    rec["last_updated"] = now_iso()
    for field, value in fields.items():
        val = safe_float(value)
        if val is None:
            continue
        old_avg = safe_float(rec.get(field), 0.0) or 0.0
        rec[field] = round(old_avg + ((val - old_avg) / new_n), 5)
    model[key] = rec
    return model

def get_actual_pitcher_workload(game_pk, pitcher_id):
    """Return actual K/BF/pitches/IP after game final for deeper learning.

    Also returns actual pitcher team context so Manager Pull Learning does not fall
    into UNKNOWN when the saved snapshot did not carry a clean team field.
    """
    box = safe_get_json(f"{MLB_BASE}/game/{game_pk}/boxscore")
    if not box:
        return {}
    for side in ["home", "away"]:
        team_node = (box.get("teams", {}) or {}).get(side, {}) or {}
        team_info = team_node.get("team", {}) or {}
        team_abbrev = team_info.get("abbreviation") or team_info.get("teamCode") or team_info.get("fileCode") or team_info.get("name")
        players = team_node.get("players", {})
        for p in players.values():
            person = p.get("person", {})
            if str(person.get("id")) == str(pitcher_id):
                pitching = p.get("stats", {}).get("pitching", {}) or {}
                workload = {
                    "actual": safe_float(pitching.get("strikeOuts")),
                    "actual_bf": safe_float(pitching.get("battersFaced")),
                    "actual_pitches": safe_float(pitching.get("numberOfPitches", pitching.get("pitchesThrown", pitching.get("pitchCount")))),
                    "actual_ip": baseball_ip_to_float(pitching.get("inningsPitched")),
                    "actual_er": safe_float(pitching.get("earnedRuns")),
                    "actual_hits": safe_float(pitching.get("hits")),
                    "actual_bb": safe_float(pitching.get("baseOnBalls")),
                    "actual_hr": safe_float(pitching.get("homeRuns")),
                    "actual_team": team_abbrev,
                    "actual_team_id": team_info.get("id"),
                    "actual_team_side": side,
                }
                try:
                    workload.update(get_actual_first_inning_pitcher_workload(game_pk, pitcher_id))
                except Exception:
                    pass
                return workload
    return {}


# -----------------------------------------------------------------------------
# First Inning Layer 3.0 (TRACKING / WORKLOAD CONFIDENCE ONLY)
# -----------------------------------------------------------------------------
# This layer is intentionally conservative. It DOES NOT directly move K projection,
# Line-Aware Smart Final K Projection, BF formula, IP formula, or official decisions.
# It starts as day-1 tracking, then becomes a confidence/workload context once enough
# graded samples exist.

def get_actual_first_inning_pitcher_workload(game_pk, pitcher_id):
    """Return first-inning workload for a pitcher from MLB play-by-play.

    Fields are saved into the graded pick/result log so the model can learn first
    inning efficiency over time. If play-by-play is unavailable, safely returns {}.
    """
    data = safe_get_json(f"{MLB_BASE}/game/{game_pk}/feed/live")
    if not data:
        return {}
    plays = (((data.get("liveData") or {}).get("plays") or {}).get("allPlays") or [])
    pitcher_id_s = str(pitcher_id)
    pitches = 0
    batters_faced = 0
    ks = 0
    walks = 0
    hits = 0
    runs = 0
    events_seen = 0
    for play in plays:
        try:
            about = play.get("about") or {}
            if int(about.get("inning") or 0) != 1:
                continue
            matchup = play.get("matchup") or {}
            pitcher = matchup.get("pitcher") or {}
            if str(pitcher.get("id")) != pitcher_id_s:
                continue
            batters_faced += 1
            events_seen += 1
            for ev in (play.get("playEvents") or []):
                details = ev.get("details") or {}
                if ev.get("isPitch") or details.get("isPitch"):
                    pitches += 1
            result = play.get("result") or {}
            event_type = str(result.get("eventType") or result.get("event") or "").lower()
            if "strikeout" in event_type:
                ks += 1
            if event_type in ["walk", "intent_walk", "hit_by_pitch"] or "walk" in event_type:
                walks += 1
            if event_type in ["single", "double", "triple", "home_run"]:
                hits += 1
            rbi = safe_float(result.get("rbi"), 0) or 0
            runs += int(max(0, rbi))
        except Exception:
            continue
    if events_seen <= 0 and pitches <= 0:
        return {}
    return {
        "first_inning_pitches_actual": int(pitches),
        "first_inning_bf_actual": int(batters_faced),
        "first_inning_k_actual": int(ks),
        "first_inning_bb_actual": int(walks),
        "first_inning_hits_actual": int(hits),
        "first_inning_runs_actual": int(runs),
        "first_inning_tracked_at": now_iso(),
    }


def _first_inning_label(avg_pitches, samples=0):
    if not samples or avg_pitches is None:
        return "FI_TRACK_ONLY"
    x = float(avg_pitches)
    if x < 12:
        return "FI_ELITE_EFFICIENT_START"
    if x <= 15:
        return "FI_GOOD_START"
    if x <= 18:
        return "FI_AVERAGE_START"
    if x <= 22:
        return "FI_STRESS_START"
    return "FI_DANGER_HIGH_PITCH_1ST"


def _first_inning_confidence(samples):
    n = int(samples or 0)
    if n <= 0:
        return "DAY_1_TRACK_ONLY"
    if n < 3:
        return "LOW_SAMPLE_TRACK_ONLY"
    if n < 6:
        return "SMALL_SAMPLE_DISPLAY_ONLY"
    if n < 10:
        return "USABLE_CONTEXT_LIGHT"
    return "STABLE_CONTEXT"


def build_first_inning_efficiency_profile(pitcher_id=None, pitcher_name=None, results=None):
    """Build first-inning efficiency profile from graded results.

    Design: informational/context only. projection_impact_k is always 0.00 so
    tomorrow's K projections are protected while data accumulates.
    """
    results = load_json(RESULT_LOG, []) if results is None else (results or [])
    rows = []
    pid_s = str(pitcher_id) if pitcher_id is not None else ""
    name_s = str(pitcher_name or "").strip().lower()
    for r in results:
        try:
            if pid_s and str(r.get("pitcher_id") or r.get("Pitcher ID") or "") != pid_s:
                # If pitcher ID is missing in older rows, allow exact name match below.
                if name_s and str(r.get("pitcher") or r.get("Pitcher") or "").strip().lower() != name_s:
                    continue
            elif not pid_s and name_s and str(r.get("pitcher") or r.get("Pitcher") or "").strip().lower() != name_s:
                continue
            fp = safe_float(r.get("first_inning_pitches_actual"), None)
            if fp is None:
                continue
            rows.append(r)
        except Exception:
            continue
    samples = len(rows)
    def avg_field(field):
        vals = [safe_float(x.get(field), None) for x in rows]
        vals = [v for v in vals if v is not None]
        return None if not vals else round(float(np.mean(vals)), 2)
    avg_p = avg_field("first_inning_pitches_actual")
    avg_bf = avg_field("first_inning_bf_actual")
    avg_k = avg_field("first_inning_k_actual")
    avg_bb = avg_field("first_inning_bb_actual")
    label = _first_inning_label(avg_p, samples)
    confidence = _first_inning_confidence(samples)
    score = 50.0
    if avg_p is not None and samples >= 3:
        # Score is a workload confidence clue only. It does not alter projections.
        score = 50.0 + clamp((16.5 - float(avg_p)) * 3.0, -25, 25)
    score = round(float(clamp(score, 20, 80)), 1)
    if samples <= 0:
        note = "First inning layer is live but starts at Day 1: tracking only; no projection impact."
    else:
        note = f"{label}: {samples} graded sample(s), avg 1st inning pitches {avg_p}; confidence {confidence}. Projection impact 0.00 K."
    return {
        "samples": samples,
        "avg_pitches": avg_p,
        "avg_bf": avg_bf,
        "avg_k": avg_k,
        "avg_bb": avg_bb,
        "score": score,
        "label": label,
        "confidence": confidence,
        "projection_impact_k": 0.0,
        "note": note,
    }


def build_decision_tier_3_0(p, d=None):
    """Non-invasive decision tier display.

    This creates a clearer middle ground between hard PASS and official plays.
    It does not overwrite the existing Decision, Line-Aware Smart Decision, K PROJ,
    projection, IP, BF, or saved grading logic.
    """
    d = d or {}
    decision = str(d.get("decision") or p.get("Line-Aware Smart Decision") or p.get("Decision") or "").upper()
    lean = str(d.get("lean_side") or p.get("Model Lean") or p.get("market_lean") or "").upper()
    edge = abs(safe_float(d.get("line_edge"), safe_float(p.get("Line-Aware Smart Edge"), safe_float(p.get("Edge Gap"), 0))) or 0)
    hit = safe_float(d.get("hit_rate"), None)
    role_score = safe_float(d.get("role_score"), safe_float(p.get("Role Score"), 50)) or 50
    starter_score = safe_float(d.get("starter_score"), safe_float(p.get("Starter Score"), 50)) or 50
    conflict = safe_float(p.get("conflict_score_2_2") or p.get("Conflict Score 2.2") or p.get("conflict_score"), 0) or 0
    market_agree = str(p.get("market_agreement") or p.get("Market Agree") or "").upper()
    fi_label = str(p.get("first_inning_efficiency_label") or "")

    reasons = []
    if "OVER" in lean:
        lean_side = "OVER"
    elif "UNDER" in lean:
        lean_side = "UNDER"
    else:
        lean_side = "LEAN"

    if "🔥" in decision or decision.startswith("✅ OVER") or decision.startswith("✅ UNDER"):
        tier = "OFFICIAL"
    elif "OVER LEAN" in decision or "UNDER LEAN" in decision:
        tier = "PLAYABLE"
    elif "PASS" in decision and edge >= 0.45:
        tier = f"PASS-LEAN {lean_side}"
        reasons.append("Projection still has directional lean; not a dead play")
    elif "PASS" in decision:
        tier = "TRACK ONLY"
    else:
        tier = "TRACK ONLY"

    if conflict >= 3:
        if tier == "OFFICIAL":
            tier = "PLAYABLE"
        elif tier == "PLAYABLE":
            tier = f"PASS-LEAN {lean_side}"
        reasons.append("conflict score elevated")
    if market_agree in ["DISAGREE", "MARKET_DISAGREE"] and tier == "OFFICIAL":
        tier = "PLAYABLE"
        reasons.append("market disagreement")
    if role_score < 45 or starter_score < 45:
        tier = "TRACK ONLY" if "PASS-LEAN" in tier or tier == "PLAYABLE" else tier
        reasons.append("role/starter confidence low")
    if "DANGER" in fi_label and tier == "OFFICIAL":
        tier = "PLAYABLE"
        reasons.append("first inning stress profile warning")
    if edge < 0.25 and "PASS" in decision:
        tier = "AVOID"
        reasons.append("edge too thin")
    return {
        "decision_tier_3_0": tier,
        "decision_tier_3_0_note": "; ".join(reasons) if reasons else "Tier is display-only; core projection unchanged.",
    }


@st.cache_data(ttl=86400, show_spinner=False)
def get_team_manager_name_v11_20(team_id=None, team_abbrev=None):
    """Best-effort live MLB manager resolver.

    This is used for Manager Pull Learning labels only. It does not change
    K projections, IP projections, BF projections, or pick decisions.
    If MLB does not expose coach data for the team, it safely falls back
    to TEAM:<abbr/id> instead of UNKNOWN.
    """
    try:
        team_id_val = safe_int(team_id, None)
        if team_id_val is not None:
            for url in [
                f"{MLB_BASE}/teams/{team_id_val}/coaches",
                f"{MLB_BASE}/team/{team_id_val}/coaches",
            ]:
                data = safe_get_json(url, timeout=10)
                if not isinstance(data, dict):
                    continue
                candidates = []
                # MLB endpoints may use coaches, roster, or staff depending on season/API shape.
                for key in ["coaches", "roster", "staff", "people"]:
                    val = data.get(key)
                    if isinstance(val, list):
                        candidates.extend(val)
                for item in candidates:
                    if not isinstance(item, dict):
                        continue
                    job = str(item.get("job") or item.get("jobTitle") or item.get("title") or item.get("position") or "").lower()
                    person = item.get("person") if isinstance(item.get("person"), dict) else item
                    name = person.get("fullName") or person.get("name") or item.get("name")
                    if name and ("manager" in job or job in ["mgr"]):
                        return str(name).strip()
        abbr = str(team_abbrev or team_id or "UNKNOWN").strip()
        return f"TEAM:{abbr}" if abbr and abbr.upper() != "UNKNOWN" else "UNKNOWN"
    except Exception:
        abbr = str(team_abbrev or team_id or "UNKNOWN").strip()
        return f"TEAM:{abbr}" if abbr and abbr.upper() != "UNKNOWN" else "UNKNOWN"

def manager_learning_key_from_pick_v11_20(pick):
    """Return the best available manager-learning key without affecting projections."""
    if not isinstance(pick, dict):
        return "UNKNOWN"
    for k in ["manager_name", "Manager", "manager", "manager_pull_learning_key"]:
        val = pick.get(k)
        if val and str(val).strip().upper() not in ["UNKNOWN", "NAN", "NONE"]:
            return str(val).strip()
    team_id = pick.get("actual_team_id") or pick.get("team_id") or pick.get("Team ID")
    team_abbr = pick.get("actual_team") or pick.get("team") or pick.get("pitcher_team") or pick.get("Team") or pick.get("team_abbrev")
    return get_team_manager_name_v11_20(team_id=team_id, team_abbrev=team_abbr)

def update_deep_context_learning_after_grade(pick):
    """Accumulates post-game errors for future bullpen and umpire corrections."""
    if not isinstance(pick, dict):
        return
    actual = safe_float(pick.get("actual"))
    projection = safe_float(pick.get("projection"))
    actual_bf = safe_float(pick.get("actual_bf"))
    expected_bf = safe_float(pick.get("expected_bf"))
    if actual is None or projection is None:
        return

    feature_bank = load_json(GRADED_FEATURES_FILE, [])
    feature_bank.append({
        "pick_id": pick.get("pick_id"),
        "graded_at": pick.get("graded_at") or now_iso(),
        "pitcher": pick.get("pitcher"),
        "pitcher_id": pick.get("pitcher_id"),
        "line": pick.get("line"),
        "pick_side": pick.get("pick_side"),
        "projection": projection,
        "actual": actual,
        "k_error": actual - projection,
        "expected_bf": expected_bf,
        "actual_bf": actual_bf,
        "bf_error": None if actual_bf is None or expected_bf is None else actual_bf - expected_bf,
        "umpire": pick.get("umpire"),
        "ump_factor": pick.get("ump_factor"),
        "bullpen_status": pick.get("bullpen_status"),
        "bullpen_bf_factor": pick.get("bullpen_bf_factor"),
        "bullpen_recent_pitches": pick.get("bullpen_recent_pitches"),
        "bullpen_recent_ip": pick.get("bullpen_recent_ip"),
        "bullpen_back_to_back_relievers": pick.get("bullpen_back_to_back_relievers"),
        "weather_factor": pick.get("weather_factor"),
        "manager_hook_status": pick.get("manager_hook_status") or pick.get("manager_hook"),
        "graded_result": pick.get("graded_result"),
    })
    save_json(GRADED_FEATURES_FILE, feature_bank[-FEATURE_BANK_RECENT_LIMIT:])

    # Umpire learning: actual Ks minus projected Ks for that umpire.
    ump_key = umpire_context_key(pick.get("umpire")) if pick.get("umpire") and str(pick.get("umpire")).lower() != "unknown" else None
    if ump_key:
        model = _load_context_model(UMPIRE_LEARNING_FILE)
        model = _update_context_avg(model, ump_key, {"k_error": actual - projection})
        _save_context_model(UMPIRE_LEARNING_FILE, model)

    # Bullpen learning: actual BF minus projected BF for that bullpen workload bucket.
    bp_label = pick.get("bullpen_status")
    if bp_label and actual_bf is not None and expected_bf is not None:
        usage = {
            "available": True,
            "label": bp_label,
            "bullpen_pitches": pick.get("bullpen_recent_pitches"),
            "bullpen_ip": pick.get("bullpen_recent_ip"),
            "back_to_back_relief_appearances": pick.get("bullpen_back_to_back_relievers"),
        }
        bp_key = bullpen_context_key_from_usage(usage)
        model = _load_context_model(BULLPEN_LEARNING_FILE)
        model = _update_context_avg(model, bp_key, {"bf_error": actual_bf - expected_bf, "k_error": actual - projection})
        _save_context_model(BULLPEN_LEARNING_FILE, model)


# =========================
# v11.2 CONTEXT GUARDRAIL LAYER
# =========================
def opponent_k_rank_label_from_rate(opponent_k_rate):
    """Convert real lineup/team K rate into a coarse rank-style label.

    This is not a fake rank table. It is derived from the same real opponent K%
    already used by the app. Lower rank number = more strikeout-friendly matchup.
    """
    ok = safe_float(opponent_k_rate, LEAGUE_AVG_K) or LEAGUE_AVG_K
    if ok >= LEAGUE_AVG_K + 0.040:
        return 1, "EXTREME_HIGH_K"
    if ok >= LEAGUE_AVG_K + 0.030:
        return 5, "HIGH_K"
    if ok >= LEAGUE_AVG_K + 0.015:
        return 10, "ABOVE_AVG_K"
    if ok <= LEAGUE_AVG_K - 0.035:
        return 30, "EXTREME_CONTACT"
    if ok <= LEAGUE_AVG_K - 0.020:
        return 25, "LOW_K"
    return 15, "NEUTRAL_K"

def vegas_total_leash_ks_adjustment(total):
    """Small Ks projection nudge from run environment.

    Lower totals usually help starters work deeper. Higher totals increase early-hook risk.
    Kept very small so it cannot overpower real lineups, Statcast, or leash model.
    """
    t = safe_float(total)
    if t is None:
        return 0.0, "Vegas total unavailable; neutral"
    if t <= 7.5:
        return 0.18, "Low Vegas total; small Ks leash boost"
    if t >= 9.5:
        return -0.18, "High Vegas total; small Ks leash cut"
    return 0.0, "Neutral Vegas total"

def elite_pitcher_guard_ks_adjustment(k9, k_rate, opponent_k_rate):
    """Protects elite K pitchers from being under-projected in strong K matchups.

    This is capped and only adds a small amount. It does not auto-bet overs.
    """
    k9 = safe_float(k9)
    kr = safe_float(k_rate)
    opp_rank, opp_label = opponent_k_rank_label_from_rate(opponent_k_rate)

    if k9 is None or kr is None:
        return 0.0, "Elite pitcher guard unavailable"

    if k9 >= 10.5 and kr >= 0.29:
        if opp_rank <= 10:
            return 0.35, f"Elite pitcher guard vs {opp_label}; capped boost"
        return 0.22, "Elite pitcher guard; capped boost"
    if k9 >= 9.8 and kr >= 0.27:
        return 0.16, "High-K pitcher guard; capped boost"
    return 0.0, "No elite pitcher guard"

def pitch_mix_handedness_guard_ks_adjustment(pitch_type_rows, lineup_rows):
    """Small boost when slider-heavy pitchers face many opposite/lefty bats.

    Uses real pitch type rows and real lineup rows only. If either is unavailable, neutral.
    """
    try:
        if not pitch_type_rows or not lineup_rows:
            return 0.0, "Pitch-mix handedness guard unavailable"

        slider_usage = 0.0
        for r in pitch_type_rows:
            pt = str(r.get("Pitch Type", "")).lower()
            if pt in ["sl", "slider"]:
                slider_usage = max(slider_usage, (safe_float(r.get("Usage %"), 0) or 0) / 100.0)

        # The current MLB lineup payload in this app may not always include batter handedness.
        # If handedness is absent, this stays neutral instead of guessing.
        lefties = 0
        for r in lineup_rows[:9]:
            hand = str(r.get("Bat Side", r.get("Side", r.get("Bats", "")))).upper()
            if hand.startswith("L"):
                lefties += 1

        if slider_usage > 0.32 and lefties >= 5:
            return 0.16, f"Slider-heavy pitch mix vs {lefties} lefties; capped boost"
        return 0.0, "Neutral pitch-mix handedness guard"
    except Exception as e:
        return 0.0, f"Pitch-mix handedness guard error: {e}"

def apply_context_guardrail_projection(
    projection,
    line=None,
    pitcher_profile=None,
    pitcher_k_rate=None,
    lineup_k=None,
    recent_rows=None,
    pitch_type_rows=None,
    lineup_rows=None,
    vegas_total=None,
    roof_closed=False,
    wind_in=False,
    umpire_boost=0.0,
):
    """Final small, capped projection guardrail layer.

    This layer is intentionally conservative:
    - uses only already-real inputs when available
    - never creates props or lines
    - cannot move projection by more than +/- 0.65 Ks total
    - cannot force a bet; EV/edge/no-bet filters still decide
    """
    base = safe_float(projection)
    if base is None:
        return projection, {
            "Context Guardrail Adj": 0.0,
            "Context Guardrail Notes": "Projection unavailable",
            "Opponent K Rank Label": None,
        }

    notes = []
    adj = 0.0

    lineup_k_val = safe_float(lineup_k, LEAGUE_AVG_K) or LEAGUE_AVG_K
    opp_rank, opp_label = opponent_k_rank_label_from_rate(lineup_k_val)
    notes.append(f"Opponent K rank label: {opp_label}")

    # Pull real K/9 if available
    k9 = None
    if isinstance(pitcher_profile, dict):
        k9 = pitcher_profile.get("K/9")
    kr = safe_float(pitcher_k_rate)

    a, n = elite_pitcher_guard_ks_adjustment(k9, kr, lineup_k_val)
    adj += a
    notes.append(n)

    # Real recent pitch count trend as a projection-level nudge, separate from BF factor
    vals = []
    for r in (recent_rows or [])[:3]:
        p = safe_float(r.get("Pitches"))
        if p is not None and p > 0:
            vals.append(p)
    if len(vals) >= 3:
        avg = sum(vals) / len(vals)
        if avg > 102:
            adj += 0.16
            notes.append(f"High L3 pitch-count trend ({avg:.0f}); small projection boost")
        elif avg < 88:
            adj -= 0.16
            notes.append(f"Low L3 pitch-count trend ({avg:.0f}); small projection cut")
        else:
            notes.append(f"Neutral L3 pitch-count trend ({avg:.0f})")
    else:
        notes.append("Pitch-count trend thin; neutral")

    a, n = vegas_total_leash_ks_adjustment(vegas_total)
    adj += a
    notes.append(n)

    # Weather/roof is intentionally tiny because the app already has weather caps elsewhere
    if bool(roof_closed):
        adj += 0.05
        notes.append("Roof closed; tiny environment stability boost")
    elif bool(wind_in):
        adj += 0.08
        notes.append("Wind in; tiny Ks environment boost")

    # Umpire boost must already be produced by a real umpire model. Manual boost defaults to 0.
    ub = clamp(safe_float(umpire_boost, 0.0) or 0.0, -0.15, 0.15)
    if abs(ub) > 0:
        adj += ub
        notes.append(f"Umpire guardrail adj {ub:+.2f}")

    a, n = pitch_mix_handedness_guard_ks_adjustment(pitch_type_rows, lineup_rows)
    adj += a
    notes.append(n)

    adj = float(clamp(adj, -0.65, 0.65))
    final_projection = float(clamp(base + adj, 1.0, 14.0))

    return final_projection, {
        "Context Guardrail Adj": round(adj, 2),
        "Context Guardrail Notes": " | ".join(notes),
        "Opponent K Rank": opp_rank,
        "Opponent K Rank Label": opp_label,
    }


# =========================
# v11.4 RUN-DAMAGE / SHORT-OUTING RISK LAYER
# =========================
def pitcher_run_damage_profile(pitcher_id, recent_rows=None, statcast_profile=None):
    """Advanced run-damage / short-outing risk profile.

    v11.12 upgrade:
    Uses H, R, ER, BB and HR as volume-risk signals. This does not directly
    downgrade a pitcher\'s raw K skill. It only helps estimate whether the
    starter is more likely to lose batters faced because of traffic, damage,
    pitch-count stress, or an early hook.
    """
    profile = {
        "available": False,
        "whip": None,
        "era": None,
        "h9": None,
        "bb9": None,
        "hr9": None,
        "season_hits": None,
        "season_runs": None,
        "season_er": None,
        "season_bb": None,
        "season_hr": None,
        "recent_er_avg": None,
        "recent_runs_avg": None,
        "recent_hits_avg": None,
        "recent_bb_avg": None,
        "recent_hr_avg": None,
        "recent_ip_avg": None,
        "recent_traffic_index": None,
        "risk_score": 0,
        "risk_level": "UNKNOWN",
        "bf_factor": 1.0,
        "volatility_penalty": 0.0,
        "notes": []
    }

    def add_score(points, note):
        profile["risk_score"] += int(points)
        if note:
            profile["notes"].append(str(note))

    try:
        data = safe_get_json(
            f"{MLB_BASE}/people/{pitcher_id}/stats",
            params={"stats": "season", "group": "pitching"},
            timeout=12,
        )
        split = get_first_stat_split(data)
        stat = (split or {}).get("stat", {}) if split else {}

        ip = baseball_ip_to_float(stat.get("inningsPitched"))
        h = safe_float(stat.get("hits"), 0) or 0
        r = safe_float(stat.get("runs"), 0) or 0
        er = safe_float(stat.get("earnedRuns"), 0) or 0
        bb = safe_float(stat.get("baseOnBalls"), 0) or 0
        hr = safe_float(stat.get("homeRuns"), 0) or 0

        profile["whip"] = safe_float(stat.get("whip"))
        profile["era"] = safe_float(stat.get("era"))
        profile["season_hits"] = h
        profile["season_runs"] = r
        profile["season_er"] = er
        profile["season_bb"] = bb
        profile["season_hr"] = hr

        if ip and ip > 0:
            profile["available"] = True
            profile["h9"] = h / ip * 9
            profile["bb9"] = bb / ip * 9
            profile["hr9"] = hr / ip * 9

        if profile["whip"] is not None:
            profile["available"] = True
            if profile["whip"] >= 1.55:
                add_score(4, f"Extreme WHIP {profile['whip']:.2f}")
            elif profile["whip"] >= 1.45:
                add_score(3, f"High WHIP {profile['whip']:.2f}")
            elif profile["whip"] >= HIGH_RUN_DAMAGE_WHIP:
                add_score(2, f"Elevated WHIP {profile['whip']:.2f}")

        if profile["era"] is not None:
            if profile["era"] >= 5.40:
                add_score(3, f"Extreme ERA {profile['era']:.2f}")
            elif profile["era"] >= 5.00:
                add_score(2, f"High ERA {profile['era']:.2f}")
            elif profile["era"] >= 4.25:
                add_score(1, f"Elevated ERA {profile['era']:.2f}")

        if profile["h9"] is not None:
            if profile["h9"] >= 10.5:
                add_score(3, f"Extreme H/9 {profile['h9']:.1f}")
            elif profile["h9"] >= HIGH_SEASON_H9:
                add_score(2, f"High H/9 {profile['h9']:.1f}")

        if profile["bb9"] is not None:
            if profile["bb9"] >= 4.5:
                add_score(3, f"Extreme BB/9 {profile['bb9']:.1f}")
            elif profile["bb9"] >= HIGH_SEASON_BB9:
                add_score(2, f"High BB/9 {profile['bb9']:.1f}")
            elif profile["bb9"] >= 3.2:
                add_score(1, f"Elevated BB/9 {profile['bb9']:.1f}")

        if profile["hr9"] is not None:
            if profile["hr9"] >= 1.70:
                add_score(3, f"Extreme HR/9 {profile['hr9']:.2f}")
            elif profile["hr9"] >= HIGH_SEASON_HR9:
                add_score(2, f"High HR/9 {profile['hr9']:.2f}")
            elif profile["hr9"] >= 1.10:
                add_score(1, f"Elevated HR/9 {profile['hr9']:.2f}")
    except Exception as e:
        profile["notes"].append(f"Season run-damage unavailable: {e}")

    try:
        sp = statcast_profile or {}
        hard = safe_float(sp.get("hard_hit_pct"), None)
        barrel = safe_float(sp.get("barrel_pct"), None)
        xwoba = safe_float(sp.get("xwoba"), None)
        ev = safe_float(sp.get("avg_exit_velocity"), None)
        if hard is not None:
            profile["available"] = True
            profile["savant_hard_hit_pct"] = hard * 100.0 if hard <= 1 else hard
            if hard >= 0.45:
                add_score(5, f"Official Savant hard-hit risk {hard*100:.1f}%")
            elif hard >= 0.40:
                add_score(3, f"Official Savant elevated hard-hit {hard*100:.1f}%")
        if barrel is not None:
            profile["available"] = True
            profile["savant_barrel_pct"] = barrel * 100.0 if barrel <= 1 else barrel
            if barrel >= 0.105:
                add_score(5, f"Official Savant barrel risk {barrel*100:.1f}%")
            elif barrel >= 0.080:
                add_score(3, f"Official Savant elevated barrels {barrel*100:.1f}%")
        if xwoba is not None:
            profile["available"] = True
            profile["savant_xwoba"] = xwoba
            if xwoba >= 0.350:
                add_score(4, f"Official Savant xwOBA risk {xwoba:.3f}")
            elif xwoba >= 0.325:
                add_score(2, f"Official Savant elevated xwOBA {xwoba:.3f}")
        if ev is not None:
            profile["available"] = True
            profile["savant_avg_exit_velocity"] = ev
            if ev >= 91.0:
                add_score(3, f"Official Savant exit velo risk {ev:.1f}")
    except Exception as e:
        profile["notes"].append(f"Savant run-damage unavailable: {e}")

    try:
        ers, runs, hits, walks, homers, ips = [], [], [], [], [], []
        for r in (recent_rows or [])[:5]:
            er = safe_float(r.get("ER", r.get("Earned Runs")))
            rr = safe_float(r.get("R", r.get("Runs")))
            h = safe_float(r.get("H", r.get("Hits")))
            bb = safe_float(r.get("BB", r.get("Walks", r.get("BaseOnBalls"))))
            hr = safe_float(r.get("HR", r.get("Home Runs", r.get("homeRuns"))))
            ip = safe_float(r.get("IP_float"))
            if er is not None: ers.append(er)
            if rr is not None: runs.append(rr)
            if h is not None: hits.append(h)
            if bb is not None: walks.append(bb)
            if hr is not None: homers.append(hr)
            if ip is not None: ips.append(ip)

        if ers:
            profile["recent_er_avg"] = float(np.mean(ers))
            profile["available"] = True
            if profile["recent_er_avg"] >= HIGH_RUN_DAMAGE_RECENT_ER:
                add_score(3, f"High recent ER avg {profile['recent_er_avg']:.1f}")
            elif profile["recent_er_avg"] >= 3.0:
                add_score(2, f"Elevated recent ER avg {profile['recent_er_avg']:.1f}")

        if runs:
            profile["recent_runs_avg"] = float(np.mean(runs))
            profile["available"] = True
            if profile["recent_runs_avg"] >= HIGH_RECENT_RUNS_AVG:
                add_score(3, f"High recent R avg {profile['recent_runs_avg']:.1f}")
            elif profile["recent_runs_avg"] >= 3.5:
                add_score(2, f"Elevated recent R avg {profile['recent_runs_avg']:.1f}")

        if hits:
            profile["recent_hits_avg"] = float(np.mean(hits))
            profile["available"] = True
            if profile["recent_hits_avg"] >= 7.0:
                add_score(3, f"Extreme recent H avg {profile['recent_hits_avg']:.1f}")
            elif profile["recent_hits_avg"] >= 6.0:
                add_score(2, f"High recent H avg {profile['recent_hits_avg']:.1f}")
            elif profile["recent_hits_avg"] >= 5.0:
                add_score(1, f"Elevated recent H avg {profile['recent_hits_avg']:.1f}")

        if walks:
            profile["recent_bb_avg"] = float(np.mean(walks))
            profile["available"] = True
            if profile["recent_bb_avg"] >= 3.5:
                add_score(3, f"Extreme recent BB avg {profile['recent_bb_avg']:.1f}")
            elif profile["recent_bb_avg"] >= HIGH_RECENT_BB_AVG:
                add_score(2, f"High recent BB avg {profile['recent_bb_avg']:.1f}")
            elif profile["recent_bb_avg"] >= 2.2:
                add_score(1, f"Elevated recent BB avg {profile['recent_bb_avg']:.1f}")

        if homers:
            profile["recent_hr_avg"] = float(np.mean(homers))
            profile["available"] = True
            if profile["recent_hr_avg"] >= 1.8:
                add_score(3, f"Extreme recent HR avg {profile['recent_hr_avg']:.1f}")
            elif profile["recent_hr_avg"] >= HIGH_RECENT_HR_AVG:
                add_score(2, f"High recent HR avg {profile['recent_hr_avg']:.1f}")

        if ips:
            profile["recent_ip_avg"] = float(np.mean(ips))
            profile["available"] = True
            if profile["recent_ip_avg"] < 4.5:
                add_score(3, f"Very short recent IP {profile['recent_ip_avg']:.1f}")
            elif profile["recent_ip_avg"] < 5.0:
                add_score(2, f"Recent IP short {profile['recent_ip_avg']:.1f}")

        if hits or walks or homers:
            traffic = (profile.get("recent_hits_avg") or 0) + (profile.get("recent_bb_avg") or 0) + (profile.get("recent_hr_avg") or 0) * 1.6
            profile["recent_traffic_index"] = round(float(traffic), 2)
            if traffic >= 9.0:
                add_score(3, f"Extreme recent traffic index {traffic:.1f}")
            elif traffic >= 7.2:
                add_score(2, f"High recent traffic index {traffic:.1f}")
            elif traffic >= 6.2:
                add_score(1, f"Elevated recent traffic index {traffic:.1f}")
    except Exception as e:
        profile["notes"].append(f"Recent run-damage unavailable: {e}")

    score = int(profile.get("risk_score", 0) or 0)
    if not profile["available"]:
        profile["risk_level"] = "UNKNOWN"
        profile["bf_factor"] = 1.0
        profile["volatility_penalty"] = 0.0
        if not profile["notes"]:
            profile["notes"].append("Run-damage inputs unavailable")
    elif score >= 11:
        profile["risk_level"] = "EXTREME"
        profile["bf_factor"] = RUN_DAMAGE_MAX_BF_CUT
        profile["volatility_penalty"] = RUN_DAMAGE_EXTREME_VOL_PENALTY
    elif score >= 8:
        profile["risk_level"] = "HIGH"
        profile["bf_factor"] = RUN_DAMAGE_BF_CUT_HIGH
        profile["volatility_penalty"] = RUN_DAMAGE_HIGH_VOL_PENALTY
    elif score >= 4:
        profile["risk_level"] = "MILD"
        profile["bf_factor"] = RUN_DAMAGE_BF_CUT_MILD
        profile["volatility_penalty"] = RUN_DAMAGE_MILD_VOL_PENALTY
    else:
        profile["risk_level"] = "LOW"
        profile["bf_factor"] = 1.0
        profile["volatility_penalty"] = 0.0

    # Keep notes compact and readable in Streamlit/debug rows.
    profile["notes"] = profile["notes"][:10]
    return profile



def opponent_contact_damage_profile(batter_pitch_rows=None):
    out = {
        "available": False,
        "avg_contact": None,
        "avg_slg_vs_pitch": None,
        "risk_score": 0,
        "risk_level": "UNKNOWN",
        "notes": []
    }
    contacts, slgs = [], []
    for r in (batter_pitch_rows or []):
        c = safe_float(r.get("Per-Batter Contact%"))
        s = safe_float(r.get("Per-Batter SLG vs Pitch"))
        if c is not None:
            contacts.append(c / 100.0 if c > 1 else c)
        if s is not None:
            slgs.append(s)

    if contacts:
        out["available"] = True
        out["avg_contact"] = float(np.mean(contacts))
        if out["avg_contact"] >= 0.79:
            out["risk_score"] += 3
            out["notes"].append(f"High opponent contact vs pitch mix {out['avg_contact']:.1%}")
        elif out["avg_contact"] >= 0.75:
            out["risk_score"] += 2
            out["notes"].append(f"Elevated opponent contact vs pitch mix {out['avg_contact']:.1%}")
    if slgs:
        out["available"] = True
        out["avg_slg_vs_pitch"] = float(np.mean(slgs))
        if out["avg_slg_vs_pitch"] >= 0.560:
            out["risk_score"] += 3
            out["notes"].append(f"High opponent SLG vs pitch mix {out['avg_slg_vs_pitch']:.3f}")
        elif out["avg_slg_vs_pitch"] >= HIGH_OPP_SLG_VS_PITCH:
            out["risk_score"] += 2
            out["notes"].append(f"Elevated opponent SLG vs pitch mix {out['avg_slg_vs_pitch']:.3f}")

    score = int(out.get("risk_score", 0) or 0)
    if not out["available"]:
        out["risk_level"] = "UNKNOWN"
        out["notes"].append("Opponent contact/SLG profile unavailable")
    elif score >= 5:
        out["risk_level"] = "HIGH"
    elif score >= 3:
        out["risk_level"] = "MILD"
    else:
        out["risk_level"] = "LOW"
    return out

def combined_game_script_risk(pitcher_damage, opponent_damage, line=None, side=None):
    p_score = safe_int((pitcher_damage or {}).get("risk_score"), 0) or 0
    o_score = safe_int((opponent_damage or {}).get("risk_score"), 0) or 0
    total = p_score + o_score
    ln = safe_float(line)
    side_text = str(side or "").upper()

    notes = []
    notes.extend((pitcher_damage or {}).get("notes", [])[:3])
    notes.extend((opponent_damage or {}).get("notes", [])[:3])

    # v11.12: let the advanced H/R/ER/BB/HR profile supply a capped BF factor,
    # then combine with opponent contact damage. This remains a volume-risk layer only.
    pitcher_bf_factor = safe_float((pitcher_damage or {}).get("bf_factor"), 1.0) or 1.0
    if total >= 9 or (pitcher_damage or {}).get("risk_level") == "EXTREME":
        label, factor = "EXTREME", min(RUN_DAMAGE_BF_CUT_EXTREME, pitcher_bf_factor)
    elif total >= 6 or (pitcher_damage or {}).get("risk_level") == "HIGH" or (opponent_damage or {}).get("risk_level") == "HIGH":
        label, factor = "HIGH", min(RUN_DAMAGE_BF_CUT_HIGH, pitcher_bf_factor)
    elif total >= 3 or (pitcher_damage or {}).get("risk_level") == "MILD" or (opponent_damage or {}).get("risk_level") == "MILD":
        label, factor = "MILD", min(RUN_DAMAGE_BF_CUT_MILD, pitcher_bf_factor)
    else:
        label, factor = "LOW", min(1.0, pitcher_bf_factor)

    vol_penalty = safe_float((pitcher_damage or {}).get("volatility_penalty"), 0.0) or 0.0
    if vol_penalty > 0:
        notes.append(f"Run-damage volatility penalty {vol_penalty:.0%}")

    if "OVER" in side_text and ln is not None and ln >= 5.5 and label in ["MILD", "HIGH", "EXTREME"]:
        factor = min(factor, 0.94 if label == "MILD" else 0.88 if label == "HIGH" else 0.82)
        notes.append("Over line needs 6+ Ks; early-hook risk amplified")

    return {
        "label": label,
        "factor": float(clamp(factor, RUN_DAMAGE_MAX_BF_CUT, 1.0)),
        "score": int(total),
        "volatility_penalty": round(float(vol_penalty), 3),
        "notes": " | ".join(notes[:10]) if notes else "No major run-damage risk detected"
    }

def apply_game_script_bf_cut(expected_bf, game_script_risk):
    bf = safe_float(expected_bf)
    if bf is None:
        return expected_bf
    factor = safe_float((game_script_risk or {}).get("factor"), 1.0) or 1.0
    return float(clamp(bf * factor, 12, 31))


# =========================
# v11.18 TARGETED IP/BF SAFETY PATCH
# =========================
def _recent_volume_means_v11_18(recent_rows):
    """Small helper for targeted IP/BF safety logic.

    Uses the same real recent game logs already loaded by get_recent_logs().
    It does not fetch or fake data.
    """
    vals = {"ip": [], "bf": [], "pitches": []}
    for r in (recent_rows or [])[:10]:
        ip = safe_float(r.get("IP_float", r.get("IP")), None)
        bf = safe_float(r.get("BF"), None)
        pc = safe_float(r.get("Pitches", r.get("pitchesThrown")), None)
        if ip is not None:
            vals["ip"].append(ip)
        if bf is not None:
            vals["bf"].append(bf)
        if pc is not None:
            vals["pitches"].append(pc)

    def avg(xs, n=None):
        xs = xs[:n] if n else xs
        return float(np.mean(xs)) if xs else None

    return {
        "l3_ip": avg(vals["ip"], 3),
        "l5_ip": avg(vals["ip"], 5),
        "l10_ip": avg(vals["ip"], 10),
        "l3_bf": avg(vals["bf"], 3),
        "l5_bf": avg(vals["bf"], 5),
        "l10_bf": avg(vals["bf"], 10),
        "l3_pitches": avg(vals["pitches"], 3),
        "l5_pitches": avg(vals["pitches"], 5),
    }


def apply_targeted_ip_bf_safety_v11_18(expected_bf, recent_rows, profile=None, row=None, pitcher_name=None, game_script_risk=None, pitch_count_profile=None):
    """Targeted V1 IP/BF patch.

    Purpose from slate review:
    - prevent confirmed starters from being projected like bulk/opener arms,
    - protect true ace/workhorse leash from excessive run-damage cuts,
    - do NOT touch K skill, opponent K%, or official filters.

    This only changes expected batters faced in a capped way, using existing logs.
    """
    bf0 = safe_float(expected_bf, DEFAULT_BF) or DEFAULT_BF
    bf = float(bf0)
    profile = profile or {}
    row = row or {}
    vol = _recent_volume_means_v11_18(recent_rows)
    notes = []

    # Recent BF/IP conversion from the same pitcher logs.
    bf_per_ip_vals = []
    for r in (recent_rows or [])[:8]:
        ip = safe_float(r.get("IP_float", r.get("IP")), None)
        rbf = safe_float(r.get("BF"), None)
        if ip and ip > 0 and rbf and rbf > 0:
            bf_per_ip_vals.append(rbf / ip)
    bf_per_ip = float(clamp(np.mean(bf_per_ip_vals), 3.65, 5.15)) if bf_per_ip_vals else 4.25

    # Schedule rows in this engine are probable/starting pitchers. Still protect against true opener/bulk profiles.
    confirmed_flag = row.get("pitcher_confirmed")
    starter_like = (confirmed_flag is not False)
    l5_ip = vol.get("l5_ip")
    l5_bf = vol.get("l5_bf")
    if l5_ip is not None and l5_bf is not None and l5_ip < 3.05 and l5_bf < 13.5:
        starter_like = False
        notes.append("starter floor skipped: opener/bulk recent volume")

    pc_label = str((pitch_count_profile or {}).get("label") or "").upper()
    if pc_label in ["STRICT_CAP", "OPENER", "BULK_ROLE"]:
        starter_like = False
        notes.append(f"starter floor skipped: pitch-count role {pc_label}")

    # 1) Confirmed starter floor: fixes 1.6-3.3 IP style misses without blindly raising everyone.
    if starter_like:
        starter_floor_ip = 4.00
        # If recent L5 is strong, allow a slightly stronger floor; still conservative.
        if l5_ip is not None and l5_ip >= 5.2:
            starter_floor_ip = 4.35
        floor_bf = starter_floor_ip * bf_per_ip
        if bf < floor_bf:
            old = bf
            bf = max(bf, floor_bf)
            notes.append(f"starter BF floor {old:.1f}->{bf:.1f} (~{starter_floor_ip:.1f} IP)")

    # 2) Ace/workhorse leash protection. BF-only; does not boost K%.
    k_pct = safe_float(profile.get("Pitcher K%"), None)
    k9 = safe_float(profile.get("K/9"), None)
    avg_ip = safe_float(profile.get("AVG IP"), None)
    if avg_ip is None:
        avg_ip = l5_ip
    avg_pc = vol.get("l5_pitches")
    is_ace = ((k_pct is not None and k_pct >= 0.27) or (k9 is not None and k9 >= 9.2))
    is_workhorse = ((avg_ip is not None and avg_ip >= 5.5) or (avg_pc is not None and avg_pc >= 88))
    if starter_like and (is_ace or is_workhorse):
        # Protect from Cole/Gilbert/Cease/Luzardo-type under-leash. Capped so it doesn't blow up Wacha-type reads.
        ace_floor_bf = 22.25 if is_ace else 21.25
        if pc_label in ["SHORT_LEASH", "MONITOR"]:
            ace_floor_bf -= 0.75
        if bf < ace_floor_bf:
            old = bf
            bf = max(bf, ace_floor_bf)
            notes.append(f"ace/workhorse leash floor {old:.1f}->{bf:.1f}")

    # 3) Run-damage cap: do not let damage risk alone turn a real starter into a 3-4 inning projection.
    gs_label = str((game_script_risk or {}).get("label") or "").upper()
    gs_factor = safe_float((game_script_risk or {}).get("factor"), 1.0) or 1.0
    if starter_like and gs_label in ["HIGH", "EXTREME"] and gs_factor < 0.94:
        # Add back only a small fraction of the cut; BF remains capped below original aggressive workload.
        restore_to = max(bf, min(22.0, bf0 * 0.94))
        if restore_to > bf:
            old = bf
            bf = restore_to
            notes.append(f"run-damage cap restore {old:.1f}->{bf:.1f} ({gs_label})")

    # Keep the patch modest. It should improve volume/IP, not rewrite the slate.
    bf = float(clamp(bf, 14, 31))
    max_add = 3.25 if starter_like else 1.25
    if bf > bf0 + max_add:
        notes.append(f"patch capped at +{max_add:.2f} BF")
        bf = bf0 + max_add

    label = "IP_BF_PATCH_ACTIVE" if abs(bf - bf0) >= 0.05 else "IP_BF_PATCH_NEUTRAL"
    return bf, label, " | ".join(notes) if notes else "Targeted IP/BF patch neutral"


def stronger_over_gate(side, prob, edge, source_label, game_script_risk, market_source_count=None):
    if "OVER" not in str(side or "").upper():
        return None
    notes = []
    p = safe_float(prob)
    e = safe_float(edge)
    label = (game_script_risk or {}).get("label", "UNKNOWN")

    if p is not None and p < OVER_MIN_PROB_STRONG:
        notes.append(f"stronger over gate: probability below {int(OVER_MIN_PROB_STRONG*100)}%")
    if e is not None and e < OVER_MIN_EDGE_STRONG:
        notes.append(f"stronger over gate: edge below {OVER_MIN_EDGE_STRONG:.2f} K")
    if source_label != "TRUE LINEUP":
        notes.append("stronger over gate: lineup not true/confirmed")
    if label in ["HIGH", "EXTREME"]:
        notes.append(f"stronger over gate: game-script risk {label}")
    if market_source_count is not None and safe_int(market_source_count, 0) <= 1:
        notes.append("market confirmation rule: only one market source")
    return "; ".join(notes) if notes else None


# =========================
# v11.6 REPEAT MATCHUP / FAMILIARITY LAYER
# =========================
@st.cache_data(ttl=900, show_spinner=False)
def pitcher_recent_opponent_familiarity(pitcher_id, opponent_team_name=None, opponent_abbrev=None, lookback_days=21):
    """Small repeat-opponent familiarity factor.

    If a pitcher faced this same opponent recently, hitters may have a small timing/recognition edge.
    This is intentionally capped and only cuts Ks slightly. Missing data stays neutral.
    """
    result = {
        "available": False,
        "factor": 1.0,
        "recent_matchups": 0,
        "last_days_ago": None,
        "label": "NEUTRAL",
        "note": "No recent same-opponent matchup found"
    }
    if not pitcher_id:
        return result

    data = safe_get_json(
        f"{MLB_BASE}/people/{pitcher_id}/stats",
        params={"stats": "gameLog", "group": "pitching"},
        timeout=12,
    )
    if not isinstance(data, dict):
        result["note"] = "Pitcher game log unavailable for repeat-matchup check"
        return result

    try:
        splits = data["stats"][0]["splits"]
    except Exception:
        result["note"] = "Pitcher game log missing splits for repeat-matchup check"
        return result

    opp_norms = set()
    for v in [opponent_team_name, opponent_abbrev]:
        if v:
            opp_norms.add(normalize_name(v))
    if not opp_norms:
        result["note"] = "Opponent name unavailable for repeat-matchup check"
        return result

    today = california_now().date()
    matches = []

    for g in splits:
        try:
            gdate = datetime.strptime(g.get("date", ""), "%Y-%m-%d").date()
        except Exception:
            continue
        days_ago = (today - gdate).days
        if days_ago < 0 or days_ago > int(lookback_days):
            continue

        opp_obj = g.get("opponent", {}) or {}
        opp_values = [
            opp_obj.get("name"),
            opp_obj.get("abbreviation"),
            opp_obj.get("teamName"),
            opp_obj.get("clubName"),
        ]
        opp_game_norms = {normalize_name(x) for x in opp_values if x}
        if opp_norms & opp_game_norms:
            matches.append(days_ago)

    if not matches:
        return result

    matches = sorted(matches)
    n = len(matches)
    last_days = matches[0]
    factor = 1.0
    label = "LOW"

    if n >= 2 and last_days <= 21:
        factor = REPEAT_MATCHUP_MULTI_RECENT_FACTOR
        label = "HIGH"
    elif last_days <= 7:
        factor = REPEAT_MATCHUP_SAME_7D_FACTOR
        label = "HIGH"
    elif last_days <= 14:
        factor = REPEAT_MATCHUP_SAME_14D_FACTOR
        label = "MILD"
    elif last_days <= 21:
        factor = REPEAT_MATCHUP_SAME_21D_FACTOR
        label = "LOW"

    factor = float(clamp(factor, REPEAT_MATCHUP_FACTOR_MIN, REPEAT_MATCHUP_FACTOR_MAX))
    return {
        "available": True,
        "factor": factor,
        "recent_matchups": int(n),
        "last_days_ago": int(last_days),
        "label": label,
        "note": f"Repeat opponent familiarity {label}: faced opponent {n} time(s) in last {lookback_days} days; most recent {last_days} day(s) ago; K factor x{factor:.3f}"
    }

def apply_repeat_matchup_factor(k_rate, repeat_profile):
    kr = safe_float(k_rate)
    if kr is None:
        return k_rate, "Repeat matchup factor skipped; missing K rate"
    factor = safe_float((repeat_profile or {}).get("factor"), 1.0) or 1.0
    return float(clamp(kr * factor, 0.08, 0.50)), (repeat_profile or {}).get("note", "Repeat matchup neutral")

# =========================
# STATCAST
# =========================
@st.cache_data(ttl=21600, show_spinner=False)
def get_statcast_pitch_profile(pitcher_id, days=365):
    empty = {
        "available": False, "message": "No pitcher id", "rows": 0,
        "csw": None, "whiff": None, "chase": None, "zone_contact": None,
        "pitch_mix": [], "pitch_type_profile": [], "putaway": None,
        "fastball_velo_season": None, "fastball_velo_recent": None, "fastball_velo_delta": None,
        "pitch_usage_trend": None, "pitch_usage_note": None, "first_strike_pct": None,
        "csw_recent_30": None, "csw_recent_30_pitches": 0,
        "csw_recent_45": None, "csw_recent_45_pitches": 0,
        "savant_k_pct": None, "savant_bb_pct": None, "swing_pct": None, "zone_pct": None,
        "avg_exit_velocity": None, "hard_hit_pct": None, "barrel_pct": None,
        "sweet_spot_pct": None, "avg_launch_angle": None, "xwoba": None, "woba": None,
        "batted_balls": 0, "plate_appearances": 0,
        "official_source": "Baseball Savant Statcast CSV",
    }
    if not pitcher_id:
        return empty
    end = datetime.now()
    start = end - timedelta(days=int(days))
    url = "https://baseballsavant.mlb.com/statcast_search/csv"
    params = {
        "all": "true",
        "player_type": "pitcher",
        "pitchers_lookup[]": str(pitcher_id),
        "game_date_gt": start.strftime("%Y-%m-%d"),
        "game_date_lt": end.strftime("%Y-%m-%d"),
        "type": "details",
    }
    try:
        r = requests.get(url, params=params, timeout=30, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code != 200 or not r.text.strip():
            empty["message"] = f"Statcast HTTP {r.status_code}"
            return empty
        df = pd.read_csv(io.StringIO(r.text), low_memory=False)
        if df.empty or "description" not in df.columns:
            empty["message"] = "Statcast returned no pitch rows"
            return empty
        desc = df["description"].astype(str).str.lower()
        pitch_count = int(len(df))
        called_mask = desc.eq("called_strike")
        whiff_mask = desc.isin(["swinging_strike", "swinging_strike_blocked", "foul_tip"])
        swing_mask = desc.isin(["swinging_strike", "swinging_strike_blocked", "foul_tip", "foul", "foul_bunt", "missed_bunt", "hit_into_play", "hit_into_play_no_out", "hit_into_play_score"])
        called = int(called_mask.sum())
        whiffs_n = int(whiff_mask.sum())
        swings = int(swing_mask.sum())
        csw = (called + whiffs_n) / pitch_count if pitch_count else None
        whiff = whiffs_n / swings if swings else None

        # Sabermetric K inputs from real Statcast pitch-level data.
        # Chase% = swings at pitches outside the zone. Zone Contact% = contact on swings inside the zone.
        chase = None
        zone_contact = None
        try:
            if "zone" in df.columns:
                zone_num = pd.to_numeric(df["zone"], errors="coerce")
                out_zone = zone_num.isin([11, 12, 13, 14])
                in_zone = zone_num.isin([1, 2, 3, 4, 5, 6, 7, 8, 9])
                out_zone_pitches = int(out_zone.sum())
                chase_swings = int((out_zone & swing_mask).sum())
                chase = chase_swings / out_zone_pitches if out_zone_pitches else None
                zone_swings = int((in_zone & swing_mask).sum())
                zone_whiffs = int((in_zone & whiff_mask).sum())
                zone_contact = (zone_swings - zone_whiffs) / zone_swings if zone_swings else None
        except Exception:
            chase = None
            zone_contact = None

        # Mechanics / trend inputs for strikeout projection quality.
        # Fastball velocity trend: recent 30 days vs full pulled window.
        fastball_velo_season = None
        fastball_velo_recent = None
        fastball_velo_delta = None
        pitch_usage_trend = None
        pitch_usage_note = None
        first_strike_pct = None
        try:
            if "pitch_type" in df.columns and "release_speed" in df.columns:
                fb_types = {"FF", "SI", "FT", "FC"}
                df_v = df.copy()
                df_v["pitch_type"] = df_v["pitch_type"].fillna("UNK").astype(str)
                df_v["release_speed"] = pd.to_numeric(df_v["release_speed"], errors="coerce")
                fb = df_v[df_v["pitch_type"].isin(fb_types) & df_v["release_speed"].notna()]
                if not fb.empty:
                    fastball_velo_season = float(fb["release_speed"].mean())
                    if "game_date" in fb.columns:
                        gdt = pd.to_datetime(fb["game_date"], errors="coerce")
                        recent_cut = pd.Timestamp(end.date()) - pd.Timedelta(days=30)
                        fb_recent = fb[gdt >= recent_cut]
                        if len(fb_recent) >= 15:
                            fastball_velo_recent = float(fb_recent["release_speed"].mean())
                            fastball_velo_delta = float(fastball_velo_recent - fastball_velo_season)
        except Exception:
            fastball_velo_season = fastball_velo_recent = fastball_velo_delta = None

        try:
            if "pitch_type" in df.columns:
                df_u = df.copy()
                df_u["pitch_type"] = df_u["pitch_type"].fillna("UNK").astype(str)
                if "game_date" in df_u.columns:
                    gdt = pd.to_datetime(df_u["game_date"], errors="coerce")
                    recent_cut = pd.Timestamp(end.date()) - pd.Timedelta(days=30)
                    recent_df = df_u[gdt >= recent_cut]
                    if len(recent_df) >= 40:
                        season_usage = df_u["pitch_type"].value_counts(normalize=True)
                        recent_usage = recent_df["pitch_type"].value_counts(normalize=True)
                        trends = []
                        for pt in set(season_usage.index).union(set(recent_usage.index)):
                            s_u = float(season_usage.get(pt, 0.0))
                            r_u = float(recent_usage.get(pt, 0.0))
                            delta = r_u - s_u
                            if abs(delta) >= 0.045:
                                trends.append({"Pitch Type": pt, "Season Usage %": round(s_u*100,1), "Recent Usage %": round(r_u*100,1), "Delta %": round(delta*100,1)})
                        trends = sorted(trends, key=lambda x: abs(x.get("Delta %",0)), reverse=True)[:3]
                        pitch_usage_trend = trends
                        if trends:
                            pitch_usage_note = "; ".join([f"{t['Pitch Type']} {t['Delta %']:+.1f} pts" for t in trends])
        except Exception:
            pitch_usage_trend = None
            pitch_usage_note = None

        try:
            # First-strike%: first pitch of each PA that is a called/swinging strike/foul/in play.
            key_cols = [c for c in ["game_pk", "at_bat_number"] if c in df.columns]
            if len(key_cols) == 2:
                df_fs = df.copy()
                if "pitch_number" in df_fs.columns:
                    df_fs["pitch_number_num"] = pd.to_numeric(df_fs["pitch_number"], errors="coerce")
                    first_df = df_fs.sort_values(key_cols + ["pitch_number_num"]).groupby(key_cols, as_index=False).first()
                else:
                    first_df = df_fs.groupby(key_cols, as_index=False).first()
                fd = first_df["description"].astype(str).str.lower()
                strike_like = fd.isin(["called_strike", "swinging_strike", "swinging_strike_blocked", "foul", "foul_tip", "hit_into_play", "hit_into_play_no_out", "hit_into_play_score"])
                if len(first_df) >= 20:
                    first_strike_pct = float(strike_like.mean())
        except Exception:
            first_strike_pct = None

        savant_k_pct = None
        savant_bb_pct = None
        swing_pct = None
        zone_pct = None
        avg_exit_velocity = None
        hard_hit_pct = None
        barrel_pct = None
        sweet_spot_pct = None
        avg_launch_angle = None
        xwoba = None
        woba = None
        batted_balls = 0
        plate_appearances = 0
        try:
            swing_pct = float(swing_mask.mean()) if len(df) else None
            if "zone" in df.columns:
                zone_num = pd.to_numeric(df["zone"], errors="coerce")
                zone_pct = float(zone_num.isin([1, 2, 3, 4, 5, 6, 7, 8, 9]).mean())

            if "launch_speed" in df.columns:
                ls = pd.to_numeric(df["launch_speed"], errors="coerce")
                bbe = df[ls.notna()].copy()
                batted_balls = int(len(bbe))
                if batted_balls:
                    avg_exit_velocity = float(ls[ls.notna()].mean())
                    hard_hit_pct = float((ls[ls.notna()] >= 95.0).mean())
                    if "launch_angle" in bbe.columns:
                        la = pd.to_numeric(bbe["launch_angle"], errors="coerce")
                        if la.notna().any():
                            avg_launch_angle = float(la.mean())
                            sweet_spot_pct = float(la.between(8, 32, inclusive="both").mean())
                    if "launch_speed_angle" in bbe.columns:
                        lsa = pd.to_numeric(bbe["launch_speed_angle"], errors="coerce")
                        if lsa.notna().any():
                            # Baseball Savant's launch_speed_angle classification uses 6 for barrels.
                            barrel_pct = float((lsa == 6).mean())

            if "estimated_woba_using_speedangle" in df.columns:
                xw = pd.to_numeric(df["estimated_woba_using_speedangle"], errors="coerce")
                if xw.notna().any():
                    xwoba = float(xw.mean())
            if "woba_value" in df.columns:
                wv = pd.to_numeric(df["woba_value"], errors="coerce")
                if wv.notna().any():
                    woba = float(wv.mean())

            key_cols = [c for c in ["game_pk", "at_bat_number"] if c in df.columns]
            if len(key_cols) == 2 and "events" in df.columns:
                pa_df = df.copy()
                if "pitch_number" in pa_df.columns:
                    pa_df["pitch_number_num"] = pd.to_numeric(pa_df["pitch_number"], errors="coerce")
                    pa_df = pa_df.sort_values(key_cols + ["pitch_number_num"]).groupby(key_cols, as_index=False).tail(1)
                else:
                    pa_df = pa_df.groupby(key_cols, as_index=False).tail(1)
                events = pa_df["events"].astype(str).str.lower()
                valid_pa = events.notna() & ~events.isin(["", "nan", "none"])
                plate_appearances = int(valid_pa.sum())
                if plate_appearances >= 20:
                    k_events = events.isin(["strikeout", "strikeout_double_play"])
                    bb_events = events.isin(["walk", "intent_walk"])
                    savant_k_pct = float(k_events.sum() / plate_appearances)
                    savant_bb_pct = float(bb_events.sum() / plate_appearances)
        except Exception:
            savant_k_pct = savant_bb_pct = swing_pct = zone_pct = None
            avg_exit_velocity = hard_hit_pct = barrel_pct = sweet_spot_pct = avg_launch_angle = xwoba = woba = None
            batted_balls = plate_appearances = 0

        csw_recent_30 = None
        csw_recent_30_pitches = 0
        csw_recent_45 = None
        csw_recent_45_pitches = 0
        try:
            if "game_date" in df.columns:
                df_csw = df.copy()
                gdt = pd.to_datetime(df_csw["game_date"], errors="coerce")
                for _days, _name in [(30, "30"), (45, "45")]:
                    cut = pd.Timestamp(end.date()) - pd.Timedelta(days=_days)
                    rec = df_csw[gdt >= cut]
                    if len(rec) >= 40:
                        rec_desc = rec["description"].astype(str).str.lower()
                        rec_called = rec_desc.eq("called_strike")
                        rec_whiff = rec_desc.isin(["swinging_strike", "swinging_strike_blocked", "foul_tip"])
                        val = float((int(rec_called.sum()) + int(rec_whiff.sum())) / max(len(rec), 1))
                        if _days == 30:
                            csw_recent_30 = val
                            csw_recent_30_pitches = int(len(rec))
                        else:
                            csw_recent_45 = val
                            csw_recent_45_pitches = int(len(rec))
        except Exception:
            csw_recent_30 = csw_recent_45 = None
            csw_recent_30_pitches = csw_recent_45_pitches = 0

        pitch_mix = []
        pitch_type_profile = []
        if "pitch_type" in df.columns:
            df2 = df.copy()
            df2["pitch_type"] = df2["pitch_type"].fillna("UNK").astype(str)
            df2["_called"] = called_mask.astype(int)
            df2["_whiff"] = whiff_mask.astype(int)
            df2["_swing"] = swing_mask.astype(int)
            total = max(len(df2), 1)
            grouped = df2.groupby("pitch_type").agg(Pitches=("pitch_type", "size"), Called=("_called", "sum"), Whiffs=("_whiff", "sum"), Swings=("_swing", "sum")).reset_index()
            grouped["Usage"] = grouped["Pitches"] / total
            grouped["CSW"] = (grouped["Called"] + grouped["Whiffs"]) / grouped["Pitches"].replace(0, np.nan)
            grouped["WhiffRate"] = grouped["Whiffs"] / grouped["Swings"].replace(0, np.nan)
            grouped = grouped.sort_values("Usage", ascending=False).head(8)
            for _, row in grouped.iterrows():
                pt = str(row["pitch_type"])
                usage = safe_float(row["Usage"], 0) or 0
                wr = safe_float(row["WhiffRate"])
                csw_rate = safe_float(row["CSW"])
                pitch_mix.append({"Pitch Type": pt, "Usage %": round(usage * 100, 1)})
                pitch_type_profile.append({
                    "Pitch Type": pt,
                    "Usage %": round(usage * 100, 1),
                    "Pitcher Whiff%": None if wr is None or pd.isna(wr) else round(wr * 100, 1),
                    "Pitcher CSW%": None if csw_rate is None or pd.isna(csw_rate) else round(csw_rate * 100, 1),
                    "Pitches": int(row["Pitches"]),
                    "Swings": int(row["Swings"]),
                })
        return {
            "available": True,
            "message": "Real Baseball Savant Statcast pitch-level data loaded",
            "official_source": "Baseball Savant Statcast CSV",
            "rows": pitch_count,
            "csw": None if csw is None else float(csw),
            "whiff": None if whiff is None else float(whiff),
            "chase": None if chase is None else float(chase),
            "zone_contact": None if zone_contact is None else float(zone_contact),
            "pitch_mix": pitch_mix,
            "pitch_type_profile": pitch_type_profile,
            "fastball_velo_season": None if fastball_velo_season is None else round(float(fastball_velo_season), 2),
            "fastball_velo_recent": None if fastball_velo_recent is None else round(float(fastball_velo_recent), 2),
            "fastball_velo_delta": None if fastball_velo_delta is None else round(float(fastball_velo_delta), 2),
            "pitch_usage_trend": pitch_usage_trend or [],
            "pitch_usage_note": pitch_usage_note or "No meaningful recent pitch-usage shift",
            "first_strike_pct": None if first_strike_pct is None else float(first_strike_pct),
            "csw_recent_30": None if csw_recent_30 is None else float(csw_recent_30),
            "csw_recent_30_pitches": int(csw_recent_30_pitches or 0),
            "csw_recent_45": None if csw_recent_45 is None else float(csw_recent_45),
            "csw_recent_45_pitches": int(csw_recent_45_pitches or 0),
            "savant_k_pct": None if savant_k_pct is None else float(savant_k_pct),
            "savant_bb_pct": None if savant_bb_pct is None else float(savant_bb_pct),
            "swing_pct": None if swing_pct is None else float(swing_pct),
            "zone_pct": None if zone_pct is None else float(zone_pct),
            "avg_exit_velocity": None if avg_exit_velocity is None else round(float(avg_exit_velocity), 2),
            "hard_hit_pct": None if hard_hit_pct is None else float(hard_hit_pct),
            "barrel_pct": None if barrel_pct is None else float(barrel_pct),
            "sweet_spot_pct": None if sweet_spot_pct is None else float(sweet_spot_pct),
            "avg_launch_angle": None if avg_launch_angle is None else round(float(avg_launch_angle), 2),
            "xwoba": None if xwoba is None else round(float(xwoba), 3),
            "woba": None if woba is None else round(float(woba), 3),
            "batted_balls": int(batted_balls or 0),
            "plate_appearances": int(plate_appearances or 0),
        }
    except Exception as e:
        empty["message"] = f"Statcast unavailable: {e}"
        return empty

def apply_statcast_csw_adjustment(pitcher_k, statcast_profile, enabled=True):
    if not enabled or not statcast_profile or not statcast_profile.get("available"):
        return pitcher_k, "No Statcast adjustment"
    csw = statcast_profile.get("csw")
    if csw is None:
        return pitcher_k, "No Statcast CSW available"
    factor = clamp(1 + ((float(csw) - 0.275) * 0.45), 0.93, 1.07)
    return clamp(pitcher_k * factor, 0.08, 0.50), f"Real Statcast CSW adjustment x{factor:.3f}"



def build_sabermetric_k_profile(pitcher_k, statcast_profile=None, lineup_rows=None, enabled=True):
    """Sabermetric K Layer 1.0 for strikeout props.

    Uses the K-predictive metrics only:
      - CSW% (called strikes + whiffs per pitch)
      - SwStr/Whiff% (whiffs per swing from pitch-level Statcast)
      - Chase% (swings outside the zone)
      - Zone Contact% (lower is better for strikeouts)
      - Projected/confirmed lineup K pressure as a small context guard

    The factor is capped so sabermetrics improve the projection without overpowering
    the existing BF, lineup, pitch count, market, and official-play filters.
    """
    base_k = safe_float(pitcher_k)
    if not enabled or base_k is None:
        return {"available": False, "score": 50, "label": "SABER_OFF", "k_factor": 1.0, "note": "Sabermetric K layer off"}

    sp = statcast_profile or {}
    if not sp.get("available"):
        return {"available": False, "score": 50, "label": "SABER_UNKNOWN", "k_factor": 1.0, "note": sp.get("message", "Sabermetric K unavailable")}

    csw = safe_float(sp.get("csw"))
    whiff = safe_float(sp.get("whiff"))
    chase = safe_float(sp.get("chase"))
    zone_contact = safe_float(sp.get("zone_contact"))

    components = []
    notes = []
    # League reference anchors. These are conservative and intentionally broad.
    if csw is not None:
        v = clamp(50 + ((csw - 0.285) / 0.055) * 25, 20, 100)
        components.append((v, 0.36)); notes.append(f"CSW {csw*100:.1f}%")
    if whiff is not None:
        v = clamp(50 + ((whiff - 0.255) / 0.075) * 25, 20, 100)
        components.append((v, 0.30)); notes.append(f"Whiff {whiff*100:.1f}%")
    if chase is not None:
        v = clamp(50 + ((chase - 0.305) / 0.075) * 22, 20, 100)
        components.append((v, 0.18)); notes.append(f"Chase {chase*100:.1f}%")
    if zone_contact is not None:
        v = clamp(50 + ((0.835 - zone_contact) / 0.075) * 22, 20, 100)
        components.append((v, 0.16)); notes.append(f"Zone contact {zone_contact*100:.1f}%")

    if not components:
        return {"available": False, "score": 50, "label": "SABER_THIN", "k_factor": 1.0, "note": "Sabermetric K layer thin: no CSW/whiff/chase/contact metrics"}

    total_w = sum(w for _, w in components) or 1.0
    score = sum(v * w for v, w in components) / total_w

    # Small context guard from the actual batter table; not a replacement for lineup_k/log5.
    rates = []
    for r in lineup_rows or []:
        rk = safe_float(r.get("Raw_K_Rate"))
        if rk is None:
            rk = safe_float(r.get("Used K%"))
            if rk is not None and rk > 1:
                rk = rk / 100.0
        if rk is not None:
            rates.append(rk)
    if len(rates) >= 6:
        avg_lu = float(np.mean(rates))
        if avg_lu >= 0.255:
            score += 4; notes.append(f"lineup K pressure {avg_lu*100:.1f}%")
        elif avg_lu <= 0.195:
            score -= 4; notes.append(f"contact lineup {avg_lu*100:.1f}%")

    score = int(round(clamp(score, 20, 100)))
    if score >= 88:
        label = "ELITE_SABER_K"
    elif score >= 76:
        label = "PLUS_SABER_K"
    elif score >= 62:
        label = "SOLID_SABER_K"
    elif score >= 45:
        label = "NEUTRAL_SABER_K"
    else:
        label = "LOW_SABER_K"

    # Capped K-rate factor. We already have a CSW adjustment elsewhere, so the factor is modest.
    factor = 1.0 + ((score - 50) / 50.0) * 0.045
    factor = float(clamp(factor, 0.955, 1.055))
    return {
        "available": True,
        "score": score,
        "label": label,
        "k_factor": round(factor, 3),
        "csw": None if csw is None else round(csw * 100, 1),
        "whiff": None if whiff is None else round(whiff * 100, 1),
        "chase": None if chase is None else round(chase * 100, 1),
        "zone_contact": None if zone_contact is None else round(zone_contact * 100, 1),
        "note": f"Sabermetric K {label}: score {score}/100; factor x{factor:.3f}; " + "; ".join(notes)
    }

def apply_sabermetric_k_adjustment(pitcher_k, sabermetric_profile, enabled=True):
    if not enabled or not isinstance(sabermetric_profile, dict) or not sabermetric_profile.get("available"):
        return pitcher_k, (sabermetric_profile or {}).get("note", "No sabermetric K adjustment")
    factor = safe_float(sabermetric_profile.get("k_factor"), 1.0) or 1.0
    return float(clamp((safe_float(pitcher_k, LEAGUE_AVG_K) or LEAGUE_AVG_K) * factor, 0.08, 0.50)), sabermetric_profile.get("note", f"Sabermetric K factor x{factor:.3f}")



# =========================
# MECHANICS / PITCH-SHAPE TREND LAYER FOR K PROPS
# =========================
def build_mechanics_k_profile(statcast_profile=None, enabled=True):
    """Velocity trend + pitch usage trend + first-strike%.

    This layer is intentionally capped. It is meant to detect K-upside/injury-risk
    signals without overpowering CSW/whiff, BF, lineups, pitch count, or market.
    """
    sp = statcast_profile or {}
    if not enabled or not sp.get("available"):
        return {"available": False, "score": 50, "label": "MECH_UNKNOWN", "k_factor": 1.0, "note": sp.get("message", "Mechanics layer unavailable")}

    components = []
    notes = []
    velo_delta = safe_float(sp.get("fastball_velo_delta"))
    if velo_delta is not None:
        # +1.5 mph is very strong, -1.5 mph is a real risk flag.
        vscore = clamp(50 + (velo_delta / 1.5) * 22, 20, 95)
        components.append((vscore, 0.42))
        notes.append(f"FB velo trend {velo_delta:+.1f} mph")

    fstrike = safe_float(sp.get("first_strike_pct"))
    if fstrike is not None:
        # League-ish anchor around 61-62%.
        fs_score = clamp(50 + ((fstrike - 0.615) / 0.075) * 22, 20, 95)
        components.append((fs_score, 0.36))
        notes.append(f"F-Strike {fstrike*100:.1f}%")

    usage_trend = sp.get("pitch_usage_trend") or []
    usage_score = 50
    if usage_trend:
        # If a pitcher is changing pitch mix, we do not automatically call it good.
        # We reward only modestly when the changed pitch is also a high-CSW/whiff pitch
        # in the pitch_type_profile table; otherwise it is an information/confidence tag.
        pitch_profiles = {str(r.get("Pitch Type")): r for r in (sp.get("pitch_type_profile") or [])}
        plus_points = 0
        detail = []
        for t in usage_trend[:3]:
            pt = str(t.get("Pitch Type"))
            delta = safe_float(t.get("Delta %"), 0) or 0
            prof = pitch_profiles.get(pt, {})
            wr = safe_float(prof.get("Pitcher Whiff%"))
            csw = safe_float(prof.get("Pitcher CSW%"))
            if delta > 0 and ((wr is not None and wr >= 30) or (csw is not None and csw >= 32)):
                plus_points += min(8, abs(delta) * 0.55)
            elif delta < 0 and ((wr is not None and wr >= 30) or (csw is not None and csw >= 32)):
                plus_points -= min(7, abs(delta) * 0.45)
            detail.append(f"{pt} {delta:+.1f} pts")
        usage_score = clamp(50 + plus_points, 35, 70)
        components.append((usage_score, 0.22))
        notes.append("Usage trend " + ", ".join(detail))

    if not components:
        return {"available": False, "score": 50, "label": "MECH_THIN", "k_factor": 1.0, "note": "No velocity/usage/F-Strike trend data"}

    total_w = sum(w for _, w in components) or 1.0
    score = int(round(clamp(sum(v*w for v, w in components) / total_w, 20, 100)))
    if score >= 82:
        label = "MECH_UPGRADE"
    elif score >= 66:
        label = "MECH_PLUS"
    elif score >= 46:
        label = "MECH_NEUTRAL"
    else:
        label = "MECH_RISK"

    factor = 1.0 + ((score - 50) / 50.0) * 0.035
    factor = float(clamp(factor, 0.965, 1.04))
    return {
        "available": True,
        "score": score,
        "label": label,
        "k_factor": round(factor, 3),
        "fastball_velo_season": sp.get("fastball_velo_season"),
        "fastball_velo_recent": sp.get("fastball_velo_recent"),
        "fastball_velo_delta": sp.get("fastball_velo_delta"),
        "pitch_usage_note": sp.get("pitch_usage_note") or "No meaningful usage shift",
        "pitch_usage_trend": usage_trend,
        "first_strike_pct": None if fstrike is None else round(fstrike * 100, 1),
        "note": f"Mechanics {label}: score {score}/100; factor x{factor:.3f}; " + "; ".join(notes)
    }

def apply_mechanics_k_adjustment(pitcher_k, mechanics_profile, enabled=True):
    if not enabled or not isinstance(mechanics_profile, dict) or not mechanics_profile.get("available"):
        return pitcher_k, (mechanics_profile or {}).get("note", "No mechanics K adjustment")
    factor = safe_float(mechanics_profile.get("k_factor"), 1.0) or 1.0
    return float(clamp((safe_float(pitcher_k, LEAGUE_AVG_K) or LEAGUE_AVG_K) * factor, 0.08, 0.50)), mechanics_profile.get("note", f"Mechanics K factor x{factor:.3f}")

def build_projection_attribution_engine(base_projection=None, final_projection=None, components=None):
    """Small transparent attribution table for mobile cards/debugging.

    components should be a list of (label, delta, note). Deltas are approximate K
    contributions, not a second projection model. They help verify pipeline alignment.
    """
    rows = []
    base = safe_float(base_projection, 0.0) or 0.0
    final = safe_float(final_projection, base) or base
    for label, delta, note in (components or []):
        d = safe_float(delta, 0.0) or 0.0
        rows.append({"Layer": str(label), "K Impact": round(d, 2), "Note": str(note or "")[:140]})
    explained = sum(safe_float(r.get("K Impact"), 0) or 0 for r in rows)
    residual = final - base - explained
    if abs(residual) >= 0.05:
        rows.append({"Layer": "Simulation/Calibration", "K Impact": round(residual, 2), "Note": "Monte Carlo, market/probability calibration, rounding, and interaction effects"})
    summary = f"Base {base:.2f} → Final {final:.2f} ({final-base:+.2f} K)"
    return {"base_projection": round(base, 2), "final_projection": round(final, 2), "total_delta": round(final-base, 2), "summary": summary, "rows": rows[:8]}

# =========================
# DIPS / MARKET-INEFFICIENCY LAYER FOR K PROPS
# =========================
def build_dips_metrics_from_counts(so=None, bb=None, hr=None, ip=None, bf=None):
    """Return DIPS-style pitcher metrics from MLB season counts.

    Strikeout props should not let ERA/WHIP drive the pick. This layer focuses on
    K-BB% first, then uses FIP/xFIP/SIERA only as light sustainability signals.

    Notes:
    - FIP uses a common constant approximation because MLB Stats API does not
      provide the season-specific FIP constant directly.
    - xFIP is approximated by normalizing HR to a league-average HR/9 baseline;
      it is intentionally light-weight.
    - SIERA here is a compact K-BB/PA approximation. Without full batted-ball
      detail, it should be used as a direction/risk flag, not a primary projection.
    """
    so = safe_float(so, 0) or 0
    bb = safe_float(bb, 0) or 0
    hr = safe_float(hr, 0) or 0
    ip = safe_float(ip)
    bf = safe_float(bf)
    if not ip or ip <= 0 or not bf or bf <= 0:
        return {"available": False, "k_pct": None, "bb_pct": None, "kbb_pct": None, "fip": None, "xfip": None, "siera": None}

    k_pct = so / bf
    bb_pct = bb / bf
    kbb_pct = k_pct - bb_pct

    # Approx constants. The goal is a stable direction signal, not official leader-board values.
    fip_constant = 3.15
    league_hr9 = 1.12
    x_hr = league_hr9 * ip / 9.0
    fip = ((13 * hr) + (3 * bb) - (2 * so)) / ip + fip_constant
    xfip = ((13 * x_hr) + (3 * bb) - (2 * so)) / ip + fip_constant

    # Compact SIERA-style approximation using the strongest available DIPS inputs.
    # Lower is better. Keep bounded to avoid bad stat feeds creating extreme values.
    siera = 5.20 - (16.0 * k_pct) + (11.0 * bb_pct) - (2.2 * kbb_pct)

    return {
        "available": True,
        "k_pct": float(k_pct),
        "bb_pct": float(bb_pct),
        "kbb_pct": float(kbb_pct),
        "fip": round(float(clamp(fip, 1.2, 8.5)), 2),
        "xfip": round(float(clamp(xfip, 1.2, 8.5)), 2),
        "siera": round(float(clamp(siera, 1.5, 7.5)), 2),
    }


def build_dips_k_profile(profile=None, recent_rows=None, enabled=True):
    """DIPS K Dominance Engine.

    Uses K-BB% as the main signal and FIP/xFIP/SIERA as small supporting context.
    It is purposely capped so it helps side selection without overfitting.
    """
    if not enabled:
        return {"available": False, "score": 50, "label": "DIPS_OFF", "k_factor": 1.0, "reliability_nudge": 0, "note": "DIPS layer off"}
    profile = profile or {}

    kbb = safe_float(profile.get("K-BB%"))
    fip = safe_float(profile.get("FIP"))
    xfip = safe_float(profile.get("xFIP"))
    siera = safe_float(profile.get("SIERA"))
    bb_pct = safe_float(profile.get("BB%"))
    bf = safe_float(profile.get("BF"), 0) or 0

    # Recent K-BB% support, light weight only.
    recent_kbb = None
    try:
        vals = []
        for r in (recent_rows or [])[:5]:
            so = safe_float(r.get("Ks"))
            bb = safe_float(r.get("BB"))
            bf_r = safe_float(r.get("BF"))
            if so is not None and bb is not None and bf_r and bf_r > 0:
                vals.append((so - bb) / bf_r)
        if vals:
            recent_kbb = sum(vals) / len(vals)
    except Exception:
        recent_kbb = None

    components = []
    notes = []
    if kbb is not None:
        # 6% weak, 14% solid, 20% strong, 25% elite.
        components.append((clamp((kbb - 0.06) / 0.20, 0, 1) * 100, 0.52))
        notes.append(f"K-BB {kbb*100:.1f}%")
    if recent_kbb is not None:
        components.append((clamp((recent_kbb - 0.05) / 0.21, 0, 1) * 100, 0.14))
        notes.append(f"L5 K-BB {recent_kbb*100:.1f}%")
    if siera is not None:
        # Lower SIERA supports skill sustainability.
        components.append((clamp((5.10 - siera) / 2.20, 0, 1) * 100, 0.12))
        notes.append(f"SIERA {siera:.2f}")
    if fip is not None:
        components.append((clamp((5.25 - fip) / 2.40, 0, 1) * 100, 0.10))
        notes.append(f"FIP {fip:.2f}")
    if xfip is not None:
        components.append((clamp((5.15 - xfip) / 2.25, 0, 1) * 100, 0.08))
        notes.append(f"xFIP {xfip:.2f}")
    if bb_pct is not None:
        # Walks do not kill K ability directly, but they do create pitch-count stress.
        bb_score = clamp((0.13 - bb_pct) / 0.09, 0, 1) * 100
        components.append((bb_score, 0.04))
        notes.append(f"BB {bb_pct*100:.1f}%")

    if not components:
        return {"available": False, "score": 50, "label": "DIPS_UNKNOWN", "k_factor": 1.0, "reliability_nudge": 0, "note": "No DIPS inputs available"}

    total_w = sum(w for _, w in components) or 1.0
    score = int(round(sum(v * w for v, w in components) / total_w))

    # Small-sample shrink.
    if bf < 120:
        score = int(round((score * 0.65) + (50 * 0.35)))
        notes.append(f"thin BF {int(bf)}")
    elif bf < 220:
        score = int(round((score * 0.82) + (50 * 0.18)))
        notes.append(f"medium BF {int(bf)}")

    if score >= 88:
        label = "DIPS_ELITE"
    elif score >= 76:
        label = "DIPS_STRONG"
    elif score >= 62:
        label = "DIPS_SOLID"
    elif score >= 45:
        label = "DIPS_NEUTRAL"
    else:
        label = "DIPS_RISK"

    # Projection modifier: purposely smaller than CSW/SwStr layer.
    factor = 1.0 + clamp((score - 50) / 1000.0, -0.045, 0.055)
    # If walks are extreme, avoid boosting OVER too much because pitch count may shorten outing.
    if bb_pct is not None and bb_pct >= 0.115 and factor > 1.0:
        factor = min(factor, 1.018)
        notes.append("walk-stress cap")

    reliability_nudge = 0
    if score >= 82:
        reliability_nudge = 4
    elif score >= 70:
        reliability_nudge = 2
    elif score <= 38:
        reliability_nudge = -5
    elif score <= 48:
        reliability_nudge = -2

    return {
        "available": True,
        "score": score,
        "label": label,
        "k_factor": round(float(factor), 3),
        "reliability_nudge": reliability_nudge,
        "kbb_pct": None if kbb is None else round(kbb * 100, 1),
        "bb_pct": None if bb_pct is None else round(bb_pct * 100, 1),
        "recent_kbb_pct": None if recent_kbb is None else round(recent_kbb * 100, 1),
        "fip": fip,
        "xfip": xfip,
        "siera": siera,
        "note": f"DIPS {label}: score {score}/100; factor x{factor:.3f}; " + "; ".join(notes),
    }


def apply_dips_k_adjustment(pitcher_k, dips_profile, enabled=True):
    if not enabled or not isinstance(dips_profile, dict) or not dips_profile.get("available"):
        return pitcher_k, (dips_profile or {}).get("note", "No DIPS adjustment")
    factor = safe_float(dips_profile.get("k_factor"), 1.0) or 1.0
    base = safe_float(pitcher_k, LEAGUE_AVG_K) or LEAGUE_AVG_K
    return float(clamp(base * factor, 0.08, 0.50)), dips_profile.get("note", f"DIPS K factor x{factor:.3f}")


def build_babip_regression_profile(profile=None):
    """DIPS-style BABIP regression context for pitcher volatility.

    This is intentionally NOT a K-projection driver. It is a small reliability /
    miss-reason context layer because BABIP can signal luck, defense noise, or
    early-pull/run-damage risk.
    """
    prof = profile or {}
    babip = safe_float(prof.get("BABIP"), None)
    if babip is None:
        return {"available": False, "babip": None, "score": 50, "label": "BABIP_UNKNOWN", "reliability_nudge": 0, "note": "BABIP unavailable"}
    league = 0.300
    diff = babip - league
    if diff >= 0.055:
        label, score, nudge = "UNLUCKY_HIGH_BABIP", 70, 2
        note = f"BABIP {babip:.3f} above league {league:.3f}; possible positive regression, but watch run-damage volatility."
    elif diff <= -0.045:
        label, score, nudge = "LUCKY_LOW_BABIP", 38, -2
        note = f"BABIP {babip:.3f} below league {league:.3f}; possible negative regression / run-prevention luck."
    else:
        label, score, nudge = "BABIP_NEUTRAL", 55, 0
        note = f"BABIP {babip:.3f} near league {league:.3f}; neutral regression signal."
    return {"available": True, "babip": round(float(babip), 3), "score": score, "label": label, "reliability_nudge": nudge, "note": note}

def apply_pitch_type_matchup_adjustment(pitcher_k, pitcher_statcast, enabled=True):
    if not enabled or not pitcher_statcast or not pitcher_statcast.get("available"):
        return pitcher_k, "No pitch-type matchup adjustment", False, [], 1.0
    # Conservative simplified pitch-type factor from pitcher whiff vs league ref.
    rows = []
    weighted = 0
    total_w = 0
    for r in pitcher_statcast.get("pitch_type_profile", []):
        pt = r.get("Pitch Type")
        usage = (safe_float(r.get("Usage %"), 0) or 0) / 100
        wr = safe_float(r.get("Pitcher Whiff%"))
        ref = LEAGUE_AVG_WHIFF_BY_PITCH_TYPE.get(pt, 0.25)
        if usage >= 0.03 and wr is not None:
            idx = clamp((wr / 100) / max(ref, 0.01), 0.85, 1.18)
            weighted += usage * idx
            total_w += usage
            rows.append({"Pitch Type": pt, "Usage %": round(usage * 100, 1), "Pitcher Whiff%": wr, "League Ref Whiff%": round(ref * 100, 1), "Index": round(idx, 3)})
    if total_w <= 0:
        return pitcher_k, "Pitch-type rows unavailable", False, rows, 1.0
    combined = weighted / total_w
    factor = clamp(1 + ((combined - 1) * 0.08), 0.97, 1.03)
    return clamp(pitcher_k * factor, 0.08, 0.50), f"Pitch-type whiff mix adjustment x{factor:.3f}", True, rows, factor



@st.cache_data(ttl=21600, show_spinner=False)
def get_batter_statcast_pitch_type_profile(batter_id, days=365, pitcher_hand=None):
    """Real per-batter Statcast profile by pitch type.

    Adds:
    - per-batter whiff% by pitch type
    - per-batter contact% by pitch type
    - per-batter SLG vs pitch type from real batted-ball outcomes
    - overall batter whiff/contact profile

    Missing or thin data stays neutral. Nothing is guessed.
    """
    empty = {
        "available": False,
        "message": "No batter id",
        "rows": 0,
        "overall_whiff": None,
        "overall_contact": None,
        "pitch_type_profile": []
    }
    if not batter_id:
        return empty

    end = datetime.now()
    start = end - timedelta(days=int(days))
    url = "https://baseballsavant.mlb.com/statcast_search/csv"
    params = {
        "all": "true",
        "player_type": "batter",
        "batters_lookup[]": str(batter_id),
        "game_date_gt": start.strftime("%Y-%m-%d"),
        "game_date_lt": end.strftime("%Y-%m-%d"),
        "type": "details",
    }

    def _event_total_bases(ev):
        ev = str(ev or "").lower()
        if ev == "single":
            return 1
        if ev == "double":
            return 2
        if ev == "triple":
            return 3
        if ev == "home_run":
            return 4
        return 0

    def _is_ab_event(ev):
        ev = str(ev or "").lower()
        if not ev or ev in ["nan", "none"]:
            return False
        non_ab = {
            "walk", "intent_walk", "hit_by_pitch", "sac_bunt", "sac_fly",
            "catcher_interf", "sac_fly_double_play", "sac_bunt_double_play"
        }
        return ev not in non_ab

    try:
        r = requests.get(url, params=params, timeout=25, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code != 200 or not r.text.strip():
            empty["message"] = f"Batter Statcast HTTP {r.status_code}"
            return empty

        df = pd.read_csv(io.StringIO(r.text), low_memory=False)
        if df.empty or "description" not in df.columns or "pitch_type" not in df.columns:
            empty["message"] = "Batter Statcast returned no pitch-type rows"
            return empty

        # Use pitcher-hand split only if enough real rows exist; otherwise keep full batter sample.
        if pitcher_hand in ["R", "L"] and "p_throws" in df.columns:
            hand_df = df[df["p_throws"].astype(str).str.upper() == pitcher_hand].copy()
            if len(hand_df) >= 25:
                df = hand_df

        desc = df["description"].astype(str).str.lower()
        whiff_mask = desc.isin(["swinging_strike", "swinging_strike_blocked", "foul_tip"])
        swing_mask = desc.isin([
            "swinging_strike", "swinging_strike_blocked", "foul_tip", "foul", "foul_bunt",
            "missed_bunt", "hit_into_play", "hit_into_play_no_out", "hit_into_play_score"
        ])
        contact_mask = swing_mask & (~whiff_mask)

        df2 = df.copy()
        df2["pitch_type"] = df2["pitch_type"].fillna("UNK").astype(str)
        df2["_whiff"] = whiff_mask.astype(int)
        df2["_swing"] = swing_mask.astype(int)
        df2["_contact"] = contact_mask.astype(int)

        if "events" in df2.columns:
            df2["_ab_event"] = df2["events"].apply(_is_ab_event).astype(int)
            df2["_total_bases"] = df2["events"].apply(_event_total_bases).astype(float)
        else:
            df2["_ab_event"] = 0
            df2["_total_bases"] = 0.0

        overall_swings = int(df2["_swing"].sum())
        overall_whiffs = int(df2["_whiff"].sum())
        overall_contacts = int(df2["_contact"].sum())
        overall_whiff = overall_whiffs / overall_swings if overall_swings > 0 else None
        overall_contact = overall_contacts / overall_swings if overall_swings > 0 else None

        grouped = df2.groupby("pitch_type").agg(
            Pitches=("pitch_type", "size"),
            Whiffs=("_whiff", "sum"),
            Swings=("_swing", "sum"),
            Contacts=("_contact", "sum"),
            ABEvents=("_ab_event", "sum"),
            TotalBases=("_total_bases", "sum"),
        ).reset_index()

        grouped = grouped[grouped["Swings"] >= 5]
        if grouped.empty:
            empty["message"] = "Batter Statcast has too few swings by pitch type"
            return empty

        grouped["WhiffRate"] = grouped["Whiffs"] / grouped["Swings"].replace(0, np.nan)
        grouped["ContactRate"] = grouped["Contacts"] / grouped["Swings"].replace(0, np.nan)
        grouped["SLG"] = grouped["TotalBases"] / grouped["ABEvents"].replace(0, np.nan)

        profile = []
        for _, row in grouped.iterrows():
            wr = safe_float(row["WhiffRate"])
            cr = safe_float(row["ContactRate"])
            slg = safe_float(row["SLG"])
            if wr is None or pd.isna(wr):
                continue
            profile.append({
                "Pitch Type": str(row["pitch_type"]),
                "Batter Whiff%": round(wr * 100, 1),
                "Batter Contact%": None if cr is None or pd.isna(cr) else round(cr * 100, 1),
                "Batter SLG vs Pitch": None if slg is None or pd.isna(slg) else round(slg, 3),
                "Swings": int(row["Swings"]),
                "Contacts": int(row["Contacts"]),
                "Pitches Seen": int(row["Pitches"]),
                "AB Events": int(row["ABEvents"]),
                "Total Bases": int(row["TotalBases"]),
            })

        if not profile:
            empty["message"] = "No batter pitch-type rows passed sample filter"
            return empty

        return {
            "available": True,
            "message": "Real batter Statcast pitch-type whiff/contact/SLG loaded",
            "rows": int(len(df)),
            "overall_whiff": None if overall_whiff is None else float(overall_whiff),
            "overall_contact": None if overall_contact is None else float(overall_contact),
            "pitch_type_profile": profile
        }
    except Exception as e:
        empty["message"] = f"Batter Statcast unavailable: {e}"
        return empty


def build_pitch_type_matchup_profile(pitcher_statcast, lineup_rows, enabled=True, min_batters=5, pitcher_hand=None):
    """Compare real pitcher pitch mix to real batter pitch-type profiles.

    v11.3 adds per-batter:
    - K% already supplied from lineup_rows
    - SLG vs pitch type
    - contact% / whiff% by pitch type

    Missing pitch types are ignored, never guessed.
    """
    result = {
        "available": False,
        "factor": 1.0,
        "message": "Pitch-type matchup disabled or unavailable",
        "rows": [],
        "batter_rows": [],
        "batters_loaded": 0
    }
    if not enabled:
        result["message"] = "Pitch-type matchup disabled"
        return result
    if not pitcher_statcast or not pitcher_statcast.get("available"):
        result["message"] = "Pitcher Statcast pitch mix unavailable"
        return result
    pitch_profile = pitcher_statcast.get("pitch_type_profile") or []
    if not pitch_profile:
        result["message"] = "Pitcher pitch-type profile unavailable"
        return result
    if not lineup_rows:
        result["message"] = "No posted lineup for batter pitch-type matching"
        return result

    pitcher_usage = {r.get("Pitch Type"): (safe_float(r.get("Usage %"), 0) or 0) / 100.0 for r in pitch_profile}
    pitcher_whiff = {
        r.get("Pitch Type"): (safe_float(r.get("Pitcher Whiff%")) / 100.0 if safe_float(r.get("Pitcher Whiff%")) is not None else None)
        for r in pitch_profile
    }
    pitch_types = [pt for pt, use in pitcher_usage.items() if pt and use >= 0.03]

    batter_profiles = []
    batter_detail_rows = []

    for r in lineup_rows[:9]:
        bid = r.get("Player ID")
        batter_name = r.get("Batter")
        prof = get_batter_statcast_pitch_type_profile(bid, days=365, pitcher_hand=pitcher_hand)
        if prof.get("available"):
            by_pt = {x.get("Pitch Type"): x for x in prof.get("pitch_type_profile", [])}
            batter_profiles.append({
                "Batter": batter_name,
                "Order": r.get("Order"),
                "Used K%": r.get("Used K%"),
                "Raw_K_Rate": r.get("Raw_K_Rate"),
                "Overall Contact%": None if prof.get("overall_contact") is None else round(prof.get("overall_contact") * 100, 1),
                "Overall Whiff%": None if prof.get("overall_whiff") is None else round(prof.get("overall_whiff") * 100, 1),
                "by_pt": by_pt
            })

            for pt, prow in by_pt.items():
                if pt not in pitch_types:
                    continue
                batter_detail_rows.append({
                    "Order": r.get("Order"),
                    "Batter": batter_name,
                    "Player ID": bid,
                    "Pitch Type": pt,
                    "Pitcher Usage %": round((pitcher_usage.get(pt, 0) or 0) * 100, 1),
                    "Per-Batter K%": r.get("Used K%"),
                    "Per-Batter Contact%": prow.get("Batter Contact%"),
                    "Per-Batter Whiff%": prow.get("Batter Whiff%"),
                    "Per-Batter SLG vs Pitch": prow.get("Batter SLG vs Pitch"),
                    "Swings": prow.get("Swings"),
                    "Pitches Seen": prow.get("Pitches Seen"),
                    "AB Events": prow.get("AB Events"),
                })

    result["batters_loaded"] = len(batter_profiles)
    result["batter_rows"] = batter_detail_rows

    if len(batter_profiles) < min_batters:
        result["message"] = f"Only {len(batter_profiles)}/9 batter pitch-type profiles loaded; no adjustment applied"
        return result

    rows = []
    weighted_index = 0.0
    used_weight = 0.0

    for pt in pitch_types:
        use = pitcher_usage.get(pt, 0) or 0
        batter_whiff_rates = []
        batter_contact_rates = []
        batter_slg_rates = []
        batter_swings = 0
        slg_ab_events = 0

        for bp in batter_profiles:
            row = bp["by_pt"].get(pt)
            if not row:
                continue

            wr = safe_float(row.get("Batter Whiff%"))
            cr = safe_float(row.get("Batter Contact%"))
            slg = safe_float(row.get("Batter SLG vs Pitch"))
            swings = safe_int(row.get("Swings"), 0) or 0
            ab_events = safe_int(row.get("AB Events"), 0) or 0

            if wr is not None and swings >= 5:
                batter_whiff_rates.append(wr / 100.0)
                batter_swings += swings
            if cr is not None and swings >= 5:
                batter_contact_rates.append(cr / 100.0)
            if slg is not None and ab_events >= 2:
                batter_slg_rates.append(slg)
                slg_ab_events += ab_events

        if len(batter_whiff_rates) < 3:
            continue

        avg_batter_whiff = float(np.mean(batter_whiff_rates))
        avg_batter_contact = float(np.mean(batter_contact_rates)) if batter_contact_rates else None
        avg_batter_slg = float(np.mean(batter_slg_rates)) if batter_slg_rates else None

        league_ref = LEAGUE_AVG_WHIFF_BY_PITCH_TYPE.get(pt, 0.25)
        pitcher_wr = pitcher_whiff.get(pt)

        pitcher_bonus = 1.0
        if pitcher_wr is not None:
            pitcher_bonus = clamp(pitcher_wr / max(league_ref, 0.01), 0.85, 1.18)

        batter_whiff_index = avg_batter_whiff / max(league_ref, 0.01)

        # Contact and SLG protect against fake K boosts when hitters see a pitch well.
        contact_guard = 1.0
        if avg_batter_contact is not None:
            if avg_batter_contact >= 0.78:
                contact_guard = 0.96
            elif avg_batter_contact <= 0.64:
                contact_guard = 1.04

        slg_guard = 1.0
        if avg_batter_slg is not None:
            if avg_batter_slg >= 0.520:
                slg_guard = 0.97
            elif avg_batter_slg <= 0.300:
                slg_guard = 1.03

        combined_index = (batter_whiff_index * 0.60) + (pitcher_bonus * 0.25) + (contact_guard * 0.10) + (slg_guard * 0.05)
        combined_index = clamp(combined_index, 0.82, 1.22)

        weighted_index += use * combined_index
        used_weight += use

        rows.append({
            "Pitch Type": pt,
            "Pitcher Usage %": round(use * 100, 1),
            "Avg Batter Whiff%": round(avg_batter_whiff * 100, 1),
            "Avg Batter Contact%": None if avg_batter_contact is None else round(avg_batter_contact * 100, 1),
            "Avg Batter SLG vs Pitch": None if avg_batter_slg is None else round(avg_batter_slg, 3),
            "League Ref Whiff%": round(league_ref * 100, 1),
            "Pitcher Whiff%": None if pitcher_wr is None else round(pitcher_wr * 100, 1),
            "Contact Guard": round(contact_guard, 3),
            "SLG Guard": round(slg_guard, 3),
            "Index": round(combined_index, 3),
            "Batter Profiles Used": len(batter_whiff_rates),
            "Batter Swings": batter_swings,
            "SLG AB Events": slg_ab_events,
        })

    if used_weight <= 0 or not rows:
        result["message"] = "No overlapping pitcher/batter pitch-type rows passed sample filter"
        return result

    avg_index = weighted_index / used_weight
    factor = clamp(1 + ((avg_index - 1) * 0.10), 0.965, 1.035)
    result.update({
        "available": True,
        "factor": factor,
        "message": f"Real per-batter K/contact/whiff/SLG pitch-type matchup x{factor:.3f} ({len(batter_profiles)}/9 batters loaded)",
        "rows": rows,
        "batter_rows": batter_detail_rows,
    })
    return result


def apply_advanced_pitch_type_matchup_adjustment(pitcher_k, matchup_profile, enabled=True):
    if not enabled or not matchup_profile or not matchup_profile.get("available"):
        msg = matchup_profile.get("message", "No batter-vs-pitch-type matchup adjustment") if matchup_profile else "No batter-vs-pitch-type matchup adjustment"
        return pitcher_k, msg
    factor = safe_float(matchup_profile.get("factor"), 1.0) or 1.0
    return clamp(pitcher_k * factor, 0.08, 0.50), matchup_profile.get("message", f"Pitch-type matchup x{factor:.3f}")



def build_k_context_no_duplicate_profile(lineup_rows, matchup_profile=None, statcast_profile=None, lineup_locked=False, enabled=True):
    """K Context No-Duplicate Upgrade.

    Adds the remaining K context signals without double-counting major layers:
    - Confirmed lineup K pressure is reported and used only as a tiny confidence/context guard
      because lineup K% already feeds calculate_log5_k_rate().
    - Pitch-type matchup availability is reported only because the advanced pitch-type engine
      already applies its own factor earlier.
    - Batter whiff pressure and CSW synergy receive only a micro capped factor, using real
      batter-vs-pitch rows when available.

    Max projection impact is intentionally tiny (about +/-1.5%) so it cannot overpower the
    existing K core that went 9-5: BF/IP, leash, pitcher K%, lineup K%, pitch type, CSW,
    pitch count, and official filters.
    """
    profile = {
        "available": False,
        "score": 50,
        "label": "K_CONTEXT_NEUTRAL",
        "k_factor": 1.0,
        "confirmed_lineup_k_pressure": None,
        "batter_whiff_pressure": None,
        "csw_synergy": None,
        "pitch_type_context": "ALREADY_APPLIED" if (matchup_profile or {}).get("available") else "UNAVAILABLE",
        "note": "K context upgrade disabled or unavailable",
    }
    if not enabled:
        profile["note"] = "K context upgrade off"
        return profile

    notes = []
    score_parts = []

    # 1) Confirmed Lineup K Pressure — report/tiny guard only; main lineup K already in log5.
    rates = []
    for r in (lineup_rows or [])[:9]:
        if not isinstance(r, dict):
            continue
        rk = safe_float(r.get("Raw_K_Rate"))
        if rk is None:
            rk = safe_float(r.get("Used K%"))
            if rk is not None and rk > 1:
                rk = rk / 100.0
        if rk is not None:
            rates.append(float(rk))
    if len(rates) >= 6:
        avg_k = float(np.mean(rates))
        profile["confirmed_lineup_k_pressure"] = round(avg_k * 100, 1)
        # Only a tiny score movement to avoid double-counting calculate_log5_k_rate.
        lu_score = clamp(50 + ((avg_k - 0.225) / 0.055) * 10, 35, 65)
        if lineup_locked:
            notes.append(f"confirmed lineup K pressure {avg_k*100:.1f}%")
        else:
            notes.append(f"projected lineup K pressure {avg_k*100:.1f}%")
        score_parts.append((lu_score, 0.25))

    # 2) Pitch-Type Matchup — already applied by build_pitch_type_matchup_profile/apply_advanced...;
    # do not apply it again. Just score the quality/availability for UI/audit.
    mp = matchup_profile or {}
    if mp.get("available"):
        rows = mp.get("rows") or []
        factor = safe_float(mp.get("factor"), 1.0) or 1.0
        pitch_score = clamp(50 + ((factor - 1.0) / 0.035) * 15, 35, 65)
        profile["pitch_type_context"] = "ACTIVE_ALREADY_APPLIED"
        notes.append(f"pitch-type matchup already applied x{factor:.3f}")
        score_parts.append((pitch_score, 0.20))
    else:
        profile["pitch_type_context"] = "NO_REAL_BATTER_MATCHUP"

    # 3) Batter Whiff Pressure — use batter pitch-type rows if available; micro-only.
    batter_rows = mp.get("batter_rows") or []
    whiffs = []
    for br in batter_rows:
        w = safe_float(br.get("Per-Batter Whiff%"))
        if w is not None:
            whiffs.append(w / 100.0 if w > 1 else w)
    if len(whiffs) >= 12:
        avg_whiff = float(np.mean(whiffs))
        profile["batter_whiff_pressure"] = round(avg_whiff * 100, 1)
        whiff_score = clamp(50 + ((avg_whiff - 0.255) / 0.070) * 18, 30, 70)
        notes.append(f"batter whiff pressure {avg_whiff*100:.1f}%")
        score_parts.append((whiff_score, 0.30))

    # 4) CSW Synergy — pitcher CSW plus batter whiff susceptibility; micro-only.
    sp = statcast_profile or {}
    csw = safe_float(sp.get("csw"))
    if csw is not None and len(whiffs) >= 12:
        avg_whiff = float(np.mean(whiffs))
        # Synergy only when both pitcher CSW and lineup whiff pressure point same direction.
        synergy_raw = ((csw - 0.285) / 0.055) * 0.55 + ((avg_whiff - 0.255) / 0.070) * 0.45
        synergy_score = clamp(50 + synergy_raw * 14, 35, 65)
        profile["csw_synergy"] = round(synergy_score, 1)
        notes.append(f"CSW synergy pitcher {csw*100:.1f}% + batter whiff {avg_whiff*100:.1f}%")
        score_parts.append((synergy_score, 0.25))

    if not score_parts:
        profile["note"] = "K context upgrade neutral: no additional non-duplicate batter context available"
        return profile

    total_w = sum(w for _, w in score_parts) or 1.0
    score = sum(v * w for v, w in score_parts) / total_w
    score = float(clamp(score, 35, 65))

    if score >= 58:
        label = "PLUS_K_CONTEXT"
    elif score <= 42:
        label = "LOW_K_CONTEXT"
    else:
        label = "NEUTRAL_K_CONTEXT"

    # Micro capped factor; this is intentionally small to protect a winning K core.
    factor = 1.0 + ((score - 50.0) / 50.0) * 0.035
    factor = float(clamp(factor, 0.985, 1.015))

    profile.update({
        "available": True,
        "score": round(score, 1),
        "label": label,
        "k_factor": round(factor, 4),
        "note": f"{label}: score {score:.1f}/100; micro x{factor:.3f}; " + "; ".join(notes),
    })
    return profile


def apply_k_context_no_duplicate_adjustment(pitcher_k, context_profile=None, enabled=True):
    if not enabled or not context_profile or not context_profile.get("available"):
        note = (context_profile or {}).get("note", "K context no-duplicate adjustment unavailable")
        return pitcher_k, note
    factor = safe_float(context_profile.get("k_factor"), 1.0) or 1.0
    return clamp(pitcher_k * factor, 0.08, 0.50), context_profile.get("note", f"K context x{factor:.3f}")

