# =========================
# PITCHER FS TRAFFIC / TRUE-OUTCOME LAYER
# Version: PITCHER_FS_TRAFFIC_ONLY_2026_06_17
#
# Scope:
# - Pitcher Fantasy only.
# - K PROJ / K Upside math is intentionally untouched.
# - Adds ER, expected hits allowed, expected walks allowed, WHIP/traffic, win/QS audit
#   into the Pitcher FS calculation so fantasy scoring understands manager-hook/run-damage risk.
# =========================
PITCHER_FS_TRAFFIC_ONLY_VERSION = "PITCHER_FS_TRAFFIC_ONLY_2026_06_17"

_prev_pitcher_fs_board_traffic_only = build_pitcher_fs_board

def _pfs_to_num(x, default=0.0):
    try:
        if x in (None, "", "—"):
            return default
        v = float(x)
        if pd.isna(v):
            return default
        return v
    except Exception:
        return default

def _pfs_cap(x, lo, hi, default=0.0):
    try:
        return max(lo, min(hi, float(x)))
    except Exception:
        return default

def _pfs_raw_lookup(board, pitcher, matchup):
    pn = str(pitcher or "").strip().lower()
    mt = str(matchup or "").strip().lower()
    for p in board or []:
        if not isinstance(p, dict):
            continue
        name = str(p.get("pitcher") or p.get("Pitcher") or p.get("Player") or "").strip().lower()
        game = str(p.get("matchup") or p.get("Matchup") or p.get("Game") or "").strip().lower()
        if name == pn and (not mt or game == mt):
            return p
    for p in board or []:
        if not isinstance(p, dict):
            continue
        name = str(p.get("pitcher") or p.get("Pitcher") or p.get("Player") or "").strip().lower()
        if name == pn:
            return p
    return {}

def _pfs_first_num(d, keys, default=None):
    for k in keys:
        if isinstance(d, dict) and k in d:
            v = _pfs_to_num(d.get(k), None)
            if v is not None:
                return v
    return default

def _pfs_estimate_hits_walks(row, raw):
    ip = _pfs_cap(row.get("IP Projection"), 0.1, 8.0, 5.0)

    h9 = _pfs_first_num(raw, [
        "H/9", "Hits/9", "Hit/9", "hits_per_9", "h_per_9", "Season H/9", "Recent H/9"
    ], None)
    bb9 = _pfs_first_num(raw, [
        "BB/9", "Walks/9", "Walk/9", "bb_per_9", "walks_per_9", "Season BB/9", "Recent BB/9"
    ], None)
    whip = _pfs_first_num(raw, ["WHIP", "whip", "Season WHIP", "Recent WHIP"], None)

    if bb9 is None:
        bb_rate = _pfs_first_num(raw, ["BB%", "Walk%", "walk_rate", "bb_rate"], None)
        if bb_rate is not None:
            if bb_rate > 1:
                bb_rate = bb_rate / 100.0
            bf = _pfs_to_num(row.get("Expected BF") or row.get("Exp BF") or raw.get("expected_bf") or raw.get("Exp BF"), ip * 4.25)
            bb9 = _pfs_cap((bf * bb_rate) / max(ip, 0.1) * 9.0, 0.4, 6.5, 2.8)
        else:
            bb9 = 2.8

    if h9 is None:
        if whip is not None:
            h9 = _pfs_cap((whip * 9.0) - bb9, 4.5, 12.5, 8.1)
        else:
            h9 = 8.1

    h9 = _pfs_cap(h9, 4.5, 13.5, 8.1)
    bb9 = _pfs_cap(bb9, 0.4, 7.0, 2.8)

    hits_allowed = _pfs_cap(ip * h9 / 9.0, 0.2, 12.0, ip * 0.9)
    walks_allowed = _pfs_cap(ip * bb9 / 9.0, 0.0, 6.0, ip * 0.32)
    whip_proj = _pfs_cap((hits_allowed + walks_allowed) / max(ip, 0.1), 0.55, 2.4, 1.25)

    return hits_allowed, walks_allowed, whip_proj, h9, bb9

def _pfs_traffic_label(whip, er_proj, ip):
    if whip >= 1.55 or er_proj >= 4.0:
        return "HIGH_TRAFFIC / HOOK_RISK"
    if whip <= 1.05 and er_proj <= 2.2 and ip >= 5.5:
        return "CLEAN_VOLUME_PROFILE"
    return "NORMAL_TRAFFIC"

def build_pitcher_fs_board(board=None):
    df = _prev_pitcher_fs_board_traffic_only(board)
    if df is None or df.empty:
        return df
    out = []
    for _, rr in df.iterrows():
        row = rr.to_dict()
        raw = _pfs_raw_lookup(board, row.get("Pitcher"), row.get("Matchup"))
        try:
            k_proj = _pfs_cap(row.get("K Projection"), 0.0, 14.0, 4.5)
            ip_proj = _pfs_cap(row.get("IP Projection"), 1.0, 8.0, 5.0)
            er_proj = _pfs_cap(row.get("ER Projection"), 0.0, 7.0, 2.5)
            win_pct = _pfs_cap(row.get("Win %"), 0.0, 100.0, 50.0)
            qs_pct = _pfs_cap(row.get("QS %"), 0.0, 100.0, 15.0)
            hits_allowed, walks_allowed, whip_proj, h9, bb9 = _pfs_estimate_hits_walks(row, raw)

            # Underdog-style pitcher fantasy audit with traffic/run-damage context.
            # K Upside is untouched; this only recalculates Pitcher FS.
            base_positive = (ip_proj * 3.0) + (k_proj * 3.0) + ((win_pct / 100.0) * 5.0) + ((qs_pct / 100.0) * 5.0)
            run_damage_penalty = er_proj * 3.0
            traffic_penalty = (hits_allowed * 0.60) + (walks_allowed * 0.75)
            fs = base_positive - run_damage_penalty - traffic_penalty

            # Small hook-risk tax only when projected traffic is genuinely high.
            hook_tax = 0.0
            if whip_proj >= 1.55:
                hook_tax -= 0.65
            elif whip_proj >= 1.40:
                hook_tax -= 0.35
            if er_proj >= 4.0:
                hook_tax -= 0.45
            fs += hook_tax

            fs = _pfs_cap(fs, 2.0, 52.0, _pfs_to_num(row.get("FS Projection"), 18.0))
            floor = _pfs_cap(fs - 5.25 - max(0.0, whip_proj - 1.25) * 2.5, 0.0, fs, fs * 0.65)
            ceiling = _pfs_cap(fs + 4.5 + k_proj * 0.25, fs + 1.0, 58.0, fs + 5.5)

            row.update({
                "FS Projection": round(fs, 2),
                "Floor": round(floor, 2),
                "Median": round(fs, 2),
                "Ceiling": round(ceiling, 2),
                "Confidence %": _fs_conf(fs, floor, ceiling) if "_fs_conf" in globals() else row.get("Confidence %", "—"),
                "Expected Hits Allowed": round(hits_allowed, 2),
                "Expected Walks Allowed": round(walks_allowed, 2),
                "Projected WHIP": round(whip_proj, 2),
                "Projected H/9": round(h9, 2),
                "Projected BB/9": round(bb9, 2),
                "Run Damage Penalty": round(run_damage_penalty, 2),
                "Traffic Penalty": round(traffic_penalty, 2),
                "Hook Risk Tax": round(hook_tax, 2),
                "Traffic Label": _pfs_traffic_label(whip_proj, er_proj, ip_proj),
                "Pitcher FS Formula": "IP*3 + K*3 + Win*5 + QS*5 - ER*3 - H*0.60 - BB*0.75",
                "Pitcher FS Version": PITCHER_FS_TRAFFIC_ONLY_VERSION,
            })
        except Exception:
            row["Pitcher FS Version"] = PITCHER_FS_TRAFFIC_ONLY_VERSION + "_FALLBACK"
        out.append(row)
    return pd.DataFrame(out)

def render_pitcher_fs_scoring_audit_card(df):
    try:
        if df is None or df.empty:
            return
        st.markdown("#### Pitcher FS Scoring Audit")
        cols = [c for c in [
            "Pitcher", "Matchup", "FS Projection", "K Projection", "IP Projection", "ER Projection",
            "Expected Hits Allowed", "Expected Walks Allowed", "Projected WHIP", "Win %", "QS %",
            "Traffic Label", "Pitcher FS Version"
        ] if c in df.columns]
        st.dataframe(df[cols].head(20), use_container_width=True, hide_index=True)
    except Exception:
        pass

_prev_render_pitcher_fs_tab_traffic_only = render_pitcher_fs_tab

def render_pitcher_fs_tab(board=None):
    st.subheader("Pitcher Fantasy — True Outcome / Traffic Adjusted")
    st.caption("K Upside is untouched. Pitcher FS uses K, IP, ER, projected hits allowed, projected walks allowed, Win%, QS%, and traffic/hook risk.")
    df = build_pitcher_fs_board(board)
    if df is None or df.empty:
        st.info("No Pitcher FS rows yet. Refresh K PROJ / UPSIDE first.")
        return
    df = df.sort_values("FS Projection", ascending=False)
    st.dataframe(df, use_container_width=True, hide_index=True)
    render_pitcher_fs_scoring_audit_card(df)
    try:
        _render_fs_cards(df, kind="pitcher")
    except Exception:
        pass

# =============================================================
# OPPONENT TEAM K RANK ENGINE 3.1 — VERIFIED SOURCE SAFE ADD-ON
# Source priority: MLB.com official team hitting leaderboard endpoint (BDFED),
# with neutral fallback to existing Opp K% if live data is unavailable.
# Safe rules:
# - DOES NOT change K projections, IP projections, BF projections, odds, or player decisions.
# - Adds context/export columns only.
# - Uses pitcher handedness to choose opponent K% vs RHP/LHP when available.
# =============================================================
OPP_K_RANK_ENGINE_VERSION = "OPP_TEAM_K_RANK_3_3_MLB_OFFICIAL_BATTER_K_AND_PITCHER_STRENGTH_2026_06_25"

try:
    import datetime as _okr_dt
except Exception:
    _okr_dt = None


def _okr_num(x, default=None):
    try:
        if x is None or x == "":
            return default
        if isinstance(x, str):
            x = x.replace("%", "").replace(",", "").strip()
        v = float(x)
        if math.isnan(v):
            return default
        return v
    except Exception:
        try:
            return safe_float(x, default)
        except Exception:
            return default


def _okr_abbr(x):
    s = str(x or "").strip().upper()
    if not s:
        return ""
    aliases = {
        "WSN": "WSH", "WAS": "WSH", "WASHINGTON": "WSH", "WASHINGTON NATIONALS": "WSH",
        "CHW": "CWS", "CHISOX": "CWS", "CHICAGO WHITE SOX": "CWS", "WHITE SOX": "CWS",
        "KCR": "KC", "KAN": "KC", "KANSAS CITY": "KC", "KANSAS CITY ROYALS": "KC",
        "TBR": "TB", "TAM": "TB", "TAMPA BAY": "TB", "TAMPA BAY RAYS": "TB",
        "SDP": "SD", "SAN DIEGO": "SD", "SAN DIEGO PADRES": "SD",
        "SFG": "SF", "SAN FRANCISCO": "SF", "SAN FRANCISCO GIANTS": "SF",
        "OAK": "ATH", "ATHLETICS": "ATH", "A'S": "ATH", "ATHLETICS ATHLETICS": "ATH",
        "ARI": "AZ", "ARIZONA": "AZ", "ARIZONA DIAMONDBACKS": "AZ",
        "LAA": "LAA", "LOS ANGELES ANGELS": "LAA", "ANGELS": "LAA",
        "LAD": "LAD", "LOS ANGELES DODGERS": "LAD", "DODGERS": "LAD",
        "NYM": "NYM", "NEW YORK METS": "NYM", "METS": "NYM",
        "NYY": "NYY", "NEW YORK YANKEES": "NYY", "YANKEES": "NYY",
        "TOR": "TOR", "TORONTO": "TOR", "TORONTO BLUE JAYS": "TOR", "BLUE JAYS": "TOR",
        "COL": "COL", "COLORADO": "COL", "COLORADO ROCKIES": "COL", "ROCKIES": "COL",
        "PIT": "PIT", "PITTSBURGH": "PIT", "PITTSBURGH PIRATES": "PIT", "PIRATES": "PIT",
        "CIN": "CIN", "REDS": "CIN", "CINCINNATI REDS": "CIN",
        "BAL": "BAL", "ORIOLES": "BAL", "BALTIMORE ORIOLES": "BAL",
    }
    if s in aliases:
        return aliases[s]
    # common MLB abbrevs pass through
    return s[:3] if len(s) > 3 and " " not in s else s


def _okr_field(d, names):
    if not isinstance(d, dict):
        return None
    low = {str(k).lower(): k for k in d.keys()}
    for name in names:
        if name in d:
            return d.get(name)
        lk = str(name).lower()
        if lk in low:
            return d.get(low[lk])
    return None


def _okr_extract_stat_rows(payload):
    if not isinstance(payload, dict):
        return []
    for key in ["stats", "rows", "data", "teams", "results"]:
        v = payload.get(key)
        if isinstance(v, list):
            return v
    # BDFED sometimes wraps under stats/items-like objects
    for v in payload.values():
        if isinstance(v, list) and v and isinstance(v[0], dict):
            return v
    return []


def _okr_parse_team_stat_rows(rows, split_label, source_label):
    parsed = []
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        team_obj = r.get("team") if isinstance(r.get("team"), dict) else {}
        ab = (_okr_field(r, ["teamAbbrev", "teamAbbreviation", "abbreviation", "teamCode", "team", "teamName"]) or
              _okr_field(team_obj, ["abbreviation", "teamCode", "name", "teamName"]))
        ab = _okr_abbr(ab)
        if not ab:
            continue
        # MLB/BDFED names vary. Try every common variant.
        so = _okr_num(_okr_field(r, ["strikeouts", "strikeOuts", "so", "SO", "strike_outs", "k", "K"]), None)
        pa = _okr_num(_okr_field(r, ["plateAppearances", "plate_appearances", "pa", "PA"]), None)
        k_pct_raw = _okr_num(_okr_field(r, ["strikeoutRate", "strikeOutRate", "kRate", "kPercent", "kPct", "K%", "strikeoutPct"]), None)
        # Some endpoints return K% as 24.1, some as .241.
        k_pct = None
        if k_pct_raw is not None:
            k_pct = k_pct_raw / 100.0 if k_pct_raw > 1 else k_pct_raw
        elif so is not None and pa and pa > 0:
            k_pct = so / pa
        if k_pct is None:
            continue
        parsed.append({
            "Team": ab,
            "Split": split_label,
            "SO": so,
            "PA": pa,
            "K%": float(k_pct),
            "Source": source_label,
        })
    return parsed


def _okr_mlb_season():
    try:
        # Prefer the app slate date/session if present; otherwise current year.
        y = int(st.session_state.get("season", 0) or 0)
        if 2000 <= y <= 2100:
            return y
    except Exception:
        pass
    try:
        return int((_okr_dt.date.today() if _okr_dt else None).year)
    except Exception:
        return 2026


def _okr_fetch_bdfed_split(season, sit_code=None, last30=False, lookback_days=None):
    """Official MLB.com stats backend used by MLB Stats pages. Returns parsed rows or []."""
    try:
        import requests
        base = "https://bdfed.stitch.mlbinfra.com/bdfed/stats/team"
        params = {
            "stitch_env": "prod",
            "sportId": 1,
            "gameType": "R",
            "group": "hitting",
            "stats": "season",
            "season": int(season),
            "limit": 30,
            "offset": 0,
            "sortStat": "strikeouts",
            "order": "desc",
        }
        if sit_code:
            params["sitCodes"] = sit_code
        days = int(lookback_days or (30 if last30 else 0))
        if days > 0 and _okr_dt:
            end = _okr_dt.date.today()
            start = end - _okr_dt.timedelta(days=days)
            # BDFED commonly honors startDate/endDate. The response is validated downstream
            # through PA/sample-size reliability before recent form can affect projections.
            params["startDate"] = start.strftime("%Y-%m-%d")
            params["endDate"] = end.strftime("%Y-%m-%d")
        r = requests.get(base, params=params, timeout=12, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code != 200:
            return []
        payload = r.json()
        return _okr_parse_team_stat_rows(_okr_extract_stat_rows(payload), "", "MLB.com official team stats")
    except Exception:
        return []


def _okr_rank_rows(rows, split_key_name):
    """Rank official MLB team batter strikeout environment.

    Rank 1 is most strikeout-prone. Keep both K% rank and raw SO rank:
    K% rank = SO / PA, best for projections; raw SO rank = StatMuse-style check.
    """
    base_rows = [dict(r) for r in rows or [] if r.get("Team") and _okr_num(r.get("K%"), None) is not None]
    rows_k = sorted(base_rows, key=lambda x: x.get("K%", 0), reverse=True)
    rows_so = sorted([r for r in base_rows if _okr_num(r.get("SO"), None) is not None], key=lambda x: _okr_num(x.get("SO"), 0), reverse=True)
    so_rank_map = {_okr_abbr(r.get("Team")): i for i, r in enumerate(rows_so, start=1)}
    out = {}
    for i, r in enumerate(rows_k, start=1):
        ab = _okr_abbr(r.get("Team"))
        so_val = _okr_num(r.get("SO"), None)
        pa_val = _okr_num(r.get("PA"), None)
        out[ab] = {
            f"K% {split_key_name}": round(float(r.get("K%", 0)) * 100, 1),
            f"K Rank {split_key_name}": i,
            f"SO {split_key_name}": int(so_val) if so_val is not None else "",
            f"PA {split_key_name}": int(pa_val) if pa_val is not None else "",
            f"SO Rank {split_key_name}": so_rank_map.get(ab, ""),
            f"K Source {split_key_name}": r.get("Source", ""),
        }
    return out


def _okr_cache_fetch_table(season=None):
    season = season or _okr_mlb_season()
    # sitCodes convention on MLB Stats API/BDFED: vr = batting vs RHP, vl = batting vs LHP.
    splits = {
        "Overall": _okr_fetch_bdfed_split(season, None, False),
        "vs RHP": _okr_fetch_bdfed_split(season, "vr", False),
        "vs LHP": _okr_fetch_bdfed_split(season, "vl", False),
        "L3 Overall": _okr_fetch_bdfed_split(season, None, lookback_days=3),
        "L3 vs RHP": _okr_fetch_bdfed_split(season, "vr", lookback_days=3),
        "L3 vs LHP": _okr_fetch_bdfed_split(season, "vl", lookback_days=3),
        "L5 Overall": _okr_fetch_bdfed_split(season, None, lookback_days=5),
        "L5 vs RHP": _okr_fetch_bdfed_split(season, "vr", lookback_days=5),
        "L5 vs LHP": _okr_fetch_bdfed_split(season, "vl", lookback_days=5),
        "L10 Overall": _okr_fetch_bdfed_split(season, None, lookback_days=10),
        "L10 vs RHP": _okr_fetch_bdfed_split(season, "vr", lookback_days=10),
        "L10 vs LHP": _okr_fetch_bdfed_split(season, "vl", lookback_days=10),
        "L15 Overall": _okr_fetch_bdfed_split(season, None, lookback_days=15),
        "L15 vs RHP": _okr_fetch_bdfed_split(season, "vr", lookback_days=15),
        "L15 vs LHP": _okr_fetch_bdfed_split(season, "vl", lookback_days=15),
        "L30 Overall": _okr_fetch_bdfed_split(season, None, lookback_days=30),
        "L30 vs RHP": _okr_fetch_bdfed_split(season, "vr", lookback_days=30),
        "L30 vs LHP": _okr_fetch_bdfed_split(season, "vl", lookback_days=30),
    }
    # If last-30 pull fails or is ignored, keep blanks rather than faking ranks.
    merged = {}
    for split_name, rows in splits.items():
        ranked = _okr_rank_rows(rows, split_name)
        for ab, vals in ranked.items():
            merged.setdefault(ab, {"Team": ab}).update(vals)
    return merged

# Streamlit cache wrapper, if Streamlit is available.
try:
    _okr_fetch_team_k_table = st.cache_data(ttl=6*60*60, show_spinner=False)(_okr_cache_fetch_table)
except Exception:
    _okr_fetch_team_k_table = _okr_cache_fetch_table


def _okr_matchup_teams(matchup):
    s = str(matchup or "").upper().replace("VS", "@").replace(" AT ", " @ ")
    if "@" in s:
        a, h = [x.strip() for x in s.split("@", 1)]
        return _okr_abbr(a), _okr_abbr(h)
    return "", ""


def _okr_pitcher_team_from_board_item(p):
    if not isinstance(p, dict):
        return ""
    for k in ["team", "Team", "Pitcher Team", "pitcher_team", "abbr", "team_abbr", "player_team", "Player Team"]:
        v = p.get(k)
        if v not in [None, "", "—"]:
            return _okr_abbr(v)
    return ""


def _okr_pitcher_hand_from_any(row=None, p=None):
    sources = []
    if isinstance(row, dict):
        sources.append(row)
    if isinstance(p, dict):
        sources.append(p)
    if "_mlb_pitcher_throw_hand" in globals():
        for src in sources:
            try:
                pid = None
                for k in ("APP97 Pitcher Player ID", "pitcher_id", "Pitcher ID", "player_id", "playerId", "mlb_id", "MLB ID", "id"):
                    if src.get(k) not in (None, "", "—"):
                        pid = src.get(k)
                        break
                nm = src.get("Pitcher") or src.get("pitcher") or src.get("Player") or src.get("fullName") or ""
                official = _mlb_pitcher_throw_hand(pid, nm)
                if official in {"LHP", "RHP"}:
                    return official
            except Exception:
                pass
    keys = ["Pitcher Hand", "pitcher_hand", "Throws", "Throwing Hand", "Hand", "hand", "P Hand", "p_throws", "throws", "arm", "Pitcher Throws", "pitcher_throws", "throwing_hand", "throws_hand"]
    txts = []
    for src in sources:
        for k in keys:
            try:
                v = src.get(k)
                if v not in [None, "", "—"]:
                    txts.append(str(v).strip().upper())
            except Exception:
                pass
    txt = " ".join(txts)
    if "LHP" in txt or "LEFT" in txt or txt in ["L", "LH"]:
        return "LHP"
    if "RHP" in txt or "RIGHT" in txt or txt in ["R", "RH"]:
        return "RHP"
    for t in txts:
        if t in ["L", "LH", "LHP"]:
            return "LHP"
        if t in ["R", "RH", "RHP"]:
            return "RHP"
    return "UNKNOWN"


def _okr_environment_label(rank, k_pct):
    r = _okr_num(rank, None)
    k = _okr_num(k_pct, None)
    if r is None and k is None:
        return "NO VERIFIED TEAM K RANK"
    if (r is not None and r <= 5) or (k is not None and k >= 25.0):
        return "🔥 ELITE K MATCHUP"
    if (r is not None and r <= 10) or (k is not None and k >= 23.5):
        return "🟢 GOOD K MATCHUP"
    if (r is not None and r >= 26) or (k is not None and k <= 18.5):
        return "🔴 ELITE CONTACT TEAM"
    if (r is not None and r >= 21) or (k is not None and k <= 20.5):
        return "🟠 CONTACT RISK"
    return "🟡 NEUTRAL K MATCHUP"


def _okr_pitcher_strength_label(rank, k_pct):
    """Display-only pitcher K-strength label from the current projection board.
    Rank #1 = highest pitcher strikeout percentage on the current board.
    """
    r = _okr_num(rank, None)
    k = _okr_num(k_pct, None)
    if k is not None and abs(k) <= 1:
        k *= 100.0
    if r is None and k is None:
        return "PITCHER K% UNKNOWN"
    if (r is not None and r <= 5) or (k is not None and k >= 28.0):
        return "🔥 ELITE PITCHER K%"
    if (r is not None and r <= 10) or (k is not None and k >= 25.0):
        return "🟢 STRONG PITCHER K%"
    if k is not None and k <= 18.5:
        return "🟠 LOW PITCHER K%"
    return "🟡 AVERAGE PITCHER K%"






# DISPLAY-ONLY FIX: compute Pitcher K% board ranks from the FULL visible slate, not from a one-card row.
# This does NOT change projections, decisions, simulations, learning, or grading.
def _owp_apply_pitcher_k_board_ranks_display_only(df):
    """Assign slate-wide Pitcher K% board ranks after the full projection board is built.

    Previously, pitcher cards could build a one-player table for display syncing; if rank was
    calculated on that one-row table, every card could show Board Rank #1. This function ranks
    the full displayed dataframe only, stores the rank map in session_state, and leaves all model
    projection columns untouched.
    """
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return df
        d = df.copy()
        if "Pitcher" not in d.columns:
            return d
        if "Pitcher K%" not in d.columns:
            d["Pitcher K% Board Rank"] = "—"
            d["Pitcher K% Strength Label"] = "PITCHER K% UNKNOWN"
            d["Pitcher K% Rank Source"] = "Full visible projection board | unavailable"
            return d

        vals = []
        for idx, row in d.iterrows():
            try:
                v = safe_float(row.get("Pitcher K%"), None)
            except Exception:
                v = None
            if v is None:
                continue
            # App stores K% as decimal in most places; display/export uses percent.
            if abs(float(v)) <= 1:
                v = float(v) * 100.0
            vals.append((idx, float(v)))

        # Stable competition ranking: ties get same rank, next rank skips accordingly.
        ranked = sorted(vals, key=lambda x: (-x[1], str(d.loc[x[0]].get("Pitcher", ""))))
        rank_map = {}
        last_val = None
        last_rank = 0
        for pos, (idx, v) in enumerate(ranked, start=1):
            if last_val is None or abs(v - last_val) > 1e-9:
                last_rank = pos
                last_val = v
            rank_map[idx] = last_rank

        d["Pitcher K% Board Rank"] = [rank_map.get(idx, "—") for idx in d.index]
        d["Pitcher K% Strength Label"] = [
            _okr_pitcher_strength_label(rank_map.get(idx, None), safe_float(d.loc[idx].get("Pitcher K%"), None))
            for idx in d.index
        ]
        d["Pitcher K% Rank Source"] = "Full visible projection board | rank #1 = highest Pitcher K%"

        # Store lookup for the mobile player cards, which rebuild a one-row table for card sync.
        card_map = {}
        for idx, row in d.iterrows():
            nm = str(row.get("Pitcher") or "").strip()
            if not nm:
                continue
            key = nm.lower()
            card_map[key] = {
                "rank": rank_map.get(idx, "—"),
                "label": row.get("Pitcher K% Strength Label", "—"),
                "source": "Full visible projection board | rank #1 = highest Pitcher K%",
            }
        try:
            st.session_state["_owp_pitcher_k_full_board_rank_map"] = card_map
        except Exception:
            pass
        return d
    except Exception:
        return df


def _owp_overlay_full_board_pitcher_k_rank(card_row):
    """Overlay the full-board rank onto a one-player card row; display-only."""
    try:
        if not isinstance(card_row, dict):
            return card_row
        nm = str(card_row.get("Pitcher") or card_row.get("pitcher") or "").strip().lower()
        if not nm:
            return card_row
        rank_map = st.session_state.get("_owp_pitcher_k_full_board_rank_map", {})
        info = rank_map.get(nm)
        if not info:
            return card_row
        out = dict(card_row)
        out["Pitcher K% Board Rank"] = info.get("rank", "—")
        out["Pitcher K% Strength Label"] = info.get("label", out.get("Pitcher K% Strength Label", "—"))
        out["Pitcher K% Rank Source"] = info.get("source", "Full visible projection board | rank #1 = highest Pitcher K%")
        return out
    except Exception:
        return card_row

def _okr_mi_adaptive_weight_profile(rec, hand):
    """Sample-aware team K% trend versus the pitcher's handedness.

    Uses official MLB team hitting splits for L3/L5/L10/L15/L30 plus season.
    Very short windows are deliberately low weight and every recent window is
    shrunk by its PA reliability so one noisy series cannot hijack the model.
    """
    try:
        rec = rec or {}
        hand = str(hand or '').upper()
        split = 'vs LHP' if hand == 'LHP' else 'vs RHP' if hand == 'RHP' else None
        if not split:
            return None
        windows = ('L3','L5','L10','L15','L30')
        vals = {w: _okr_num(rec.get(f'K% {w} {split}'), None) for w in windows}
        pas = {w: _okr_num(rec.get(f'PA {w} {split}'), None) for w in windows}
        season_v = _okr_num(rec.get(f'K% {split}'), None)
        if season_v is None:
            season_v = _okr_num(rec.get('K% Overall'), None)
        if season_v is None:
            return None

        # Intentionally conservative: L3 is a trend flag, not a major driver.
        targets = {'L3':0.05,'L5':0.15,'L10':0.20,'L15':0.20,'L30':0.15,'SEASON':0.25}
        full_pa = {'L3':90.0,'L5':150.0,'L10':280.0,'L15':400.0,'L30':750.0}
        rel = {}
        effective = {'SEASON': targets['SEASON']}
        shrink = 0.0
        for w in windows:
            pa = pas.get(w)
            rel[w] = 0.0 if pa is None or pa <= 0 else max(0.0, min(1.0, float(pa)/full_pa[w]))
            if vals.get(w) is None or rel[w] <= 0:
                effective[w] = 0.0
                shrink += targets[w]
            else:
                effective[w] = targets[w] * rel[w]
                shrink += targets[w] - effective[w]
        effective['SEASON'] += shrink
        total=sum(effective.values())
        if total <= 0:
            effective={w:0.0 for w in windows}; effective['SEASON']=1.0
        else:
            effective={k:float(v)/total for k,v in effective.items()}
        return {
            'split':split,'season':float(season_v),'values':vals,'pa':pas,
            'reliability':rel,'targets':targets,'effective':effective,
            'mode':'L3_L5_L10_L15_L30_SEASON_PA_SHRINK'
        }
    except Exception:
        return None

def _okr_mi_blended_k_pct(rec, hand):
    """Adaptive, sample-aware opponent K% blend in percent units."""
    try:
        profile = _okr_mi_adaptive_weight_profile(rec, hand)
        if not profile:
            return None, 'NO_VERIFIED_K_BLEND'

        eff = profile['effective']
        vals = profile['values']
        season_v = profile['season']
        split = profile['split']

        blend = float(season_v) * float(eff['SEASON'])
        details = [f"mode={profile['mode']}"]
        for name in ('L3', 'L5', 'L10', 'L15', 'L30'):
            val = vals.get(name)
            w = float(eff.get(name, 0.0))
            pa = profile['pa'].get(name)
            if val is not None and w > 0:
                blend += float(val) * w
                details.append(f"{w*100:.1f}% {name} {split}={float(val):.2f}% (PA {int(pa) if pa else 0})")
        details.append(f"{float(eff['SEASON'])*100:.1f}% season {split}={float(season_v):.2f}%")

        target_text = '/'.join(f"{profile['targets'][k]*100:.0f}" for k in ('L3','L5','L10','L15','L30','SEASON'))
        details.append(f"target L3/L5/L10/L15/L30/season={target_text}")
        return round(float(blend), 2), ' | '.join(details)
    except Exception:
        return None, 'K_RECENCY_BLEND_ERROR'

def _okr_mi_projection_nudge(row, rec, hand):
    """Small capped K-environment projection nudge from official MLB team K%.

    The verified K environment uses a sample-size-aware recency blend:
      L3 + L5 + L10 + L15 + L30 vs pitcher hand, anchored by season vs-hand K%.

    It then compares verified team K% to the model's existing opponent K%.
    ORIGINAL-ANCHOR TESTER: the adjustment is intentionally tiny and capped
    at +/-0.20 K so K Environment fine-tunes the original K projection without
    overpowering pitcher skill, BF/IP, leash, learning, or line-aware layers.
    """
    try:
        verified_k, blend_note = _okr_mi_blended_k_pct(rec, hand)
        if verified_k is None:
            return 0.0, 'MI_NO_VERIFIED_TEAM_K', '', verified_k

        current_k = _okr_num(row.get('Opp K%'), None)
        if current_k is None:
            current_k = _okr_num(row.get('Opponent K% vs Pitcher Hand'), None)

        if current_k is None:
            current_k = 22.2
            current_note = 'league_avg_fallback'
        else:
            if abs(current_k) <= 1:
                current_k *= 100.0
            current_note = 'existing_opp_k'

        bf = _okr_num(row.get('Exp BF'), None)
        if bf is None:
            bf = _okr_num(row.get('BF-K Expected BF 2.1'), None)

        if bf is None:
            bf = 22.0
            bf_note = 'bf_fallback_22'
        else:
            bf_note = 'exp_bf'

        raw = float(bf) * ((float(verified_k) - float(current_k)) / 100.0)

        # Original-anchor K Environment layer:
        # use only 12% of raw K-opportunity delta and cap at +/-0.20 Ks.
        # This keeps the regular K Upside projection close to the older
        # 18-11 style build while still allowing a small matchup fine-tune.
        weighted = raw * 0.12
        capped = max(-0.20, min(0.20, weighted))

        if capped >= 0.15:
            label = 'MI_K_ENV_PLUS'
        elif capped >= 0.05:
            label = 'MI_SMALL_K_ENV_PLUS'
        elif capped <= -0.15:
            label = 'MI_CONTACT_TAX'
        elif capped <= -0.05:
            label = 'MI_SMALL_CONTACT_TAX'
        else:
            label = 'MI_NEUTRAL'

        reason = (
            f'official MLB team K blend {verified_k:.2f}% ({blend_note}) '
            f'vs {current_note} {current_k:.2f}%; {bf_note} {bf:.1f}; '
            f'raw {raw:+.2f}K * 0.12 capped +/-0.20 = {capped:+.2f}K'
        )
        return round(float(capped), 2), label, reason, verified_k
    except Exception as e:
        return 0.0, 'MI_ERROR', str(e), None


def _okr_mi_decision_from_proj(proj, line, old_decision):
    """Simple card decision from the final displayed projection.

    Keeps NO LINE unchanged. Otherwise returns one clean label:
    OVER / OVER LEAN / UNDER / UNDER LEAN / PASS.
    """
    try:
        old = str(old_decision or '')
        if 'NO LINE' in old.upper() or 'NO_UD_LINE' in old.upper():
            return old_decision

        p = _okr_num(proj, None)
        l = _okr_num(line, None)
        if p is None or l is None:
            return old_decision

        edge = p - l
        # Original-anchor display gate: do not let a tiny K Environment nudge
        # flip a visible decision. Require a clearer gap for leans.
        if edge >= 1.00:
            return '🔥 OVER'
        if edge > 0.35:
            return '⚠️ OVER LEAN'
        if edge <= -1.00:
            return '🔥 UNDER'
        if edge < -0.35:
            return '⚠️ UNDER LEAN'
        return '🚫 PASS'
    except Exception:
        return old_decision

def _okr_apply_team_k_ranks_to_df(df, board=None):
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df
    d = df.copy()
    table = {}
    try:
        table = _okr_fetch_team_k_table(_okr_mlb_season()) or {}
    except Exception:
        table = {}

    board_lookup = {}
    try:
        for p in board or []:
            nm = str(p.get("pitcher") or p.get("Pitcher") or p.get("Player") or "").strip().lower()
            if nm:
                board_lookup[nm] = p
    except Exception:
        board_lookup = {}

    opp_teams, p_teams, hands = [], [], []
    k_hand, rank_hand, label_hand, source_hand = [], [], [], []
    k_rhp, r_rhp, k_lhp, r_lhp = [], [], [], []
    k_l3_rhp, r_l3_rhp, k_l3_lhp, r_l3_lhp = [], [], [], []
    k_l5_rhp, r_l5_rhp, k_l5_lhp, r_l5_lhp = [], [], [], []
    k_l10_rhp, r_l10_rhp, k_l10_lhp, r_l10_lhp = [], [], [], []
    k_l15_rhp, r_l15_rhp, k_l15_lhp, r_l15_lhp = [], [], [], []
    k_l30_rhp, r_l30_rhp, k_l30_lhp, r_l30_lhp = [], [], [], []
    k_overall, r_overall, so_overall, so_rank_overall, pa_overall = [], [], [], [], []
    k_l30_overall, r_l30_overall, so_l30_overall, so_rank_l30_overall, pa_l30_overall = [], [], [], [], []
    top5_note = []

    for _, row in d.iterrows():
        rd = row.to_dict()
        name_key = str(rd.get("Pitcher") or rd.get("pitcher") or "").strip().lower()
        p = board_lookup.get(name_key, {})
        matchup = rd.get("Matchup") or (p.get("matchup") if isinstance(p, dict) else "")
        away, home = _okr_matchup_teams(matchup)
        pt = _okr_pitcher_team_from_board_item(p) or _okr_abbr(rd.get("Team") or rd.get("Pitcher Team") or "")
        # If pitcher team unavailable, leave opponent blank instead of guessing wrong.
        opp = ""
        if pt and away and home:
            opp = home if pt == away else away if pt == home else ""
        # fallback: if board dict has opponent/team fields
        if not opp and isinstance(p, dict):
            for k in ["opponent", "Opponent", "opp", "Opp"]:
                if p.get(k):
                    opp = _okr_abbr(p.get(k)); break
        hand = _okr_pitcher_hand_from_any(rd, p)
        rec = table.get(opp, {}) if opp else {}
        vs_key = "vs LHP" if hand == "LHP" else "vs RHP" if hand == "RHP" else None
        k_used = rec.get(f"K% {vs_key}") if vs_key else None
        r_used = rec.get(f"K Rank {vs_key}") if vs_key else None
        src_used = rec.get(f"K Source {vs_key}") if vs_key else ""
        # fallback to existing row Opp K% only when verified table is missing; mark as fallback.
        if k_used in [None, "", "—"]:
            fallback = _okr_num(rd.get("Opp K%"), None)
            if fallback is not None:
                k_used = round(fallback if fallback > 1 else fallback * 100, 1)
                src_used = "Existing app Opp K% fallback — not ranked"
        label = _okr_environment_label(r_used, k_used)

        opp_teams.append(opp or "")
        p_teams.append(pt or "")
        hands.append(hand)
        k_hand.append(k_used if k_used is not None else "")
        rank_hand.append(r_used if r_used is not None else "")
        label_hand.append(label)
        source_hand.append(src_used or "")
        k_rhp.append(rec.get("K% vs RHP", "")); r_rhp.append(rec.get("K Rank vs RHP", ""))
        k_lhp.append(rec.get("K% vs LHP", "")); r_lhp.append(rec.get("K Rank vs LHP", ""))
        k_l3_rhp.append(rec.get("K% L3 vs RHP", "")); r_l3_rhp.append(rec.get("K Rank L3 vs RHP", ""))
        k_l3_lhp.append(rec.get("K% L3 vs LHP", "")); r_l3_lhp.append(rec.get("K Rank L3 vs LHP", ""))
        k_l5_rhp.append(rec.get("K% L5 vs RHP", "")); r_l5_rhp.append(rec.get("K Rank L5 vs RHP", ""))
        k_l5_lhp.append(rec.get("K% L5 vs LHP", "")); r_l5_lhp.append(rec.get("K Rank L5 vs LHP", ""))
        k_l10_rhp.append(rec.get("K% L10 vs RHP", "")); r_l10_rhp.append(rec.get("K Rank L10 vs RHP", ""))
        k_l10_lhp.append(rec.get("K% L10 vs LHP", "")); r_l10_lhp.append(rec.get("K Rank L10 vs LHP", ""))
        k_l15_rhp.append(rec.get("K% L15 vs RHP", "")); r_l15_rhp.append(rec.get("K Rank L15 vs RHP", ""))
        k_l15_lhp.append(rec.get("K% L15 vs LHP", "")); r_l15_lhp.append(rec.get("K Rank L15 vs LHP", ""))
        k_l30_rhp.append(rec.get("K% L30 vs RHP", "")); r_l30_rhp.append(rec.get("K Rank L30 vs RHP", ""))
        k_l30_lhp.append(rec.get("K% L30 vs LHP", "")); r_l30_lhp.append(rec.get("K Rank L30 vs LHP", ""))
        k_overall.append(rec.get("K% Overall", "")); r_overall.append(rec.get("K Rank Overall", ""))
        so_overall.append(rec.get("SO Overall", "")); so_rank_overall.append(rec.get("SO Rank Overall", "")); pa_overall.append(rec.get("PA Overall", ""))
        k_l30_overall.append(rec.get("K% L30 Overall", "")); r_l30_overall.append(rec.get("K Rank L30 Overall", ""))
        so_l30_overall.append(rec.get("SO L30 Overall", "")); so_rank_l30_overall.append(rec.get("SO Rank L30 Overall", "")); pa_l30_overall.append(rec.get("PA L30 Overall", ""))
        top5_note.append("TOP-5 K ENV" if _okr_num(r_used, 99) <= 5 or _okr_num(rec.get("K Rank Overall"), 99) <= 5 or _okr_num(rec.get("SO Rank Overall"), 99) <= 5 else "")

    d["Opponent Team"] = opp_teams
    d["Pitcher Team"] = p_teams
    d["Pitcher Hand"] = hands
    d["Opponent K% vs Pitcher Hand"] = k_hand
    d["Opponent K Rank vs Pitcher Hand"] = rank_hand
    d["Opponent K Environment"] = label_hand
    d["Opponent K Rank Source"] = source_hand
    d["Opp K% vs RHP Official"] = k_rhp
    d["Opp K Rank vs RHP Official"] = r_rhp
    d["Opp K% vs LHP Official"] = k_lhp
    d["Opp K Rank vs LHP Official"] = r_lhp
    d["Opp L3 K% vs RHP Official"] = k_l3_rhp
    d["Opp L3 K Rank vs RHP Official"] = r_l3_rhp
    d["Opp L3 K% vs LHP Official"] = k_l3_lhp
    d["Opp L3 K Rank vs LHP Official"] = r_l3_lhp
    d["Opp L5 K% vs RHP Official"] = k_l5_rhp
    d["Opp L5 K Rank vs RHP Official"] = r_l5_rhp
    d["Opp L5 K% vs LHP Official"] = k_l5_lhp
    d["Opp L5 K Rank vs LHP Official"] = r_l5_lhp
    d["Opp L10 K% vs RHP Official"] = k_l10_rhp
    d["Opp L10 K Rank vs RHP Official"] = r_l10_rhp
    d["Opp L10 K% vs LHP Official"] = k_l10_lhp
    d["Opp L10 K Rank vs LHP Official"] = r_l10_lhp
    d["Opp L15 K% vs RHP Official"] = k_l15_rhp
    d["Opp L15 K Rank vs RHP Official"] = r_l15_rhp
    d["Opp L15 K% vs LHP Official"] = k_l15_lhp
    d["Opp L15 K Rank vs LHP Official"] = r_l15_lhp
    d["Opp L30 K% vs RHP Official"] = k_l30_rhp
    d["Opp L30 K Rank vs RHP Official"] = r_l30_rhp
    d["Opp L30 K% vs LHP Official"] = k_l30_lhp
    d["Opp L30 K Rank vs LHP Official"] = r_l30_lhp
    d["Team Batter K% Overall Official"] = k_overall
    d["Team Batter K% Rank Overall Official"] = r_overall
    d["Team Batter SO Overall Official"] = so_overall
    d["Team Batter SO Rank Overall Official"] = so_rank_overall
    d["Team Batter PA Overall Official"] = pa_overall
    d["Team Batter K% L30 Overall Official"] = k_l30_overall
    d["Team Batter K% Rank L30 Overall Official"] = r_l30_overall
    d["Team Batter SO L30 Overall Official"] = so_l30_overall
    d["Team Batter SO Rank L30 Overall Official"] = so_rank_l30_overall
    d["Team Batter PA L30 Overall Official"] = pa_l30_overall
    d["Team Batter K Rank Source"] = "MLB.com official team hitting stats | K%=SO/PA | SO rank=raw strikeouts"
    d["Team Batter K Rank Source URL"] = "https://www.mlb.com/stats/team"
    d["Opponent K Top-5 Note"] = top5_note

    # Pitcher K% strength rank: display/export only, no projection change.
    try:
        pk_vals = []
        for idx, r in d.iterrows():
            v = _okr_num(r.get("Pitcher K%"), None)
            if v is not None and abs(v) <= 1:
                v *= 100.0
            pk_vals.append((idx, v))
        ranked_pk = sorted([(idx, v) for idx, v in pk_vals if v is not None], key=lambda x: x[1], reverse=True)
        pk_rank_map = {idx: rank for rank, (idx, v) in enumerate(ranked_pk, start=1)}
        d["Pitcher K% Board Rank"] = [pk_rank_map.get(idx, "") for idx in d.index]
        d["Pitcher K% Strength Label"] = [_okr_pitcher_strength_label(pk_rank_map.get(idx, None), _okr_num(d.loc[idx].get("Pitcher K%"), None)) for idx in d.index]
        d["Pitcher K% Rank Source"] = "Current projection board | rank #1 = highest Pitcher K%"
    except Exception:
        d["Pitcher K% Board Rank"] = ""
        d["Pitcher K% Strength Label"] = "PITCHER K% UNKNOWN"
        d["Pitcher K% Rank Source"] = "Unavailable"

    # One clean combo label for quick read; still display-only.
    try:
        d["Team K Read"] = d.apply(lambda r: f"{r.get('Opponent Team','—')} vs {r.get('Pitcher Hand','—')}: {r.get('Opponent K% vs Pitcher Hand','—')}% / #{r.get('Opponent K Rank vs Pitcher Hand','—')} | Overall K% #{r.get('Team Batter K% Rank Overall Official','—')} | SO Rank #{r.get('Team Batter SO Rank Overall Official','—')}", axis=1)
    except Exception:
        d["Team K Read"] = ""

    # Matchup Intelligence Projection Nudge — original-anchor light weight only.
    # Uses PA-shrunk L3/L5/L10/L15/L30 vs-hand K% plus season anchor; caps at +/-0.20 K.
    try:
        mi_pre, mi_adj, mi_final, mi_label, mi_reason, mi_verified, mi_blend_detail = [], [], [], [], [], [], []
        for idx, row in d.iterrows():
            rd = row.to_dict()
            opp = _okr_abbr(rd.get("Opponent Team"))
            hand = str(rd.get("Pitcher Hand") or "UNKNOWN")
            rec = table.get(opp, {}) if opp else {}
            base = _okr_num(rd.get("Line-Aware Smart Final K Projection"), None)
            if base is None:
                base = _okr_num(rd.get("K PROJ"), None)
            adj, lab, why, verified = _okr_mi_projection_nudge(rd, rec, hand)
            _, blend_detail = _okr_mi_blended_k_pct(rec, hand)
            final = base if base is None else round(max(0.0, float(base) + float(adj)), 2)
            mi_pre.append("" if base is None else round(float(base), 2))
            mi_adj.append(adj); mi_final.append("" if final is None else final); mi_label.append(lab); mi_reason.append(why); mi_verified.append("" if verified is None else round(float(verified), 2)); mi_blend_detail.append(blend_detail)
        d["Pre-Matchup Intel K Projection"] = mi_pre
        d["Matchup Intel K Nudge"] = mi_adj
        d["Matchup Intel Label"] = mi_label
        d["Matchup Intel Reason"] = mi_reason
        d["Matchup Intel Verified Team K%"] = mi_verified
        d["Recency Team K Blend Detail"] = mi_blend_detail
        d["Recency Team K Blend Method"] = "PA-shrunk L3/L5/L10/L15/L30/season vs hand; short windows are low weight and unsupported recent weight shrinks to season"
        d["Matchup Intelligence Final K Projection"] = mi_final
        d["Matchup Intelligence Version"] = "MATCHUP_INTEL_ADAPTIVE_RECENCY_L5_25_55_L15_L30_SEASON_PA_TREND_SHRINK_WEIGHT_0_12_CAP_0_20_2026_07_11"
        # Promote this as the final display/export projection, but record the pre-value above.
        for c in ["K PROJ", "Line-Aware Smart Final K Projection", "Final K Projection"]:
            if c in d.columns:
                d[c] = [f if f not in [None, ""] else o for f, o in zip(mi_final, d[c].tolist())]
        # Refresh edges from updated final projection.
        if "UD/Line" in d.columns:
            new_edges = []
            for f, ln in zip(mi_final, d["UD/Line"].tolist()):
                fv = _okr_num(f, None); lv = _okr_num(ln, None)
                new_edges.append("" if fv is None or lv is None else round(fv - lv, 2))
            for ec in ["Line-Aware Smart Edge", "Edge Gap", "Official K Edge", "Final K Edge"]:
                if ec in d.columns:
                    d[ec] = new_edges
            if "Line-Aware Smart Decision" in d.columns:
                d["Line-Aware Smart Decision"] = [_okr_mi_decision_from_proj(f, ln, old) for f, ln, old in zip(mi_final, d["UD/Line"].tolist(), d["Line-Aware Smart Decision"].tolist())]
            if "Decision" in d.columns:
                d["Decision"] = [_okr_mi_decision_from_proj(f, ln, old) for f, ln, old in zip(mi_final, d["UD/Line"].tolist(), d["Decision"].tolist())]
    except Exception as _mi_e:
        d["Matchup Intelligence Version"] = f"MATCHUP_INTEL_ERROR:{_mi_e}"

    d["Opponent K Rank Engine Version"] = OPP_K_RANK_ENGINE_VERSION
    return d


def _okr_top5_test_table():
    """Utility for Streamlit/debug: returns Top 5 team K environments by split from verified pull."""
    try:
        table = _okr_fetch_team_k_table(_okr_mlb_season()) or {}
        rows = []
        for team, rec in table.items():
            for split in ["Overall", "vs RHP", "vs LHP", "L5 Overall", "L5 vs RHP", "L5 vs LHP", "L15 Overall", "L15 vs RHP", "L15 vs LHP", "L30 Overall", "L30 vs RHP", "L30 vs LHP"]:
                rows.append({
                    "Split": split,
                    "Team": team,
                    "K%": rec.get(f"K% {split}"),
                    "K% Rank": rec.get(f"K Rank {split}"),
                    "SO": rec.get(f"SO {split}"),
                    "SO Rank": rec.get(f"SO Rank {split}"),
                    "Source": rec.get(f"K Source {split}"),
                })
        df = pd.DataFrame(rows)
        if df.empty:
            return df
        mask = df["K% Rank"].isin([1,2,3,4,5]) | df["SO Rank"].isin([1,2,3,4,5])
        return df[mask].sort_values(["Split", "K% Rank", "SO Rank"])
    except Exception:
        return pd.DataFrame()



