# =========================
# BETA TESTER — K V5 SHARED WORKLOAD / VOLATILITY / CONFIDENCE
# =========================
# This beta layer DOES NOT overwrite production K PROJ or K Upside math.
# It creates side-by-side tester columns using the new shared workload engine.
BETA_K_V5_VERSION = "BETA_K_V5_OG_PROJECTION_PO_AUDIT_2026_07_21"

def _beta_k_line(row):
    return _beta_num(_beta_first(row, ["UD/Line", "line", "Line", "K Line", "Underdog Line", "underdog_line"], None), None)

def _beta_k_current_projection(row):
    return _beta_num(_beta_first(row, ["Line-Aware Smart Final K Projection", "K PROJ", "projection", "Projection", "Median"], None), None)

def _beta_k_v5_decision(proj, line, confidence, flags=None):
    if line is None or proj is None:
        return "NO LINE", None, "NO_LINE"
    edge = round(float(proj) - float(line), 2)
    abs_edge = abs(edge)
    flags = flags or []
    risk_flags = [f for f in flags if f in ["LOW_SAMPLE", "ROLE_RISK", "RECENT_HOOK_RISK", "EARLY_PULL_RISK", "NON_TRADITIONAL_ROLE", "HIGH_IP_VOLATILITY"]]
    if abs_edge < 0.65:
        return "⏸️ PASS — THIN EDGE", edge, "edge < 0.65 K"
    if confidence < 55:
        return "⏸️ PASS — LOW CONF", edge, f"confidence {confidence:.0f}"
    if risk_flags and abs_edge < 1.00:
        return "⏸️ PASS — WORKLOAD RISK", edge, ",".join(risk_flags)
    side = "OVER" if edge > 0 else "UNDER"
    if abs_edge >= 1.35 and confidence >= 66 and not risk_flags:
        return f"🔥 {side}", edge, "strong beta edge + confidence"
    if abs_edge >= 0.85 and confidence >= 58:
        return f"⚠️ {side} LEAN", edge, "playable beta lean"
    return f"⏸️ PASS — {side} LEAN ONLY", edge, "lean but not enough confirmation"

def _beta_k_v5_projection(row):
    """Side-by-side K tester projection.

    Uses:
    - OG/current K projection as the projection source of truth
    - beta workload/IP/BF as an audit signal
    - IP volatility as confidence/risk, not a projection rewrite
    - strikeout conversion score
    - season/vs-hand/L30/batter K environment audit already built in V4
    - confidence penalty for volatility/role risk

    It intentionally returns new fields only and does not write to K PROJ. This
    keeps app-33/OG K projections aligned while app-32 Pitching Outs stays active.
    """
    try:
        ip_info = _beta_dynamic_ip(row)
        current_k = _beta_k_current_projection(row)
        workload_k_audit = _beta_shared_k_workload_projection(row, ip_info)
        if current_k is None:
            current_k = workload_k_audit
        if current_k is None:
            return {}
        conv_score, conv_label, k_env = _beta_strikeout_conversion_score(row, ip_info)
        conv_score = _beta_num(conv_score, 50.0)
        ip_conf = _beta_num(ip_info.get("Beta IP Confidence"), 50.0)
        ip_vol = _beta_num(ip_info.get("IP Volatility Score"), 50.0)
        flags_raw = ip_info.get("Beta Flags", [])
        flags = flags_raw if isinstance(flags_raw, list) else [str(flags_raw)] if flags_raw else []

        # Keep projection immutable. Workload/volatility now affects confidence
        # and decision only, because the OG/app-33 K projection is the source of truth.
        workload_risk_adj = 0.0
        if ip_vol >= 75:
            workload_risk_adj -= 0.075
            flags.append("HIGH_IP_VOLATILITY")
        elif ip_vol >= 65:
            workload_risk_adj -= 0.045
        elif ip_vol <= 35 and "DEEP_LEASH_SUPPORT" in flags:
            workload_risk_adj += 0.025
        elif ip_vol <= 42:
            workload_risk_adj += 0.010

        # Workload risk guardrails from losses: do not let thin plays ride through bad role/hook flags.
        if any(f in flags for f in ["ROLE_RISK", "RECENT_HOOK_RISK", "EARLY_PULL_RISK", "NON_TRADITIONAL_ROLE"]):
            workload_risk_adj -= 0.025
        if "DEEP_LEASH_SUPPORT" in flags:
            workload_risk_adj += 0.012
        workload_risk_adj = _beta_cap(workload_risk_adj, -0.12, 0.04)

        beta_k = round(_beta_cap(float(current_k), 0.2, 15.0), 2)

        line = _beta_k_line(row)
        edge = None if line is None else round(beta_k - float(line), 2)

        # Confidence/risk layer only.
        conf = 50.0
        if edge is not None:
            conf += _beta_cap(abs(edge) * 11.5, 0, 22)
        conf += _beta_cap((ip_conf - 50.0) * 0.42, -12, 15)
        conf += _beta_cap((conv_score - 50.0) * 0.35, -10, 13)
        conf -= _beta_cap((ip_vol - 50.0) * 0.45, -5, 18)
        conf += workload_risk_adj * 55.0
        if any(f in flags for f in ["LOW_SAMPLE"]): conf -= 7
        if any(f in flags for f in ["ROLE_RISK", "NON_TRADITIONAL_ROLE"]): conf -= 9
        if any(f in flags for f in ["RECENT_HOOK_RISK", "EARLY_PULL_RISK"]): conf -= 8
        if "DEEP_LEASH_SUPPORT" in flags: conf += 5
        conf = round(_beta_cap(conf, 20, 92), 0)

        decision, final_edge, reason = _beta_k_v5_decision(beta_k, line, conf, flags)
        env_note = k_env.get("note", "—") if isinstance(k_env, dict) else "—"
        env_pct = round(float(k_env.get("env_k", 0))*100, 1) if isinstance(k_env, dict) and k_env.get("env_k") is not None else "—"
        return {
            "Pitcher": _beta_first(row, ["pitcher", "Pitcher", "Player", "name"], "UNKNOWN"),
            "Matchup": _beta_first(row, ["matchup", "Matchup"], ""),
            "K Line": line if line is not None else "—",
            "Current K PROJ": current_k if current_k is not None else "—",
            "Beta K V5": beta_k,
            "Beta K Edge": final_edge if final_edge is not None else "—",
            "Beta K Decision": decision,
            "Beta K Confidence": conf,
            "Decision Reason": reason,
            "Original IP": ip_info.get("Original IP"),
            "Beta IP": ip_info.get("Beta IP"),
            "Beta BF": ip_info.get("Beta BF"),
            "IP Confidence": ip_info.get("Beta IP Confidence"),
            "IP Volatility Score": ip_info.get("IP Volatility Score"),
            "IP Volatility Label": ip_info.get("IP Volatility Label"),
            "Shared Workload K Audit": workload_k_audit if workload_k_audit is not None else "—",
            "Workload Confidence Adj": round(workload_risk_adj * 100, 1),
            "K Conversion Score": conv_score,
            "K Conversion Label": conv_label,
            "K Env Blend %": env_pct,
            "K Env Details": env_note,
            "Beta Flags": ", ".join(sorted(set(flags))) if flags else "",
            "Version": BETA_K_V5_VERSION,
        }
    except Exception as e:
        return {"Pitcher": _beta_first(row, ["pitcher", "Pitcher"], "UNKNOWN"), "Error": str(e), "Version": BETA_K_V5_VERSION}

def _beta_k_v5_rows(board):
    rows = []
    for p in board or []:
        rows.append(_beta_k_v5_projection(p))
    return pd.DataFrame(rows)

def render_beta_k_v5_tab(board):
    st.markdown('<div class="section-title-pro">⚾ K BETA V5 — Shared Workload Tester</div>', unsafe_allow_html=True)
    st.caption("Tester only. Uses beta IP/BF + volatility + K conversion confidence. Production K PROJ / Upside is not overwritten.")
    df = _beta_k_v5_rows(board)
    if df.empty:
        st.info("No beta K rows yet. Refresh the board first.")
        return
    c1, c2, c3 = st.columns(3)
    c1.metric("Rows", len(df))
    if "Beta K Confidence" in df.columns:
        c2.metric("Avg Confidence", f"{pd.to_numeric(df['Beta K Confidence'], errors='coerce').mean():.0f}")
    if "Beta K Decision" in df.columns:
        playable = df[~df["Beta K Decision"].astype(str).str.contains("PASS|NO LINE", na=False)]
        c3.metric("Playable Beta Leans", len(playable))
    show_cols = [c for c in [
        "Pitcher","Matchup","K Line","Current K PROJ","Beta K V5","Beta K Edge","Beta K Decision","Beta K Confidence","Decision Reason",
        "Original IP","Beta IP","Beta BF","IP Confidence","IP Volatility Score","IP Volatility Label","Shared Workload K Audit","Workload Confidence Adj",
        "K Conversion Score","K Conversion Label","K Env Blend %","K Env Details","Beta Flags","Version"
    ] if c in df.columns]
    st.dataframe(df[show_cols], use_container_width=True, hide_index=True)
    with st.expander("Full Beta K V5 Audit", expanded=False):
        st.dataframe(df, use_container_width=True, hide_index=True)





# ============================================================
# APP 70 K UPSIDE CALIBRATION LAYER — K MODEL ONLY
# Version: APP70_K_STABILITY_CALIBRATION_2026_07_08
#
# Purpose:
# - Keep Pitching Outs completely untouched.
# - Keep the original K model as the anchor.
# - Use last-season/current-season/recent logs as a small stabilizer.
# - Lower K Environment to a light confidence/projection nudge only.
# - Improve weak 4.5-5.5 line bucket with stricter borderline filtering.
# - Add stronger volatility caution for low-sample/openers/bulk roles.
# - Make confidence tiers more realistic without creating wild projection moves.
# ============================================================
APP70_K_STABILITY_VERSION = "APP70_K_STABILITY_CALIBRATION_2026_07_08"


def _a70_num(x, default=None):
    try:
        if x is None:
            return default
        if isinstance(x, str):
            s = x.strip().replace('%', '').replace(',', '')
            if s in ('', '—', '-', 'None', 'nan', 'NaN', 'NL', 'NO LINE'):
                return default
            x = s
        v = float(x)
        if pd.isna(v):
            return default
        return v
    except Exception:
        return default


def _a70_norm_name(x):
    try:
        s = unicodedata.normalize('NFKD', str(x or '')).encode('ascii', 'ignore').decode('ascii')
        s = re.sub(r"[^a-zA-Z0-9\s'\-]", '', s).lower()
        return re.sub(r'\s+', ' ', s).strip()
    except Exception:
        return str(x or '').lower().strip()


def _a70_line(row):
    for c in ['UD/Line', 'Line', 'line', 'K Line']:
        if c in row:
            v = _a70_num(row.get(c), None)
            if v is not None:
                return v
    return None


def _a70_base_proj(row):
    for c in ['K PROJ', 'Line-Aware Smart Final K Projection', 'Final K Projection', 'WRS Final K Projection', 'TPS Final K Projection', 'TPC True K Projection', 'Projection', 'Proj']:
        if c in row:
            v = _a70_num(row.get(c), None)
            if v is not None:
                return v
    return None


def _a70_load_pitch_logs():
    """Best available Pitch.csv / pitcher game-log loader. Read-only."""
    try:
        cached = st.session_state.get('_app70_pitch_logs_cache')
        if isinstance(cached, pd.DataFrame) and not cached.empty:
            return cached.copy()
    except Exception:
        pass

    candidates = []
    try:
        for key in ['pitcher_season_logs', 'pitcher_30_day_logs']:
            df = st.session_state.get(key)
            if isinstance(df, pd.DataFrame) and not df.empty:
                candidates.append(df.copy())
    except Exception:
        pass
    try:
        if '_tpc_load_embedded_pitch_logs' in globals():
            df = _tpc_load_embedded_pitch_logs()
            if isinstance(df, pd.DataFrame) and not df.empty:
                candidates.append(df.copy())
    except Exception:
        pass
    try:
        from pathlib import Path as _Path
        for fp in [
            _Path('learning_data') / 'Pitch.csv',
            _Path.cwd() / 'learning_data' / 'Pitch.csv',
            _Path(__file__).resolve().parent / 'learning_data' / 'Pitch.csv',
        ]:
            if fp.exists():
                df = pd.read_csv(fp)
                if isinstance(df, pd.DataFrame) and not df.empty:
                    candidates.append(df.copy())
    except Exception:
        pass

    if not candidates:
        return pd.DataFrame()
    try:
        df = pd.concat(candidates, ignore_index=True, sort=False)
        df = df.loc[:, ~df.columns.duplicated()].copy()
        for c in ['K', 'Ks', 'SO', 'Strikeouts', 'IP', 'BF', 'Pitch Count', 'Pitches', 'ER', 'BB', 'H']:
            if c in df.columns:
                df[c] = pd.to_numeric(df[c], errors='coerce')
        if 'Date' in df.columns:
            df['_app70_date'] = pd.to_datetime(df['Date'], errors='coerce')
        elif '_date' in df.columns:
            df['_app70_date'] = pd.to_datetime(df['_date'], errors='coerce')
        else:
            df['_app70_date'] = pd.NaT
        pcol = next((c for c in ['Pitcher', 'Player', 'Name', 'pitcher'] if c in df.columns), None)
        if pcol:
            df['_app70_name'] = df[pcol].map(_a70_norm_name)
        try:
            st.session_state['_app70_pitch_logs_cache'] = df.copy()
        except Exception:
            pass
        return df.copy()
    except Exception:
        return pd.DataFrame()


def _a70_pitcher_history_profile(pitcher):
    """Return history/recent K baseline for one pitcher. Uses only available logs."""
    out = {
        'sample': 0, 'hist_avg': None, 'current_avg': None, 'recent5': None,
        'recent3': None, 'avg_ip': None, 'avg_bf': None, 'baseline': None,
        'trust': 0.0, 'label': 'NO_HISTORY'
    }
    try:
        df = _a70_load_pitch_logs()
        if df is None or df.empty or '_app70_name' not in df.columns:
            return out
        name = _a70_norm_name(pitcher)
        d = df[df['_app70_name'] == name].copy()
        if d.empty:
            # Loose fallback: last token + first token match, avoids suffix/diacritic issues.
            toks = name.split()
            if len(toks) >= 2:
                first, last = toks[0], toks[-1]
                d = df[df['_app70_name'].astype(str).str.contains(first, na=False) & df['_app70_name'].astype(str).str.contains(last, na=False)].copy()
        if d.empty:
            return out
        kcol = next((c for c in ['K', 'Ks', 'SO', 'Strikeouts'] if c in d.columns), None)
        if not kcol:
            return out
        d[kcol] = pd.to_numeric(d[kcol], errors='coerce')
        d = d.dropna(subset=[kcol])
        if d.empty:
            return out
        if '_app70_date' in d.columns and d['_app70_date'].notna().any():
            d = d.sort_values('_app70_date', ascending=False)
            max_year = int(d['_app70_date'].dropna().dt.year.max())
            cur = d[d['_app70_date'].dt.year == max_year]
        else:
            cur = d
        vals = [float(x) for x in d[kcol].dropna().tolist()]
        cur_vals = [float(x) for x in cur[kcol].dropna().tolist()] if isinstance(cur, pd.DataFrame) and not cur.empty else vals
        out['sample'] = len(vals)
        out['hist_avg'] = float(np.mean(vals)) if vals else None
        out['current_avg'] = float(np.mean(cur_vals)) if cur_vals else out['hist_avg']
        out['recent5'] = float(np.mean(vals[:5])) if len(vals) >= 1 else None
        out['recent3'] = float(np.mean(vals[:3])) if len(vals) >= 1 else None
        ip_col = next((c for c in ['IP', 'Innings'] if c in d.columns), None)
        bf_col = next((c for c in ['BF', 'Batters Faced'] if c in d.columns), None)
        if ip_col:
            out['avg_ip'] = _a70_num(pd.to_numeric(d[ip_col], errors='coerce').dropna().mean(), None)
        if bf_col:
            out['avg_bf'] = _a70_num(pd.to_numeric(d[bf_col], errors='coerce').dropna().mean(), None)
        n = out['sample']
        # Dynamic weighting: veterans trust current+history; low-sample stays conservative.
        h = out['hist_avg'] if out['hist_avg'] is not None else 0.0
        c = out['current_avg'] if out['current_avg'] is not None else h
        r5 = out['recent5'] if out['recent5'] is not None else c
        if n >= 22:
            baseline = 0.40*c + 0.35*h + 0.25*r5
            trust = 1.00; label = 'HIGH_HISTORY'
        elif n >= 10:
            baseline = 0.42*c + 0.33*h + 0.25*r5
            trust = 0.75; label = 'MED_HISTORY'
        elif n >= 4:
            baseline = 0.35*c + 0.45*h + 0.20*r5
            trust = 0.50; label = 'LOW_HISTORY'
        else:
            baseline = 0.60*h + 0.40*r5
            trust = 0.30; label = 'TINY_HISTORY'
        out['baseline'] = round(float(baseline), 2)
        out['trust'] = trust
        out['label'] = label
        return out
    except Exception:
        return out


def _a70_env_nudge(row):
    """K environment becomes a tiny nudge, never a projection driver."""
    nudge = 0.0
    reasons = []
    try:
        # Matchup Intel already changed the core projection upstream.
        # Read it for audit only; never apply it a second time here.
        mi = _a70_num(row.get('Matchup Intel K Nudge'), None)
        if mi is not None and abs(mi) >= 0.01:
            reasons.append(f'MI audit {mi:+.2f} (already applied)')
        env_blend = _a70_num(row.get('K Env Blend %'), None)
        if env_blend is not None:
            if env_blend >= 27:
                nudge += 0.06; reasons.append('K env plus')
            elif env_blend <= 18:
                nudge -= 0.06; reasons.append('K env low')
        env_label = str(row.get('Opponent K Environment') or row.get('K Environment') or '').upper()
        if any(x in env_label for x in ['ELITE', 'HIGH', 'PLUS']):
            nudge += 0.05; reasons.append('opp K env +')
        elif any(x in env_label for x in ['LOW', 'CONTACT', 'SUPPRESS']):
            nudge -= 0.05; reasons.append('opp contact env')
    except Exception:
        pass
    return round(float(max(-0.20, min(0.20, nudge))), 2), '; '.join(reasons) or 'neutral'


def _a70_line_bucket(line):
    if line is None:
        return 'NO_LINE'
    if line < 3.5:
        return '<3.5'
    if line <= 4.5:
        return '3.5-4.5'
    if line <= 5.5:
        return '4.5-5.5'
    if line <= 6.5:
        return '5.5-6.5'
    if line <= 7.5:
        return '6.5-7.5'
    return '7.5+'


def _a70_bucket_nudge(row, base_proj, line):
    """Small data-driven bucket correction. Especially protects the weak 4.5-5.5 range."""
    if line is None or base_proj is None:
        return 0.0, 'no line/base'
    edge = base_proj - line
    bucket = _a70_line_bucket(line)
    nudge = 0.0
    reason = []
    if bucket == '4.5-5.5':
        # This has been the weakest calibrated bucket. Trim only marginal OVERs.
        if 0.20 <= edge <= 0.95:
            nudge -= 0.18; reason.append('4.5-5.5 marginal over trim')
        elif -0.95 <= edge <= -0.20:
            nudge += 0.08; reason.append('4.5-5.5 under caution')
    elif bucket == '7.5+':
        if edge > 0 and edge < 1.35:
            nudge -= 0.18; reason.append('7.5+ hard-line trim')
    elif bucket == '<3.5':
        if edge < 0:
            nudge += 0.08; reason.append('low-line under caution')
    return round(float(max(-0.25, min(0.18, nudge))), 2), '; '.join(reason) or 'neutral'


def _a70_volatility_penalty(row, line, proj):
    """Confidence/decision penalty first, projection haircut only on risky marginal overs."""
    penalty = 0.0
    flags = []
    text = ' '.join(str(row.get(c, '')) for c in ['Volatility', 'Volatility Label', 'Pitcher Experience', 'Experience', 'Role', 'role', 'Pitcher Role', 'Lineup Status', 'Decision Note', 'Tester Note', 'Open/Bulk Role Signal 2.1'])
    up = text.upper()
    if any(x in up for x in ['ROOKIE', 'UNKNOWN', 'LOW SAMPLE', 'TINY_HISTORY', 'DEBUT']):
        penalty += 6; flags.append('low sample')
    if any(x in up for x in ['OPENER', 'BULK', 'RELIEF', 'PITCH LIMIT', 'SHORT', 'HOOK']):
        penalty += 7; flags.append('role/leash')
    exp_bf = _a70_num(row.get('Exp BF') or row.get('Expected BF') or row.get('BF'), None)
    ip = _a70_num(row.get('IP Floor') or row.get('IP Projection') or row.get('IP'), None)
    if exp_bf is not None and exp_bf < 19:
        penalty += 5; flags.append('low BF')
    if ip is not None and ip < 4.0:
        penalty += 5; flags.append('low IP')
    # Projection haircut only if marginal over and risk exists.
    haircut = 0.0
    if line is not None and proj is not None and proj > line and (proj - line) < 1.0 and penalty >= 7:
        haircut = -0.15
    return round(float(haircut), 2), int(min(25, penalty)), ', '.join(flags) or 'none'


def _a70_confidence_and_decision(row, final_proj, line, vol_penalty=0):
    if final_proj is None:
        return 'NO_PROJECTION', None, None, 'no projection'
    if line is None:
        return '🚫 NO UD LINE', None, None, 'no line'
    edge = round(float(final_proj - line), 2)
    abs_edge = abs(edge)
    side = 'OVER' if edge >= 0 else 'UNDER'
    bucket = _a70_line_bucket(line)
    role_score = _a70_num(row.get('Role Score') or row.get('role_score'), 70) or 70
    ip = _a70_num(row.get('IP Floor') or row.get('IP Projection') or row.get('IP'), None)
    exp_bf = _a70_num(row.get('Exp BF') or row.get('Expected BF') or row.get('BF'), None)
    hist_label = str(row.get('App70 History Label') or '')

    # Base confidence from edge. Keep realistic: do not create fake 80%+ often.
    conf = 50.0 + min(18.0, abs_edge * 9.5)
    if exp_bf is not None:
        if exp_bf >= 23: conf += 3
        elif exp_bf < 19: conf -= 4
    if ip is not None:
        if ip >= 5.1: conf += 2
        elif ip < 4.0: conf -= 4
    if role_score < 55: conf -= 5
    elif role_score >= 72: conf += 2
    conf -= min(10, vol_penalty * 0.45)

    # Harder gate for weak buckets and very hard lines.
    if bucket == '4.5-5.5' and abs_edge < 0.95:
        conf -= 5
    if bucket == '7.5+' and side == 'OVER' and abs_edge < 1.65:
        conf -= 7
    if 'TINY' in hist_label or 'LOW' in hist_label:
        conf -= 2

    # Decision gates: projections remain; official status becomes more disciplined.
    reason = []
    if side == 'OVER':
        official_gap = 1.15 if bucket == '4.5-5.5' else 1.00
        lean_gap = 0.70 if bucket == '4.5-5.5' else 0.55
        if bucket == '7.5+':
            official_gap = 1.60; lean_gap = 1.00
        if abs_edge >= official_gap and conf >= 60 and vol_penalty < 16:
            dec = '🔥 OVER' if abs_edge >= official_gap + 0.55 and conf >= 64 else '✅ OVER'
        elif abs_edge >= lean_gap and conf >= 54:
            dec = '⚠️ OVER LEAN'
        else:
            dec = '🚫 PASS — OVER THIN/RISK'
            reason.append('over gate not met')
    else:
        # Conservative under gate: do not over-fade strikeout arms without a real gap.
        under_gap = 1.35 if bucket in ['4.5-5.5', '5.5-6.5'] else 1.15
        strong_gap = 2.10 if bucket in ['4.5-5.5', '5.5-6.5'] else 1.85
        high_ceiling_text = ' '.join(str(row.get(c, '')) for c in ['Pitcher K%', 'Putaway/Whiff', 'K Env Details', 'Decision Note']).upper()
        if abs_edge >= strong_gap and conf >= 61:
            dec = '🔥 UNDER'
        elif abs_edge >= under_gap and conf >= 56:
            dec = '⚠️ UNDER LEAN'
        else:
            dec = '🚫 PASS — UNDER THIN/RISK'
            reason.append('under gate not met')
    conf = round(float(max(35.0, min(72.0, conf))), 1)
    if not reason:
        reason.append(f'{bucket} edge {edge:+.2f}')
    return dec, edge, conf, '; '.join(reason)


def _a70_apply_k_stability_calibration(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    d = df.copy()
    finals, hist_bases, hist_labels, hist_ns = [], [], [], []
    hist_nudges, env_nudges, bucket_nudges, vol_haircuts = [], [], [], []
    vol_penalties, decisions, edges, confs, reasons = [], [], [], [], []

    for _, rr in d.iterrows():
        row = rr.to_dict()
        pitcher = row.get('Pitcher') or row.get('pitcher') or row.get('Player') or ''
        base = _a70_base_proj(row)
        line = _a70_line(row)
        hist = _a70_pitcher_history_profile(pitcher)
        hist_base = hist.get('baseline')
        hist_trust = _a70_num(hist.get('trust'), 0.0) or 0.0
        # History stabilizer: small nudge only, so original model remains the anchor.
        hist_nudge = 0.0
        if base is not None and hist_base is not None:
            raw = (hist_base - base) * (0.16 * hist_trust)
            cap = 0.42 if hist_trust >= 0.75 else 0.28 if hist_trust >= 0.50 else 0.18
            hist_nudge = max(-cap, min(cap, raw))
        env_nudge, env_reason = _a70_env_nudge(row)
        bucket_nudge, bucket_reason = _a70_bucket_nudge(row, base, line)
        v_haircut, v_penalty, v_reason = _a70_volatility_penalty(row, line, base)
        final = None
        if base is not None:
            total_adj = hist_nudge + env_nudge + bucket_nudge + v_haircut
            # Total calibration cap keeps K PROJ close to original successful model.
            total_adj = max(-0.55, min(0.45, total_adj))
            final = round(float(max(0.0, min(15.0, base + total_adj))), 2)
        dec, edge, conf, dec_reason = _a70_confidence_and_decision(row, final, line, v_penalty)
        finals.append(final if final is not None else '')
        hist_bases.append(hist_base if hist_base is not None else '')
        hist_labels.append(hist.get('label'))
        hist_ns.append(hist.get('sample', 0))
        hist_nudges.append(round(float(hist_nudge), 2))
        env_nudges.append(env_nudge)
        bucket_nudges.append(bucket_nudge)
        vol_haircuts.append(v_haircut)
        vol_penalties.append(v_penalty)
        decisions.append(dec)
        edges.append(edge if edge is not None else '')
        confs.append(conf if conf is not None else '')
        reasons.append(f"hist={hist.get('label')} n={hist.get('sample',0)} nudge {hist_nudge:+.2f}; env {env_nudge:+.2f} ({env_reason}); bucket {bucket_nudge:+.2f} ({bucket_reason}); vol {v_penalty} ({v_reason}); {dec_reason}")

    # Preserve original final columns for audit before syncing the displayed board.
    if 'K PROJ' in d.columns and 'Pre-App70 K PROJ' not in d.columns:
        d['Pre-App70 K PROJ'] = d['K PROJ']
    if 'Decision' in d.columns and 'Pre-App70 Decision' not in d.columns:
        d['Pre-App70 Decision'] = d['Decision']
    if 'Edge Gap' in d.columns and 'Pre-App70 Edge Gap' not in d.columns:
        d['Pre-App70 Edge Gap'] = d['Edge Gap']

    d['App70 History Baseline K'] = hist_bases
    d['App70 History Label'] = hist_labels
    d['App70 History Sample'] = hist_ns
    d['App70 History Nudge'] = hist_nudges
    d['App70 K Env Nudge'] = env_nudges
    d['App70 Bucket Nudge'] = bucket_nudges
    d['App70 Volatility Projection Haircut'] = vol_haircuts
    d['App70 Volatility Penalty'] = vol_penalties
    d['App70 Calibrated K PROJ'] = finals
    d['App70 Decision'] = decisions
    d['App70 Edge'] = edges
    d['App70 Confidence %'] = confs
    d['App70 Reason'] = reasons
    d['App70 Version'] = APP70_K_STABILITY_VERSION

    # Sync regular K Upside board and cards to the calibrated projection.
    try:
        d['K PROJ'] = d['App70 Calibrated K PROJ']
        for c in ['Matchup Intelligence Final K Projection', 'Line-Aware Smart Final K Projection', 'Official K PROJ', 'Final K Projection']:
            if c in d.columns:
                d[c] = d['App70 Calibrated K PROJ']
        if 'Decision' in d.columns:
            d['Decision'] = d['App70 Decision']
        if 'Main Engine Action' in d.columns:
            d['Main Engine Action'] = d['App70 Decision']
        if 'Line-Aware Smart Decision' in d.columns:
            d['Line-Aware Smart Decision'] = d['App70 Decision']
        for c in ['Edge Gap', 'Official K Edge', 'Final K Edge', 'Line-Aware Smart Edge']:
            if c in d.columns:
                d[c] = d['App70 Edge']
        if 'Confidence %' in d.columns:
            d['Confidence %'] = d['App70 Confidence %']
        elif 'Confidence' in d.columns:
            d['Confidence'] = d['App70 Confidence %']
    except Exception:
        pass
    return d


if 'build_kproj_table' in globals():
    _prev_app70_build_kproj_table = build_kproj_table
    def build_kproj_table(board):
        df = _prev_app70_build_kproj_table(board)
        try:
            return _a70_apply_k_stability_calibration(df)
        except Exception as _app70_e:
            try:
                st.warning(f'App70 K calibration skipped safely: {_app70_e}')
            except Exception:
                pass
            return df

# =========================
# APP 75 — CONSOLIDATED K MATCHUP / OPPORTUNITY / SANITY / CONFIDENCE
# =========================
# This layer deliberately consolidates overlapping signals already present in the
# engine. It does not replace the historical/current-season K core. Pitch arsenal,
# whiff interaction, lineup quality, and environment remain small refinements.
APP75_K_MODULE_VERSION = "APP75_K_CONSOLIDATED_MODULES_1.0"


def _a75_num(v, default=None):
    try:
        if v is None or v == "" or (isinstance(v, float) and np.isnan(v)):
            return default
        if isinstance(v, str):
            s = v.replace('%', '').replace('K', '').strip()
            if not s or s in {'—', '-', 'None', 'nan'}:
                return default
            return float(s)
        return float(v)
    except Exception:
        return default


def _a75_first(row, names, default=None):
    for name in names:
        if name in row:
            v = _a75_num(row.get(name), None)
            if v is not None:
                return v
    return default


def _a75_pct(v, default=None):
    x = _a75_num(v, default)
    if x is None:
        return default
    return x / 100.0 if x > 1 else x


def _a75_workload_module(row):
    """Better BF/IP + pitch-count efficiency module.

    Outputs a 0-100 score and a small projection nudge. It rewards realistic
    opportunity, not innings by themselves.
    """
    bf = _a75_first(row, ['Exp BF', 'Expected BF', 'Beta BF', 'BF'])
    ip = _a75_first(row, ['IP Projection', 'Projected IP', 'Beta IP', 'IP Floor', 'IP'])
    pitches = _a75_first(row, ['Projected Pitches', 'Pitch Count Projection', 'Expected Pitches'])
    ppb = _a75_first(row, ['Pitches Per Batter', 'PPB', 'pitches_per_batter'])
    role = _a75_first(row, ['Role Score', 'role_score'], 65) or 65

    parts = []
    if bf is not None:
        parts.append(max(20, min(90, 50 + (bf - 21.0) * 5.0)))
    if ip is not None:
        parts.append(max(20, min(90, 50 + (ip - 5.0) * 10.0)))
    if pitches is not None:
        parts.append(max(20, min(90, 50 + (pitches - 88.0) * 0.7)))
    if ppb is not None:
        # Lower pitches/BF allows more BF for the same leash, but extremes are noisy.
        parts.append(max(30, min(75, 55 + (3.9 - ppb) * 12.0)))
    parts.append(max(25, min(85, role)))
    score = float(np.mean(parts)) if parts else 50.0
    nudge = max(-0.12, min(0.12, (score - 50.0) / 50.0 * 0.12))
    note = f"workload {score:.0f}/100"
    if bf is not None: note += f", BF {bf:.1f}"
    if ip is not None: note += f", IP {ip:.2f}"
    return score, round(nudge, 3), note


def _a75_whiff_opportunity_module(row, proj):
    """Strikeout Opportunity Index + whiff interaction.

    Uses existing real inputs already loaded by the app. This avoids a second API
    call and prevents double counting. Projection effect is capped tightly.
    """
    bf = _a75_first(row, ['Exp BF', 'Expected BF', 'Beta BF', 'BF'], 21.0) or 21.0
    pitcher_k = _a75_pct(row.get('Pitcher K%'), None)
    opp_k = _a75_pct(row.get('Opp K%'), None)
    conversion = _a75_first(row, ['K Conversion Score', 'Strikeout Conversion Score'], 50) or 50
    context = _a75_first(row, ['K Context Score', 'K Context', 'Sabermetric K Score'], 50) or 50
    pitch_factor = _a75_first(row, ['Pitch Type Factor', 'pitch_type_factor'], 1.0) or 1.0

    # Normalize core opportunity. Missing data remains neutral.
    pk_score = 50 if pitcher_k is None else max(20, min(90, 50 + (pitcher_k - 0.23) * 190))
    ok_score = 50 if opp_k is None else max(20, min(90, 50 + (opp_k - 0.225) * 180))
    bf_score = max(20, min(90, 50 + (bf - 21.0) * 5.0))
    arsenal_score = max(35, min(65, 50 + (pitch_factor - 1.0) / 0.035 * 15))
    score = 0.31 * pk_score + 0.25 * ok_score + 0.24 * bf_score + 0.12 * conversion + 0.05 * context + 0.03 * arsenal_score
    score = max(20.0, min(90.0, score))

    # Small modifier only. Do not let this layer create a new model.
    nudge = max(-0.16, min(0.16, (score - 50.0) / 40.0 * 0.16))
    return score, round(nudge, 3), f"SOI {score:.0f}/100; arsenal {arsenal_score:.0f}/100"


def _a75_lineup_quality_module(row):
    opp_k = _a75_pct(row.get('Opp K%'), None)
    lineup_k = _a75_pct(row.get('Lineup K%'), None)
    status = str(row.get('Lineup') or row.get('Lineup Status') or '').upper()
    k = lineup_k if lineup_k is not None else opp_k
    score = 50.0 if k is None else max(25, min(80, 50 + (k - 0.225) * 180))
    if 'CONFIRMED' in status or 'LOCK' in status:
        score += 3
    elif 'FALLBACK' in status or 'PROJECT' in status or 'UNKNOWN' in status:
        score -= 4
    score = max(20.0, min(85.0, score))
    # Lineup quality mostly changes confidence; raw K nudge stays micro.
    nudge = max(-0.07, min(0.07, (score - 50.0) / 35.0 * 0.07))
    return score, round(nudge, 3), f"lineup quality {score:.0f}/100"


def _a75_sanity_checker(row, proj):
    """Final projection sanity checker using BF, IP, pitcher K skill, and history.

    Returns a capped projection and audit reason. It only trims projections that
    demand an implausible conversion rate for the expected workload.
    """
    if proj is None:
        return proj, 0.0, 'no projection', False
    bf = _a75_first(row, ['Exp BF', 'Expected BF', 'Beta BF', 'BF'])
    ip = _a75_first(row, ['IP Projection', 'Projected IP', 'Beta IP', 'IP Floor', 'IP'])
    pk = _a75_pct(row.get('Pitcher K%'), None)
    hist = _a75_first(row, ['App70 History Baseline K', 'Historical Baseline K'])
    cap = None
    reasons = []

    if bf is not None:
        skill = pk if pk is not None else max(0.12, min(0.38, proj / max(bf, 1)))
        # Allow upside above expected skill, but not unlimited conversion.
        cap = bf * min(0.43, skill * 1.22 + 0.018) + 0.35
        if ip is not None and ip < 4.0:
            cap -= 0.20
            reasons.append('short-IP ceiling')
    if hist is not None:
        hist_cap = hist + 1.75
        cap = hist_cap if cap is None else min(cap, hist_cap)

    if cap is not None and proj > cap:
        new_proj = max(0.0, proj - min(0.45, proj - cap))
        return round(new_proj, 2), round(new_proj - proj, 2), f"sanity trim: cap {cap:.2f}" + (f"; {', '.join(reasons)}" if reasons else ''), True
    return round(proj, 2), 0.0, 'sanity pass', False


def _a75_dynamic_confidence(row, proj, line, workload_score, soi_score, lineup_score, sanity_flag):
    old = _a75_first(row, ['App70 Confidence %', 'Confidence %', 'Confidence'], 50) or 50
    if line is None or proj is None:
        return round(old, 1), False, 'no line/projection'
    edge = abs(proj - line)
    vol = _a75_first(row, ['App70 Volatility Penalty', 'Volatility Tax', 'Volatility'], 0) or 0
    data_score = _a75_first(row, ['Data Score', 'data_score'], 75) or 75
    lineup_status = str(row.get('Lineup') or row.get('Lineup Status') or '').upper()

    conf = 0.55 * old + 0.14 * workload_score + 0.13 * soi_score + 0.08 * lineup_score + 0.10 * min(75, 48 + edge * 10)
    conf -= min(9, vol * 0.35)
    if data_score < 70: conf -= 5
    if sanity_flag: conf -= 7
    if 'FALLBACK' in lineup_status or 'UNKNOWN' in lineup_status: conf -= 3
    conf = max(35.0, min(74.0, conf))
    danger = conf < 54 or sanity_flag or vol >= 15 or data_score < 65
    reasons = []
    if conf < 54: reasons.append('low calibrated confidence')
    if sanity_flag: reasons.append('projection sanity trim')
    if vol >= 15: reasons.append('high volatility')
    if data_score < 65: reasons.append('thin data')
    return round(conf, 1), danger, ', '.join(reasons) or 'calibration aligned'


def _a75_apply_consolidated_modules(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    d = df.copy()
    out_proj, workload_scores, workload_notes = [], [], []
    soi_scores, soi_notes, arsenal_scores = [], [], []
    lineup_scores, lineup_notes, sanity_shifts, sanity_notes = [], [], [], []
    confs, danger_tags, danger_notes, total_nudges = [], [], [], []

    for _, rr in d.iterrows():
        row = rr.to_dict()
        base = _a75_first(row, ['App70 Calibrated K PROJ', 'K PROJ', 'Final K Projection'])
        line = _a75_first(row, ['UD/Line', 'UD Line', 'Line', 'line'])
        w_score, w_nudge, w_note = _a75_workload_module(row)
        soi_score, soi_nudge, soi_note = _a75_whiff_opportunity_module(row, base)
        lu_score, lu_nudge, lu_note = _a75_lineup_quality_module(row)

        # Aggregate refinements with a hard cap. Existing K core remains the anchor.
        nudge = max(-0.28, min(0.28, 0.45 * w_nudge + 0.40 * soi_nudge + 0.15 * lu_nudge))
        p1 = None if base is None else round(max(0.0, min(15.0, base + nudge)), 2)
        p2, sanity_shift, sanity_note, sanity_flag = _a75_sanity_checker(row, p1)
        conf, danger, danger_reason = _a75_dynamic_confidence(row, p2, line, w_score, soi_score, lu_score, sanity_flag)

        pitch_factor = _a75_first(row, ['Pitch Type Factor', 'pitch_type_factor'], 1.0) or 1.0
        arsenal_score = max(35, min(65, 50 + (pitch_factor - 1.0) / 0.035 * 15))

        out_proj.append(p2 if p2 is not None else '')
        workload_scores.append(round(w_score, 1)); workload_notes.append(w_note)
        soi_scores.append(round(soi_score, 1)); soi_notes.append(soi_note)
        arsenal_scores.append(round(arsenal_score, 1))
        lineup_scores.append(round(lu_score, 1)); lineup_notes.append(lu_note)
        sanity_shifts.append(sanity_shift); sanity_notes.append(sanity_note)
        confs.append(conf); total_nudges.append(round(nudge + sanity_shift, 2))
        danger_tags.append('‼️ DANGER' if danger else '')
        danger_notes.append(('Play at your risk — ' + danger_reason) if danger else 'Confidence calibration aligned')

    if 'K PROJ' in d.columns and 'Pre-App75 K PROJ' not in d.columns:
        d['Pre-App75 K PROJ'] = d['K PROJ']
    d['Workload Engine Score'] = workload_scores
    d['Workload Engine Note'] = workload_notes
    d['Strikeout Opportunity Index'] = soi_scores
    d['Whiff Interaction Note'] = soi_notes
    d['Pitch Arsenal Matchup Score'] = arsenal_scores
    d['Lineup Quality Score'] = lineup_scores
    d['Lineup Quality Note'] = lineup_notes
    d['Projection Sanity Shift'] = sanity_shifts
    d['Projection Sanity Note'] = sanity_notes
    d['App75 Total K Adjustment'] = total_nudges
    d['App75 Final K PROJ'] = out_proj
    d['App75 Confidence %'] = confs
    d['App75 Danger Tag'] = danger_tags
    d['App75 Danger Note'] = danger_notes
    d['App75 Version'] = APP75_K_MODULE_VERSION

    # Sync the regular K Upside board only. Do not touch Pitching Outs tables.
    d['K PROJ'] = d['App75 Final K PROJ']
    for c in ['Matchup Intelligence Final K Projection', 'Line-Aware Smart Final K Projection', 'Official K PROJ', 'Final K Projection']:
        if c in d.columns:
            d[c] = d['App75 Final K PROJ']
    if 'Confidence %' in d.columns:
        d['Confidence %'] = d['App75 Confidence %']
    elif 'Confidence' in d.columns:
        d['Confidence'] = d['App75 Confidence %']

    # Keep the model side, while surfacing risk as requested.
    if 'Decision' in d.columns:
        for idx in d.index:
            tag = d.at[idx, 'App75 Danger Tag']
            if tag and tag not in str(d.at[idx, 'Decision']):
                d.at[idx, 'Decision'] = f"{d.at[idx, 'Decision']} {tag}"
    return d


if 'build_kproj_table' in globals():
    _prev_app75_build_kproj_table = build_kproj_table
    def build_kproj_table(board):
        df = _prev_app75_build_kproj_table(board)
        try:
            return _a75_apply_consolidated_modules(df)
        except Exception as _app75_e:
            try:
                st.warning(f'App75 consolidated K modules skipped safely: {_app75_e}')
            except Exception:
                pass
            return df


# ============================================================
# APP 78 / v12.0 — FINAL K PIPELINE CONSOLIDATION
# ============================================================
# Goals:
# - Apply adaptive opponent recency exactly once (already inside Pre-App70 K PROJ).
# - Combine all later secondary adjustments into one capped calibration budget.
# - Use one unified risk score, one confidence engine, and one final decision gate.
# - Keep OVER/UNDER visible; use ‼️ DANGER instead of repeated PASS gates.
# - Leave the core K projection, BF/IP, Monte Carlo, learning, and Pitching Outs untouched.
APP78_V12_VERSION = "APP78_V12_FINAL_PIPELINE_CONSOLIDATION_2026_07_11"
APP78_SECONDARY_UP_CAP = 0.45
APP78_SECONDARY_DOWN_CAP = -0.55


def _a78_num(v, default=None):
    try:
        if v is None or v == "" or (isinstance(v, float) and np.isnan(v)):
            return default
        if isinstance(v, str):
            s = v.replace('%', '').replace('K', '').replace(',', '').strip()
            if not s or s in {'—', '-', 'None', 'nan', 'NL', 'NO LINE'}:
                return default
            return float(s)
        return float(v)
    except Exception:
        return default


def _a78_first(row, names, default=None):
    for name in names:
        if name in row:
            v = _a78_num(row.get(name), None)
            if v is not None:
                return v
    return default


def _a78_line(row):
    return _a78_first(row, ['UD/Line', 'UD Line', 'Line', 'line', 'K Line'], None)


def _a78_core_anchor(row):
    """Core anchor after adaptive recency, but before App70/App75 secondary layers."""
    return _a78_first(row, [
        'Pre-App70 K PROJ',
        'Matchup Intelligence Final K Projection',
        'Line-Aware Smart Final K Projection',
        'K PROJ',
        'Final K Projection',
    ], None)


def _a78_pct(v, default=None):
    x = _a78_num(v, default)
    if x is None:
        return default
    return x / 100.0 if abs(x) > 1.0 else x


def _a78_unified_risk(row, workload_score, soi_score, lineup_score, sanity_flag=False):
    """Single 0-100 risk score. Each underlying concern is counted once."""
    role_risk = 0.0
    workload_risk = 0.0
    volatility_risk = 0.0
    data_risk = 0.0
    lineup_risk = 0.0
    injury_risk = 0.0
    reasons = []

    text = ' '.join(str(row.get(c, '')) for c in [
        'Role', 'role', 'Pitcher Role', 'Role Label', 'Starter Status',
        'Volatility Label', 'Decision Note', 'Tester Note',
        'Open/Bulk Role Signal 2.1', 'Injury Status', 'Risk Notes'
    ]).upper()

    if any(x in text for x in ['OPENER', 'BULK', 'RELIEF', 'SPOT START']):
        role_risk = 24; reasons.append('unstable role')
    elif any(x in text for x in ['ROOKIE', 'DEBUT', 'LOW SAMPLE', 'TINY_HISTORY', 'UNKNOWN']):
        role_risk = 14; reasons.append('limited role sample')

    if any(x in text for x in ['PITCH LIMIT', 'LIMITED', 'SHORT LEASH', 'HOOK', 'RETURN FROM IL']):
        workload_risk = max(workload_risk, 22); reasons.append('leash/pitch-limit risk')

    bf = _a78_first(row, ['Exp BF', 'Expected BF', 'Beta BF', 'BF'], None)
    ip = _a78_first(row, ['IP Projection', 'Projected IP', 'IP Floor', 'Beta IP', 'IP'], None)
    if bf is not None:
        if bf < 17: workload_risk = max(workload_risk, 26); reasons.append('very low BF')
        elif bf < 20: workload_risk = max(workload_risk, 16); reasons.append('low BF')
    if ip is not None:
        if ip < 3.0: workload_risk = max(workload_risk, 28); reasons.append('very low IP')
        elif ip < 4.0: workload_risk = max(workload_risk, 17); reasons.append('low IP')

    raw_vol = _a78_first(row, ['Volatility Score', 'Volatility Tax', 'Volatility', 'App70 Volatility Penalty'], 0) or 0
    if raw_vol <= 10:
        volatility_risk = min(22, raw_vol * 2.0)
    else:
        volatility_risk = min(25, raw_vol)
    if volatility_risk >= 12:
        reasons.append('high volatility')

    data_score = _a78_first(row, ['Data Score', 'data_score', 'Official Data Score'], 78) or 78
    data_risk = max(0, min(22, (75 - data_score) * 0.8))
    if data_risk >= 8:
        reasons.append('thin data')

    if lineup_score is not None:
        lineup_risk = max(0, min(15, (52 - lineup_score) * 0.45))
    lineup_status = str(row.get('Lineup') or row.get('Lineup Status') or '').upper()
    if any(x in lineup_status for x in ['FALLBACK', 'UNKNOWN', 'PROJECTED']):
        lineup_risk = max(lineup_risk, 8)
        reasons.append('lineup not confirmed')

    if any(x in text for x in ['INJURY', 'IL RETURN', 'RETURNING', 'REHAB']):
        injury_risk = 12; reasons.append('injury/return uncertainty')

    # Workload/opportunity module outputs can reduce—not duplicate—risk.
    support_credit = 0.0
    if workload_score is not None:
        support_credit += max(-5, min(8, (workload_score - 50) * 0.16))
    if soi_score is not None:
        support_credit += max(-4, min(6, (soi_score - 50) * 0.12))

    total = role_risk + workload_risk + volatility_risk + data_risk + lineup_risk + injury_risk
    total -= max(0, support_credit)
    if sanity_flag:
        total += 12
        reasons.append('sanity ceiling conflict')
    total = round(max(0.0, min(100.0, total)), 1)
    label = 'LOW' if total < 25 else 'MEDIUM' if total < 50 else 'HIGH' if total < 72 else 'EXTREME'
    return total, label, '; '.join(dict.fromkeys(reasons)) or 'no major risk conflict'


def _a78_secondary_adjustment(row, core_proj):
    """One budget for every non-core projection adjustment after adaptive recency."""
    parts = []

    # App70 historical stabilizer is retained as a small evidence-backed input.
    hist = _a78_num(row.get('App70 History Nudge'), 0.0) or 0.0
    parts.append(('history', hist))

    # Fixed line-bucket penalties are converted to a small calibration input.
    # Most of their effect now belongs in confidence/risk, not raw projection.
    bucket = _a78_num(row.get('App70 Bucket Nudge'), 0.0) or 0.0
    parts.append(('line bucket', bucket * 0.35))

    # Volatility no longer changes projection here; it feeds unified risk only.

    # Recompute the App75 micro-modules from the core anchor, once.
    try:
        w_score, w_nudge, w_note = _a75_workload_module(row)
    except Exception:
        w_score, w_nudge, w_note = 50.0, 0.0, 'workload unavailable'
    try:
        soi_score, soi_nudge, soi_note = _a75_whiff_opportunity_module(row, core_proj)
    except Exception:
        soi_score, soi_nudge, soi_note = 50.0, 0.0, 'opportunity unavailable'
    try:
        lu_score, lu_nudge, lu_note = _a75_lineup_quality_module(row)
    except Exception:
        lu_score, lu_nudge, lu_note = 50.0, 0.0, 'lineup unavailable'

    parts.append(('workload', 0.45 * (_a78_num(w_nudge, 0.0) or 0.0)))
    parts.append(('opportunity/whiff', 0.40 * (_a78_num(soi_nudge, 0.0) or 0.0)))
    parts.append(('lineup', 0.15 * (_a78_num(lu_nudge, 0.0) or 0.0)))

    raw = sum(v for _, v in parts)
    capped = max(APP78_SECONDARY_DOWN_CAP, min(APP78_SECONDARY_UP_CAP, raw))
    note = '; '.join(f'{k} {v:+.2f}' for k, v in parts if abs(v) >= 0.005) or 'secondary calibration neutral'
    if abs(raw - capped) >= 0.005:
        note += f'; budget cap {capped:+.2f}'
    return round(capped, 3), note, w_score, w_note, soi_score, soi_note, lu_score, lu_note


def _a78_final_confidence(row, projection, line, risk_score, workload_score, soi_score, lineup_score, sanity_flag):
    if projection is None or line is None:
        return None, 'no line/projection'
    edge = abs(projection - line)
    sim_prob = _a78_first(row, [
        'Sim Pick %', 'Simulation Hit Rate %', 'Hit Rate %', 'Fair Probability %',
        'App70 Confidence %', 'Confidence %', 'Confidence'
    ], None)
    if sim_prob is not None and sim_prob <= 1:
        sim_prob *= 100
    if sim_prob is None:
        sim_prob = 50 + min(16, edge * 8)

    data_score = _a78_first(row, ['Data Score', 'data_score', 'Official Data Score'], 78) or 78
    edge_score = min(76, 50 + edge * 10)
    support = 0.24 * workload_score + 0.24 * soi_score + 0.12 * lineup_score + 0.20 * edge_score + 0.20 * sim_prob
    support -= risk_score * 0.22
    if data_score < 70:
        support -= (70 - data_score) * 0.35
    if sanity_flag:
        support -= 4
    conf = round(max(35.0, min(76.0, support)), 1)
    return conf, f'edge {edge:.2f}; risk {risk_score:.1f}; sim/base {sim_prob:.1f}'


def _a78_final_decision(projection, line, confidence, risk_score, data_ok=True):
    if projection is None:
        return 'NO PROJECTION', '', None
    if line is None:
        return '🚫 NO UD LINE', '', None
    if not data_ok:
        return '🚫 PASS — DATA UNUSABLE', '', round(projection - line, 2)

    edge = round(projection - line, 2)
    side = 'OVER' if edge >= 0 else 'UNDER'
    abs_edge = abs(edge)
    danger = risk_score >= 45 or confidence < 55 or abs_edge < 0.55

    if confidence >= 64 and abs_edge >= 1.25 and risk_score < 45:
        prefix = '🔥'
    elif confidence >= 57 and abs_edge >= 0.70:
        prefix = '⚠️'
    else:
        prefix = '⚠️'
        danger = True

    decision = f'{prefix} {side}'
    tag = '‼️ DANGER' if danger else ''
    return decision, tag, edge


def _a78_apply_final_pipeline(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    d = df.copy()

    final_proj = []
    total_adj = []
    adjustment_notes = []
    sanity_shifts = []
    sanity_notes = []
    risk_scores = []
    risk_labels = []
    risk_notes = []
    confidences = []
    confidence_notes = []
    decisions = []
    danger_tags = []
    final_edges = []
    workload_scores = []
    workload_notes = []
    soi_scores = []
    soi_notes = []
    lineup_scores = []
    lineup_notes = []

    for _, rr in d.iterrows():
        row = rr.to_dict()
        core = _a78_core_anchor(row)
        line = _a78_line(row)

        adj, adj_note, w_score, w_note, soi_score, soi_note, lu_score, lu_note = _a78_secondary_adjustment(row, core)
        p1 = None if core is None else round(max(0.0, min(15.0, core + adj)), 2)
        try:
            p2, sanity_shift, sanity_note, sanity_flag = _a75_sanity_checker(row, p1)
        except Exception:
            p2, sanity_shift, sanity_note, sanity_flag = p1, 0.0, 'sanity unavailable', False

        risk, risk_label, risk_note = _a78_unified_risk(row, w_score, soi_score, lu_score, sanity_flag)
        conf, conf_note = _a78_final_confidence(row, p2, line, risk, w_score, soi_score, lu_score, sanity_flag)
        data_score = _a78_first(row, ['Data Score', 'data_score', 'Official Data Score'], 78) or 78
        data_ok = core is not None and data_score >= 35
        dec, danger, edge = _a78_final_decision(p2, line, conf or 0, risk, data_ok=data_ok)

        final_proj.append('' if p2 is None else round(p2, 2))
        total_adj.append('' if core is None or p2 is None else round(p2 - core, 2))
        adjustment_notes.append(adj_note)
        sanity_shifts.append(round(_a78_num(sanity_shift, 0.0) or 0.0, 2))
        sanity_notes.append(sanity_note)
        risk_scores.append(risk)
        risk_labels.append(risk_label)
        risk_notes.append(risk_note)
        confidences.append('' if conf is None else conf)
        confidence_notes.append(conf_note)
        decisions.append(dec)
        danger_tags.append(danger)
        final_edges.append('' if edge is None else edge)
        workload_scores.append(round(w_score, 1)); workload_notes.append(w_note)
        soi_scores.append(round(soi_score, 1)); soi_notes.append(soi_note)
        lineup_scores.append(round(lu_score, 1)); lineup_notes.append(lu_note)

    if 'K PROJ' in d.columns and 'Pre-App78 K PROJ' not in d.columns:
        d['Pre-App78 K PROJ'] = d['K PROJ']
    if 'Decision' in d.columns and 'Pre-App78 Decision' not in d.columns:
        d['Pre-App78 Decision'] = d['Decision']
    if 'Confidence %' in d.columns and 'Pre-App78 Confidence %' not in d.columns:
        d['Pre-App78 Confidence %'] = d['Confidence %']

    d['App78 Core Anchor K PROJ'] = [
        '' if _a78_core_anchor(r.to_dict()) is None else round(_a78_core_anchor(r.to_dict()), 2)
        for _, r in d.iterrows()
    ]
    d['App78 Secondary Adjustment'] = total_adj
    d['App78 Adjustment Note'] = adjustment_notes
    d['App78 Sanity Shift'] = sanity_shifts
    d['App78 Sanity Note'] = sanity_notes
    d['Unified Risk Score'] = risk_scores
    d['Unified Risk Label'] = risk_labels
    d['Unified Risk Note'] = risk_notes
    d['Final Confidence %'] = confidences
    d['Final Confidence Note'] = confidence_notes
    d['Final Decision'] = decisions
    d['Final Danger Tag'] = danger_tags
    d['Final K Edge'] = final_edges
    d['Final Workload Score'] = workload_scores
    d['Final Workload Note'] = workload_notes
    d['Final Strikeout Opportunity Index'] = soi_scores
    d['Final Opportunity Note'] = soi_notes
    d['Final Lineup Quality Score'] = lineup_scores
    d['Final Lineup Quality Note'] = lineup_notes
    d['App78 Final K PROJ'] = final_proj
    d['App78 Version'] = APP78_V12_VERSION

    # Final synchronization. Nothing after this wrapper may alter K projection/decision/confidence.
    d['K PROJ'] = d['App78 Final K PROJ']
    for c in ['Matchup Intelligence Final K Projection', 'Line-Aware Smart Final K Projection', 'Official K PROJ', 'Final K Projection', 'App70 Calibrated K PROJ', 'App75 Final K PROJ']:
        if c in d.columns:
            d[c] = d['App78 Final K PROJ']
    for c in ['Edge Gap', 'Official K Edge', 'Line-Aware Smart Edge', 'App70 Edge']:
        if c in d.columns:
            d[c] = d['Final K Edge']
    for c in ['Decision', 'Main Engine Action', 'Line-Aware Smart Decision', 'App70 Decision']:
        if c in d.columns:
            d[c] = d['Final Decision']
    if 'Confidence %' in d.columns:
        d['Confidence %'] = d['Final Confidence %']
    if 'Confidence' in d.columns:
        d['Confidence'] = d['Final Confidence %']

    # Preserve the side while surfacing risk clearly.
    if 'Decision' in d.columns:
        for idx in d.index:
            tag = str(d.at[idx, 'Final Danger Tag'] or '')
            if tag and tag not in str(d.at[idx, 'Decision']):
                d.at[idx, 'Decision'] = f"{d.at[idx, 'Decision']} {tag}"
    return d


if 'build_kproj_table' in globals():
    _prev_app78_build_kproj_table = build_kproj_table
    def build_kproj_table(board):
        df = _prev_app78_build_kproj_table(board)
        try:
            return _a78_apply_final_pipeline(df)
        except Exception as _app78_e:
            try:
                st.warning(f'v12 final K pipeline cleanup skipped safely: {_app78_e}')
            except Exception:
                pass
            return df
APP82_ACTIVE_PIPELINE_VERSION = "APP82_FIXED_ACTIVE_v2"

# =============================================================================
# APP82 — PROJECTION REALITY ANCHOR + WORKLOAD/CEILING VALIDATION
# Added after App78 cleanup. This layer is intentionally conservative:
# - It does NOT globally raise/lower projections.
# - It repairs only strong contradictions between final K projection,
#   sustainable K skill, expected BF/workload, and simulation ceiling.
# - It keeps side visible and uses DANGER/TRACK when evidence conflicts.
# =============================================================================

import math as _app82_math
import numpy as _app82_np
import pandas as _app82_pd

def _app82_num(v, default=_app82_np.nan):
    try:
        x = float(v)
        return x if _app82_np.isfinite(x) else default
    except Exception:
        return default

def _app82_first_num(row, names, default=_app82_np.nan):
    for n in names:
        if n in row.index:
            x = _app82_num(row.get(n), _app82_np.nan)
            if _app82_np.isfinite(x):
                return x
    return default

def _app82_pct(x):
    x = _app82_num(x, _app82_np.nan)
    if not _app82_np.isfinite(x):
        return _app82_np.nan
    return x / 100.0 if x > 1.0 else x

def _app82_role(row):
    blob = " ".join(str(row.get(c, "")) for c in [
        "Role", "Pitcher Role", "Starter Status", "Probable Starter",
        "Role Stability", "Role/Leash", "Beta Flags", "K Flags"
    ]).lower()
    if any(k in blob for k in ["reliever", "bullpen", "opener"]):
        return "RELIEF_OR_OPENER"
    if any(k in blob for k in ["starter", "probable", "confirmed"]):
        return "STARTER"
    # Market/workload evidence fallback.
    ip = _app82_first_num(row, ["IP", "IP PROJ", "Projected IP", "Beta IP", "APP78 Core Anchor IP", "Projected Innings"])
    bf = _app82_first_num(row, ["Exp BF", "BF", "Projected BF", "Expected BF", "BF PROJ", "BF Projection", "Projected Batters Faced", "Expected Batters Faced"])
    if (_app82_np.isfinite(ip) and ip >= 3.0) or (_app82_np.isfinite(bf) and bf >= 14):
        return "STARTER_LIKELY"
    return "UNKNOWN"

def _app82_sustainable_k_rate(row):
    vals, weights = [], []
    candidates = [
        (["Pitcher K%", "K%", "Season K%", "Pitcher K Rate", "Pitcher K Rate %", "Season K Rate", "K Rate", "K Rate %"], 0.40),
        (["K Env Blend %", "K Environment Blend %", "K Env Blend", "K Environment %"], 0.15),
        (["T12 CSW%", "CSW%", "CSW %", "CSW", "CSW Rate", "CSW Rate %"], 0.15),
        (["T12 SwStr%", "SwStr%", "SwStr %", "SwStr", "SwStr Rate", "SwStr Rate %"], 0.10),
        (["Recent K%", "L5 K%", "L10 K%"], 0.10),
        (["Opponent K%", "Opp K%", "Recency Team K Blend"], 0.10),
    ]
    for names, w in candidates:
        x = _app82_first_num(row, names)
        x = _app82_pct(x)
        if _app82_np.isfinite(x):
            # CSW and SwStr are not direct K rates; map gently toward K-rate space.
            joined = " ".join(names)
            if "CSW" in joined:
                x = max(0.10, min(0.40, (x - 0.20) * 0.75 + 0.20))
            elif "SwStr" in joined:
                x = max(0.10, min(0.40, x * 1.55))
            vals.append(x); weights.append(w)
    if not vals:
        # Fallback to K/9 translated to approximate K/BF when the export schema
        # does not expose a direct K-rate column under the expected aliases.
        k9 = _app82_first_num(row, ["K/9", "K9", "Pitcher K/9", "Season K/9", "K Per 9"])
        if _app82_np.isfinite(k9):
            return max(0.08, min(0.40, k9 / 38.0))
        return _app82_np.nan
    return sum(v*w for v,w in zip(vals,weights)) / sum(weights)

def _app82_apply(df):
    if df is None or not isinstance(df, _app82_pd.DataFrame) or df.empty:
        return df
    out = df.copy()

    proj_col = next((c for c in [
        "APP78 Final K Projection", "Matchup Intelligence Final K Projection",
        "K PROJ", "Projection", "Beta Projection"
    ] if c in out.columns), None)
    line_col = next((c for c in ["UD Line", "Line", "K Line", "stat_value"] if c in out.columns), None)
    if proj_col is None:
        return out

    anchors, adjustments, reasons, roles, contradictions = [], [], [], [], []
    final_proj, final_side, danger, tiers = [], [], [], []

    for _, row in out.iterrows():
        p = _app82_num(row.get(proj_col))
        line = _app82_num(row.get(line_col)) if line_col else _app82_np.nan
        role = _app82_role(row)
        ip = _app82_first_num(row, [
            "APP78 Core Anchor IP", "IP PROJ", "Projected IP", "Beta IP", "IP"
        ])
        bf = _app82_first_num(row, ["Exp BF", "BF", "Projected BF", "Expected BF", "BF PROJ", "BF Projection", "Projected Batters Faced", "Expected Batters Faced"])
        if not _app82_np.isfinite(bf) and _app82_np.isfinite(ip):
            bf = max(3.0, ip * 4.25)

        kr = _app82_sustainable_k_rate(row)
        sustainable = bf * kr if (_app82_np.isfinite(bf) and _app82_np.isfinite(kr)) else _app82_np.nan

        # Live-schema BF-to-K projections already produced upstream by the app.
        # Blend them with the sustainable BF*K-rate anchor rather than ignoring them.
        bf_k_21 = _app82_first_num(row, ["BF-K Expected K 2.1"])
        bf_k_22 = _app82_first_num(row, ["BF-to-K Conversion Projection 2.2"])
        bf_anchors = [x for x in [bf_k_21, bf_k_22] if _app82_np.isfinite(x)]
        if bf_anchors:
            bf_k_anchor = sum(bf_anchors) / len(bf_anchors)
            if _app82_np.isfinite(sustainable):
                sustainable = 0.60 * sustainable + 0.40 * bf_k_anchor
            else:
                sustainable = bf_k_anchor

        anchor_inputs_missing = not _app82_np.isfinite(sustainable)

        p10 = _app82_first_num(row, ["p10", "P10", "Sim P10", "K P10", "K Sim P10", "Pre Calibration P10", "pre_calibration_p10"])
        p90 = _app82_first_num(row, ["p90", "P90", "Sim P90", "K P90", "K Sim P90", "Pre Calibration P90", "pre_calibration_p90"])
        width = (p90 - p10) if (_app82_np.isfinite(p90) and _app82_np.isfinite(p10)) else _app82_np.nan

        adj = 0.0
        why = []

        # Reality anchor: only repair large contradictions; never replace the model.
        if _app82_np.isfinite(sustainable) and _app82_np.isfinite(p):
            gap = sustainable - p
            if gap >= 1.50:
                adj += min(0.45, gap * 0.22)
                why.append("LOW_K_CONTRADICTION")
            elif gap <= -1.50:
                adj -= min(0.40, abs(gap) * 0.20)
                why.append("HIGH_K_CONTRADICTION")

        # Starter workload contradiction. Do not blindly inflate IP; flag and add only
        # a tiny K repair when a starter-like role has an implausibly low workload.
        workload_conflict = False
        if role in ("STARTER", "STARTER_LIKELY") and _app82_np.isfinite(ip) and ip < 3.75:
            workload_conflict = True
            why.append("STARTER_WORKLOAD_CONFLICT")
            if _app82_np.isfinite(kr):
                # modest fallback toward 4.25 IP, capped tightly
                fallback_bf = 4.25 * 4.25
                fallback_k = fallback_bf * kr
                if _app82_np.isfinite(p) and fallback_k > p:
                    adj += min(0.25, (fallback_k - p) * 0.15)

        # One combined reality-anchor budget.
        adj = max(-0.45, min(0.55, adj))
        fp = p + adj if _app82_np.isfinite(p) else p

        side = ""
        if _app82_np.isfinite(line) and _app82_np.isfinite(fp):
            side = "OVER" if fp > line else "UNDER"
        edge = abs(fp - line) if (_app82_np.isfinite(line) and _app82_np.isfinite(fp)) else _app82_np.nan

        flags = []
        if anchor_inputs_missing:
            flags.append("ANCHOR_INPUTS_MISSING")
        # Simulation ceiling/floor conflict affects selection, not projection.
        if side == "UNDER" and _app82_np.isfinite(p90) and _app82_np.isfinite(line) and p90 >= line + 1.5:
            flags.append("HIGH_CEILING_UNDER")
        if side == "OVER" and _app82_np.isfinite(p10) and _app82_np.isfinite(line) and p10 <= line - 1.5:
            flags.append("LOW_FLOOR_OVER")
        if _app82_np.isfinite(width) and width >= 5.0:
            flags.append("WIDE_SIM_RANGE")
        if workload_conflict:
            flags.append("WORKLOAD_ROLE_CONFLICT")
        if why and any(x in why for x in ["LOW_K_CONTRADICTION", "HIGH_K_CONTRADICTION"]):
            flags.append("BF_K_CONTRADICTION")

        is_danger = bool(flags)
        # Selection tiers: projection remains visible; thin/conflicted plays are not official.
        tier = "TRACK ONLY"
        if _app82_np.isfinite(edge):
            if edge >= 1.0 and not is_danger:
                tier = "OFFICIAL"
            elif edge >= 0.50 and not is_danger:
                tier = "PLAYABLE"
            elif edge >= 1.0 and is_danger:
                tier = "PLAYABLE ‼️ DANGER"
            else:
                tier = "TRACK ONLY ‼️ DANGER" if is_danger else "TRACK ONLY"

        anchors.append(sustainable)
        adjustments.append(adj)
        reasons.append(",".join(why) if why else "NO_REALITY_REPAIR")
        roles.append(role)
        contradictions.append(",".join(flags) if flags else "NONE")
        final_proj.append(fp)
        final_side.append(side)
        danger.append("‼️ DANGER" if is_danger else "")
        tiers.append(tier)

    out["APP82 Sustainable K Anchor"] = anchors
    out["APP82 Reality Adjustment"] = adjustments
    out["APP82 Reality Reason"] = reasons
    out["APP82 Role Validation"] = roles
    out["APP82 Contradiction Flags"] = contradictions
    out["APP82 Final K Projection"] = final_proj
    out["APP82 Final Side"] = final_side
    out["APP82 Danger"] = danger
    out["APP82 Selection Tier"] = tiers
    return out

# Wrap the final K table once. Preserve all upstream engines and App78.
try:
    _app82_prev_build_kproj_table = build_kproj_table
    def build_kproj_table(*args, **kwargs):
        _df = _app82_prev_build_kproj_table(*args, **kwargs)
        return _app82_apply(_df)
except Exception:
    pass


# =============================================================================
# APP85 — ORIGINAL-K PRESERVATION + TARGETED K MISS DIAGNOSTICS
# Architecture:
#   ORIGINAL BASE_K (preserved) ->
#   Lineup K Signal + Arsenal Signal + BF/Workload Risk +
#   Line Difficulty + Recent Skill -> Risk/Upside classification
#
# IMPORTANT: Diagnostic signals DO NOT overwrite BASE_K.
# They are exported separately for backtesting. Projection adjustments should
# only be enabled after historical testing proves incremental accuracy.
# =============================================================================
import numpy as _a85_np
import pandas as _a85_pd

APP85_VERSION = "APP85_ORIGINAL_K_PLUS_TARGETED_DIAGNOSTICS_v1"

def _a85_num(v, default=_a85_np.nan):
    try:
        x = float(v)
        return x if _a85_np.isfinite(x) else default
    except Exception:
        return default

def _a85_first(row, names):
    for n in names:
        if n in row.index:
            x = _a85_num(row.get(n))
            if _a85_np.isfinite(x):
                return x
    return _a85_np.nan

def _a85_pct(v):
    x = _a85_num(v)
    if not _a85_np.isfinite(x):
        return _a85_np.nan
    return x / 100.0 if x > 1 else x

def _a85_apply(df):
    if df is None or not isinstance(df, _a85_pd.DataFrame) or df.empty:
        return df
    z = df.copy()

    base_candidates = [
        "APP78 Final K Projection", "APP78 Final K PROJ",
        "Matchup Intelligence Final K Projection", "Final K PROJ",
        "K PROJ", "Projection", "Beta Projection"
    ]
    line_candidates = ["UD Line", "Line", "K Line", "stat_value"]
    ip_candidates = ["IP", "IP PROJ", "Projected IP", "Beta IP", "Projected Innings"]
    bf_candidates = ["Exp BF", "Expected BF", "Projected BF", "BF PROJ", "BF"]

    rows = []
    for _, r in z.iterrows():
        base = _a85_first(r, base_candidates)
        line = _a85_first(r, line_candidates)
        ip = _a85_first(r, ip_candidates)
        bf = _a85_first(r, bf_candidates)
        pk = _a85_pct(_a85_first(r, ["Pitcher K%", "K%", "Pitcher K Rate %", "Season K%"]))
        oppk = _a85_pct(_a85_first(r, [
            "Opponent K%", "Opp K%", "K Env Blend %", "Recency Team K Blend",
            "Opp L5 K% vs Hand", "Opp L15 K% vs Hand", "Opp L30 K% vs Hand"
        ]))
        csw = _a85_pct(_a85_first(r, ["T12 CSW%", "CSW%", "CSW %"]))
        sw = _a85_pct(_a85_first(r, ["T12 SwStr%", "SwStr%", "SwStr %"]))
        putaway = _a85_pct(_a85_first(r, ["PutAway%", "Putaway Rate", "Put Away %", "PutAway Rate"]))

        # Lineup-specific K opportunity: use actual lineup fields when present.
        lineup_vals = []
        for c in r.index:
            cl = c.lower()
            if ("lineup" in cl or "batter" in cl) and "k%" in cl:
                x = _a85_pct(r.get(c))
                if _a85_np.isfinite(x):
                    lineup_vals.append(x)
        lineup_k = sum(lineup_vals)/len(lineup_vals) if lineup_vals else _a85_np.nan

        # Arsenal compatibility: consume existing pitch/arsenal matchup fields if available.
        arsenal = _a85_first(r, [
            "Pitch Arsenal Matchup", "Pitch Arsenal Matchup Score",
            "Arsenal Matchup Score", "Arsenal Edge", "Pitch Mix Matchup"
        ])

        # Existing BF-to-K projections are audit anchors, not replacements for BASE_K.
        bfk1 = _a85_first(r, ["BF-K Expected K 2.1"])
        bfk2 = _a85_first(r, ["BF-to-K Conversion Projection 2.2"])
        bfk = _a85_np.nan
        vals = [x for x in [bfk1, bfk2] if _a85_np.isfinite(x)]
        if vals: bfk = sum(vals)/len(vals)

        # Expected BF uncertainty / workload risk.
        workload_flags = []
        if _a85_np.isfinite(ip) and ip < 3.5:
            workload_flags.append("LOW_IP")
        if _a85_np.isfinite(bf) and bf < 16:
            workload_flags.append("LOW_BF")
        if _a85_np.isfinite(ip) and _a85_np.isfinite(bf) and ip > 0:
            bf_per_ip = bf/ip
            if bf_per_ip < 3.5 or bf_per_ip > 5.5:
                workload_flags.append("BF_IP_CONTRADICTION")

        # Line difficulty: flag thresholds materially above BASE_K / historical-style expectation.
        line_diff = (line - base) if (_a85_np.isfinite(line) and _a85_np.isfinite(base)) else _a85_np.nan
        line_flag = ""
        if _a85_np.isfinite(line_diff):
            if line_diff >= 1.0: line_flag = "HARD_LINE_ABOVE_BASE"
            elif line_diff >= 0.5: line_flag = "LINE_ABOVE_BASE"
            elif line_diff <= -1.0: line_flag = "FAVORABLE_LINE_BELOW_BASE"

        # Recent skill signal from CSW/SwStr without changing projection.
        recent_skill = []
        if _a85_np.isfinite(csw):
            recent_skill.append((csw - 0.27) / 0.05)
        if _a85_np.isfinite(sw):
            recent_skill.append((sw - 0.12) / 0.04)
        recent_score = sum(recent_skill)/len(recent_skill) if recent_skill else _a85_np.nan

        # Team/lineup opportunity differential.
        matchup_k = lineup_k if _a85_np.isfinite(lineup_k) else oppk
        lineup_signal = _a85_np.nan
        if _a85_np.isfinite(matchup_k) and _a85_np.isfinite(pk):
            lineup_signal = (0.55*pk + 0.45*matchup_k) * (bf if _a85_np.isfinite(bf) else 0)

        # Risk/upside classification only.
        tags = []
        if _a85_np.isfinite(lineup_signal) and _a85_np.isfinite(base):
            if lineup_signal >= base + 1.0: tags.append("LINEUP_K_UPSIDE")
            elif lineup_signal <= base - 1.0: tags.append("LINEUP_K_DOWNSIDE")
        if _a85_np.isfinite(bfk) and _a85_np.isfinite(base):
            if bfk >= base + 1.0: tags.append("BFK_UPSIDE")
            elif bfk <= base - 1.0: tags.append("BFK_DOWNSIDE")
        if _a85_np.isfinite(recent_score):
            if recent_score >= 0.75: tags.append("RECENT_SKILL_UP")
            elif recent_score <= -0.75: tags.append("RECENT_SKILL_DOWN")
        if workload_flags: tags.append("WORKLOAD_RISK")
        if line_flag: tags.append(line_flag)

        # Protect elite-K pitchers from automatic generic downside classifications.
        elite = _a85_np.isfinite(pk) and pk >= 0.28
        if elite: tags.append("ELITE_K_SKILL")

        upside = sum(t in tags for t in ["LINEUP_K_UPSIDE","BFK_UPSIDE","RECENT_SKILL_UP","FAVORABLE_LINE_BELOW_BASE"])
        risk = sum(t in tags for t in ["LINEUP_K_DOWNSIDE","BFK_DOWNSIDE","RECENT_SKILL_DOWN","WORKLOAD_RISK","HARD_LINE_ABOVE_BASE"])
        if upside >= 2 and risk == 0:
            cls = "UPSIDE CONFIRMED"
        elif risk >= 2 and upside == 0:
            cls = "‼️ DANGER"
        elif upside > risk:
            cls = "UPSIDE LEAN"
        elif risk > upside:
            cls = "RISK LEAN"
        else:
            cls = "NEUTRAL"

        rows.append({
            "APP85 BASE_K (Original Preserved)": base,
            "APP85 Final K Projection": base,
            "APP85 Lineup K Signal": lineup_signal,
            "APP85 Lineup K%": lineup_k,
            "APP85 Pitcher K%": pk*100 if _a85_np.isfinite(pk) else _a85_np.nan,
            "APP85 Opponent K%": oppk*100 if _a85_np.isfinite(oppk) else _a85_np.nan,
            "APP85 Expected BF": bf,
            "APP85 PutAway Rate": putaway*100 if _a85_np.isfinite(putaway) else _a85_np.nan,
            "APP85 Arsenal Matchup Score": arsenal,
            "APP85 BF-to-K Anchor": bfk,
            "APP85 Recent Skill Score": recent_score,
            "APP85 Line Difficulty": line_diff,
            "APP85 Workload Risk": ",".join(workload_flags) if workload_flags else "NONE",
            "APP85 Risk/Upside Tags": ",".join(tags) if tags else "NONE",
            "APP85 Risk/Upside Class": cls,
            "APP85 Projection Adjustment": 0.0,
            "APP85 Adjustment Mode": "DIAGNOSTIC_ONLY_BACKTEST_FIRST",
        })

    audit = _a85_pd.DataFrame(rows, index=z.index)
    for c in audit.columns:
        z[c] = audit[c]
    return z

# Wrap the active final K table before Streamlit UI renders.
try:
    _a85_prev_build_kproj_table = build_kproj_table
    def build_kproj_table(*args, **kwargs):
        _df = _a85_prev_build_kproj_table(*args, **kwargs)
        return _a85_apply(_df)
except Exception:
    pass


# =============================================================================
# APP86 — DAILY LINEUP K% REFRESH / TEAM-LINEUP K ENVIRONMENT
# Preserves Original BASE_K and Pitching Outs. Diagnostic only.
# =============================================================================
import time as _a86_time
import numpy as _a86_np
import pandas as _a86_pd

APP86_VERSION = "APP86_PRELINEUP_RELIABILITY_v4_ROTOWIRE_WIDGETS_FANTASYPROS_HAND"

def _a86_num(v):
    try:
        x = float(v)
        return x if _a86_np.isfinite(x) else _a86_np.nan
    except Exception:
        return _a86_np.nan

def _a86_pct(v):
    x = _a86_num(v)
    if not _a86_np.isfinite(x):
        return _a86_np.nan
    return x / 100.0 if x > 1 else x

def _a86_lineup_k_values(row):
    overall, vs_r, vs_l = [], [], []
    for c in row.index:
        cl = str(c).lower()
        # Never re-ingest derived APP/team summary columns as if they were individual hitters.
        # This prevents recursive 30-40% lineup K readings from prior pipeline outputs.
        if any(tag in cl for tag in ["app85", "app86", "app87", "app88", "app89", "app95", "file33", "team batter", "team k", "opponent k", "matchup intel", "daily lineup team"]):
            continue
        if "k%" not in cl or not any(t in cl for t in ["lineup", "batter", "hitter"]):
            continue
        x = _a86_pct(row.get(c))
        if not _a86_np.isfinite(x):
            continue
        if "vs rhp" in cl or "vs right" in cl:
            vs_r.append(x)
        elif "vs lhp" in cl or "vs left" in cl:
            vs_l.append(x)
        else:
            overall.append(x)
    return overall, vs_r, vs_l

def _a86_apply(df):
    if df is None or not isinstance(df, _a86_pd.DataFrame) or df.empty:
        return df
    out = df.copy()
    team_vals=[]; hand_vals=[]; counts=[]; statuses=[]; sources=[]; stamps=[]

    for _, row in out.iterrows():
        overall, vs_r, vs_l = _a86_lineup_k_values(row)
        hand = str(row.get("Pitcher Hand", row.get("Throws", row.get("Pitcher Throws","")))).upper()
        overall_avg = sum(overall)/len(overall) if overall else _a86_np.nan

        # Primary engine now exports the resolved batter-level lineup K% and hitter count.
        # APP86 must consume that directly instead of trying to rediscover nested lineup rows
        # from flattened dataframe columns. This was the cause of false TEAM_RATE_FALLBACK.
        primary_lineup_k = _a86_pct(row.get("Lineup K%"))
        primary_n = int(_a86_num(row.get("Lineup Batter Count"))) if _a86_np.isfinite(_a86_num(row.get("Lineup Batter Count"))) else 0
        primary_source = str(row.get("Projection Source", row.get("Lineup", "")) or "").upper()
        rw_status = str(row.get("RotoWire Status") or "").upper()

        if _a86_np.isfinite(primary_lineup_k) and primary_n >= 5 and "TEAM FALLBACK" not in primary_source:
            hand_avg = primary_lineup_k
            overall_avg = primary_lineup_k
            n = primary_n
            if "TRUE LINEUP" in primary_source or "CONFIRMED" in str(row.get("Lineup", "")).upper():
                status, source = f"CONFIRMED_LINEUP_{n}", "PRIMARY_BATTER_LEVEL_LINEUP"
            elif "EXPECTED" in primary_source or "ROTOWIRE" in primary_source or "FANGRAPHS" in primary_source:
                status, source = f"EXPECTED_LINEUP_{n}", ("ROTOWIRE_EXPECTED_CONSENSUS" if rw_status == "SUCCESS" else "EXPECTED_LINEUP_CONSENSUS")
            else:
                status, source = f"BATTER_LINEUP_{n}", "PRIMARY_BATTER_LEVEL_LINEUP"
        else:
            if hand.startswith("L") and vs_l:
                hand_avg, n = sum(vs_l)/len(vs_l), len(vs_l)
            elif hand.startswith("R") and vs_r:
                hand_avg, n = sum(vs_r)/len(vs_r), len(vs_r)
            else:
                hand_avg, n = overall_avg, len(overall)

            if not _a86_np.isfinite(hand_avg):
                if hand.startswith("L"):
                    hand_avg = _a86_pct(row.get("Opp K% vs LHP Official"))
                elif hand.startswith("R"):
                    hand_avg = _a86_pct(row.get("Opp K% vs RHP Official"))

            if not _a86_np.isfinite(overall_avg):
                overall_avg = _a86_pct(row.get("Team Batter K% Overall Official"))

            if n >= 9:
                status, source = "COMPLETE_9", "BATTER_LEVEL_LINEUP"
            elif n >= 7:
                status, source = "NEAR_COMPLETE_7_8", "BATTER_LEVEL_LINEUP"
            elif n > 0:
                status, source = f"PARTIAL_LINEUP_{n}", "BATTER_LEVEL_LINEUP"
            else:
                status, source = "TEAM_RATE_FALLBACK", "OFFICIAL_TEAM_K_RATE_FALLBACK"

        team_vals.append(overall_avg*100 if _a86_np.isfinite(overall_avg) else _a86_np.nan)
        hand_vals.append(hand_avg*100 if _a86_np.isfinite(hand_avg) else _a86_np.nan)
        counts.append(int(n))
        statuses.append(status)
        sources.append(source)
        stamps.append(_a86_time.strftime("%Y-%m-%d %H:%M:%S"))

    out["APP86 Daily Lineup Team K%"] = team_vals
    out["APP86 Daily Lineup K% vs Pitcher Hand"] = hand_vals
    out["APP86 Lineup Batter Count"] = counts
    out["APP86 Lineup Refresh Status"] = statuses
    out["APP86 Lineup K% Source"] = sources
    out["APP86 Lineup Refresh Timestamp"] = stamps

    if "APP85 Lineup K%" in out.columns:
        fresh = _a86_pd.to_numeric(out["APP86 Daily Lineup K% vs Pitcher Hand"], errors="coerce")
        old = _a86_pd.to_numeric(out["APP85 Lineup K%"], errors="coerce")
        out["APP85 Lineup K%"] = fresh.where(fresh.notna(), old)
    return out

try:
    _a86_prev_build_kproj_table = build_kproj_table
    def build_kproj_table(*args, **kwargs):
        return _a86_apply(_a86_prev_build_kproj_table(*args, **kwargs))
except Exception:
    pass


# =============================================================================
# APP87 — FULL ACTIVE MATCHUP ADJUSTMENT ENGINE
# Original BASE_K remains the anchor. Pitching Outs stays untouched.
# =============================================================================
import numpy as _a87_np
import pandas as _a87_pd

APP87_VERSION = "APP87_FULL_ACTIVE_K_MATCHUP_ENGINE_v1"

def _a87_num(v):
    try:
        x = float(v)
        return x if _a87_np.isfinite(x) else _a87_np.nan
    except Exception:
        return _a87_np.nan

def _a87_clip(x, lo, hi):
    try:
        return max(lo, min(hi, float(x)))
    except Exception:
        return 0.0

def _a87_apply(df):
    if df is None or not isinstance(df, _a87_pd.DataFrame) or df.empty:
        return df

    out = df.copy()
    final_proj=[]; lineup_adj_col=[]; bfk_adj_col=[]; recent_adj_col=[]
    workload_adj_col=[]; total_adj_col=[]; side_col=[]; flip_guard_col=[]
    active_signal_count_col=[]; decision_note_col=[]

    for _, row in out.iterrows():
        base = _a87_num(row.get("APP85 BASE_K (Original Preserved)"))
        if not _a87_np.isfinite(base):
            base = _a87_num(row.get("APP85 Final K Projection"))
        if not _a87_np.isfinite(base):
            base = _a87_num(row.get("K PROJ"))

        line = _a87_num(row.get("UD Line"))
        if not _a87_np.isfinite(line):
            line = _a87_num(row.get("Line"))

        lineup_k = _a87_num(row.get("APP86 Daily Lineup K% vs Pitcher Hand"))
        opp_k = _a87_num(row.get("APP85 Opponent K%"))
        exp_bf = _a87_num(row.get("APP85 Expected BF"))

        lineup_adj = 0.0
        if _a87_np.isfinite(lineup_k) and _a87_np.isfinite(opp_k):
            if not _a87_np.isfinite(exp_bf):
                exp_bf = 22.0
            raw_lineup = ((lineup_k - opp_k) / 100.0) * exp_bf
            lineup_adj = _a87_clip(raw_lineup * 0.35, -0.22, 0.22)

        bfk = _a87_num(row.get("APP85 BF-to-K Anchor"))
        bfk_adj = 0.0
        if _a87_np.isfinite(bfk) and _a87_np.isfinite(base):
            bfk_adj = _a87_clip((bfk - base) * 0.16, -0.18, 0.18)

        recent_score = _a87_num(row.get("APP85 Recent Skill Score"))
        recent_adj = 0.0
        if _a87_np.isfinite(recent_score):
            recent_adj = _a87_clip(recent_score * 0.07, -0.12, 0.12)

        workload = str(row.get("APP85 Workload Risk", "") or "").upper()
        workload_adj = 0.0
        if "BF_IP_CONTRADICTION" in workload:
            workload_adj -= 0.10
        elif "LOW_BF" in workload and "LOW_IP" in workload:
            workload_adj -= 0.08
        elif "LOW_BF" in workload or "LOW_IP" in workload:
            workload_adj -= 0.04

        raw_total = lineup_adj + bfk_adj + recent_adj + workload_adj
        total_adj = _a87_clip(raw_total, -0.45, 0.45)
        tentative = base + total_adj if _a87_np.isfinite(base) else base

        signals = [lineup_adj, bfk_adj, recent_adj, workload_adj]
        pos = sum(1 for x in signals if x >= 0.04)
        neg = sum(1 for x in signals if x <= -0.04)
        active_count = pos + neg

        final_side = ""
        flip_guard = "NO_LINE"
        if _a87_np.isfinite(line) and _a87_np.isfinite(base):
            base_side = "OVER" if base > line else "UNDER"
            tent_side = "OVER" if tentative > line else "UNDER"
            final_side = tent_side
            flip_guard = "NO_FLIP"
            if tent_side != base_side:
                agree = pos if total_adj > 0 else neg
                if abs(total_adj) < 0.30 or agree < 3:
                    final_side = base_side
                    flip_guard = "ORIGINAL_SIDE_PROTECTED"
                else:
                    flip_guard = "FLIP_ALLOWED_3_SIGNAL_CONFIRMATION"

        final_proj.append(tentative)
        lineup_adj_col.append(lineup_adj)
        bfk_adj_col.append(bfk_adj)
        recent_adj_col.append(recent_adj)
        workload_adj_col.append(workload_adj)
        total_adj_col.append(total_adj)
        side_col.append(final_side)
        flip_guard_col.append(flip_guard)
        active_signal_count_col.append(active_count)

        notes=[]
        if abs(lineup_adj) >= 0.04: notes.append(f"lineup {lineup_adj:+.2f}")
        if abs(bfk_adj) >= 0.04: notes.append(f"BF-K {bfk_adj:+.2f}")
        if abs(recent_adj) >= 0.04: notes.append(f"recent {recent_adj:+.2f}")
        if abs(workload_adj) >= 0.04: notes.append(f"workload {workload_adj:+.2f}")
        notes.append(flip_guard)
        decision_note_col.append("; ".join(notes))

    out["APP87 Original BASE_K"] = out.get("APP85 BASE_K (Original Preserved)")
    out["APP87 Daily Lineup K Adjustment"] = lineup_adj_col
    out["APP87 BF-to-K Adjustment"] = bfk_adj_col
    out["APP87 Recent Skill Adjustment"] = recent_adj_col
    out["APP87 Workload Adjustment"] = workload_adj_col
    out["APP87 Total K Adjustment"] = total_adj_col
    out["APP87 Final K Projection"] = final_proj
    out["APP87 Final Side"] = side_col
    out["APP87 Side Flip Guard"] = flip_guard_col
    out["APP87 Active Signal Count"] = active_signal_count_col
    out["APP87 Decision Note"] = decision_note_col

    if "K PROJ" in out.columns:
        out["K PROJ"] = out["APP87 Final K Projection"]
    if "Final K Projection" in out.columns:
        out["Final K Projection"] = out["APP87 Final K Projection"]

    return out

try:
    _a87_prev_build_kproj_table = build_kproj_table
    def build_kproj_table(*args, **kwargs):
        return _a87_apply(_a87_prev_build_kproj_table(*args, **kwargs))
except Exception:
    pass


# =============================================================================
# APP88 — FULL ORIGINAL-K + ALL MATCHUP LAYERS
#
# Core rule:
#   ORIGINAL BASE_K stays the foundation.
#   Pitching Outs engine stays untouched.
#
# Active K layers:
#   1) Daily batter-by-batter lineup K opportunity vs pitcher hand
#   2) Team/opponent K environment
#   3) Arsenal-vs-lineup compatibility
#   4) PutAway rate / opponent whiff interaction
#   5) Expected BF distribution / workload uncertainty
#   6) Recent CSW / SwStr / recent skill
#   7) Recent starts / historical same-line performance
#   8) Market/model probability agreement
#   9) Historical line difficulty
#
# All adjustments are individually capped and the TOTAL adjustment is capped.
# No blanket downward suppression. Original side is protected unless multiple
# independent signals agree strongly enough to justify a flip.
# =============================================================================

import numpy as _a88_np
import pandas as _a88_pd

APP88_VERSION = "APP88_FULL_ORIGINAL_K_ALL_MATCHUP_LAYERS_v1"

def _a88_num(v):
    try:
        x = float(v)
        return x if _a88_np.isfinite(x) else _a88_np.nan
    except Exception:
        return _a88_np.nan

def _a88_pct(v):
    x = _a88_num(v)
    if not _a88_np.isfinite(x):
        return _a88_np.nan
    return x / 100.0 if x > 1 else x

def _a88_clip(x, lo, hi):
    try:
        return max(lo, min(hi, float(x)))
    except Exception:
        return 0.0

def _a88_first(row, names):
    for n in names:
        if n in row.index:
            x = _a88_num(row.get(n))
            if _a88_np.isfinite(x):
                return x
    return _a88_np.nan

def _a88_collect_batter_k(row, pitcher_hand):
    overall=[]; hand_specific=[]
    for c in row.index:
        cl = str(c).lower()
        if "k%" not in cl:
            continue
        if not any(t in cl for t in ["lineup", "batter", "hitter"]):
            continue
        x = _a88_pct(row.get(c))
        if not _a88_np.isfinite(x):
            continue
        overall.append(x)
        if pitcher_hand.startswith("L") and any(t in cl for t in ["vs lhp","vs left"]):
            hand_specific.append(x)
        elif pitcher_hand.startswith("R") and any(t in cl for t in ["vs rhp","vs right"]):
            hand_specific.append(x)
    use = hand_specific if hand_specific else overall
    return use

def _a88_arsenal_signal(row):
    # Prefer explicit existing arsenal matchup score if the app already calculates one.
    explicit = _a88_first(row, [
        "Pitch Arsenal Matchup Score", "Arsenal Matchup Score", "Arsenal Edge",
        "Pitch Mix Matchup", "Pitch Arsenal Matchup"
    ])
    if _a88_np.isfinite(explicit):
        # Normalize common 0-100 or -1..1 style scales conservatively.
        if abs(explicit) > 2:
            return _a88_clip((explicit - 50.0) / 50.0, -1.0, 1.0)
        return _a88_clip(explicit, -1.0, 1.0)

    # Fallback: infer from pitch-specific whiff/K matchup columns.
    vals=[]
    for c in row.index:
        cl=str(c).lower()
        if not any(p in cl for p in ["four-seam","4-seam","ff","sinker","si","slider","sl","changeup","ch","curve","cu","cutter","fc","splitter","fs","sweeper","st"]):
            continue
        if not any(m in cl for m in ["whiff","k%","strikeout","matchup","edge"]):
            continue
        x=_a88_num(row.get(c))
        if not _a88_np.isfinite(x):
            continue
        # Normalize percentages and generic scores.
        if 0 <= x <= 1:
            vals.append((x-0.25)/0.15)
        elif 1 < x <= 100:
            vals.append((x-25.0)/15.0)
        elif -5 <= x <= 5:
            vals.append(x)
    if not vals:
        return _a88_np.nan
    return _a88_clip(sum(vals)/len(vals), -1.0, 1.0)

def _a88_apply(df):
    if df is None or not isinstance(df, _a88_pd.DataFrame) or df.empty:
        return df

    out=df.copy()
    rows=[]

    for _, row in out.iterrows():
        base=_a88_first(row, [
            "APP87 Original BASE_K","APP85 BASE_K (Original Preserved)",
            "Original K PROJ","K PROJ","Final K Projection"
        ])
        line=_a88_first(row, ["UD Line","Line","K Line","stat_value"])
        hand=str(row.get("Pitcher Hand", row.get("Throws", row.get("Pitcher Throws","")))).upper()

        # 1) BATTER-BY-BATTER LINEUP K OPPORTUNITY
        batter_ks=_a88_collect_batter_k(row, hand)
        lineup_k=(sum(batter_ks)/len(batter_ks)) if batter_ks else _a88_pct(row.get("APP86 Daily Lineup K% vs Pitcher Hand"))
        team_k=_a88_pct(_a88_first(row, ["APP85 Opponent K%","Opp K%","Opponent K%"]))
        exp_bf=_a88_first(row, ["APP85 Expected BF","Exp BF","Expected BF","Projected BF"])
        if not _a88_np.isfinite(exp_bf):
            exp_bf=22.0

        lineup_adj=0.0
        if _a88_np.isfinite(lineup_k) and _a88_np.isfinite(team_k):
            lineup_adj=_a88_clip(((lineup_k-team_k)*exp_bf)*0.35, -0.22, 0.22)

        # 2) TEAM K ENVIRONMENT / PITCHER K INTERACTION
        pitcher_k=_a88_pct(_a88_first(row, ["APP85 Pitcher K%","Pitcher K%","K%"]))
        team_env_adj=0.0
        if _a88_np.isfinite(pitcher_k) and _a88_np.isfinite(lineup_k):
            blend=(0.55*pitcher_k)+(0.45*lineup_k)
            implied=blend*exp_bf
            team_env_adj=_a88_clip((implied-base)*0.08, -0.12, 0.12) if _a88_np.isfinite(base) else 0.0

        # 3) ARSENAL VS LINEUP
        arsenal_score=_a88_arsenal_signal(row)
        arsenal_adj=_a88_clip(arsenal_score*0.12, -0.12, 0.12) if _a88_np.isfinite(arsenal_score) else 0.0

        # 4) PUTAWAY + OPPONENT WHIFF INTERACTION
        putaway=_a88_pct(_a88_first(row, ["PutAway%","Putaway Rate","Put Away %","PutAway Rate"]))
        opp_whiff=_a88_pct(_a88_first(row, ["Opponent Whiff%","Opp Whiff%","Team Whiff%","Lineup Whiff%"]))
        whiff_adj=0.0
        whiff_parts=[]
        if _a88_np.isfinite(putaway):
            whiff_parts.append((putaway-0.30)/0.12)
        if _a88_np.isfinite(opp_whiff):
            whiff_parts.append((opp_whiff-0.25)/0.10)
        if whiff_parts:
            whiff_adj=_a88_clip((sum(whiff_parts)/len(whiff_parts))*0.08, -0.10, 0.10)

        # 5) EXPECTED BF DISTRIBUTION / WORKLOAD UNCERTAINTY
        bf_p10=_a88_first(row, ["BF P10","Expected BF P10","Projected BF P10","P10 BF"])
        bf_p90=_a88_first(row, ["BF P90","Expected BF P90","Projected BF P90","P90 BF"])
        workload_adj=0.0
        workload_risk="NONE"
        if _a88_np.isfinite(bf_p10) and _a88_np.isfinite(bf_p90):
            spread=bf_p90-bf_p10
            if spread >= 10:
                workload_risk="WIDE_BF_RANGE"
            elif spread >= 7:
                workload_risk="MODERATE_BF_RANGE"
        else:
            # Fallback from IP uncertainty / explicit workload-risk flags.
            wr=str(row.get("APP85 Workload Risk","") or "").upper()
            if "BF_IP_CONTRADICTION" in wr:
                workload_risk="BF_IP_CONTRADICTION"
                workload_adj=-0.08
            elif "LOW_BF" in wr and "LOW_IP" in wr:
                workload_risk="LOW_BF_LOW_IP"
                workload_adj=-0.06
            elif "LOW_BF" in wr or "LOW_IP" in wr:
                workload_risk="LOW_OPPORTUNITY"
                workload_adj=-0.03

        # 6) RECENT SKILL
        recent_score=_a88_num(row.get("APP85 Recent Skill Score"))
        recent_adj=_a88_clip(recent_score*0.06, -0.10, 0.10) if _a88_np.isfinite(recent_score) else 0.0

        # 7) RECENT STARTS / HISTORICAL SAME-LINE PERFORMANCE
        hist_rate=_a88_pct(_a88_first(row, [
            "Same Line Hit Rate","Historical Line Hit Rate","Recent Same Line Hit Rate",
            "L10 Hit Rate","L5 Hit Rate"
        ]))
        hist_adj=0.0
        if _a88_np.isfinite(hist_rate):
            # Very small influence; direction relative to current side.
            if _a88_np.isfinite(line) and _a88_np.isfinite(base):
                base_side="OVER" if base>line else "UNDER"
                directional=(hist_rate-0.50)
                hist_adj=_a88_clip(directional*0.16, -0.08, 0.08)
                if base_side=="UNDER":
                    hist_adj=-hist_adj

        # 8) MARKET / MODEL PROBABILITY AGREEMENT
        model_prob=_a88_pct(_a88_first(row, [
            "Fair Probability","Model Probability","K Model Probability","Win Probability"
        ]))
        market_prob=_a88_pct(_a88_first(row, [
            "No Vig Probability","Market Probability","Market Implied Probability"
        ]))
        market_adj=0.0
        if _a88_np.isfinite(model_prob) and _a88_np.isfinite(market_prob):
            market_adj=_a88_clip((model_prob-market_prob)*0.20, -0.06, 0.06)

        # 9) HISTORICAL LINE DIFFICULTY
        hist_avg=_a88_first(row, [
            "Historical K Average","Recent K Average","L10 K Avg","Season K Avg"
        ])
        line_diff_flag="NONE"
        line_adj=0.0
        if _a88_np.isfinite(line) and _a88_np.isfinite(hist_avg):
            diff=line-hist_avg
            if diff>=1.0:
                line_diff_flag="HARD_LINE_ABOVE_HIST_AVG"
                line_adj=-0.05
            elif diff<=-1.0:
                line_diff_flag="FAVORABLE_LINE_BELOW_HIST_AVG"
                line_adj=0.05

        # Existing BF-to-K anchor
        bfk=_a88_num(row.get("APP85 BF-to-K Anchor"))
        bfk_adj=_a88_clip((bfk-base)*0.14,-0.16,0.16) if _a88_np.isfinite(bfk) and _a88_np.isfinite(base) else 0.0

        # Combine all active signals.
        adjustments=[
            lineup_adj,team_env_adj,arsenal_adj,whiff_adj,workload_adj,
            recent_adj,hist_adj,market_adj,line_adj,bfk_adj
        ]
        raw_total=sum(adjustments)
        total_adj=_a88_clip(raw_total,-0.45,0.45)
        tentative=base+total_adj if _a88_np.isfinite(base) else base

        # Signal agreement for side flips.
        pos=sum(1 for x in adjustments if x>=0.04)
        neg=sum(1 for x in adjustments if x<=-0.04)
        active=pos+neg
        final_side=""
        flip_guard="NO_LINE"
        if _a88_np.isfinite(line) and _a88_np.isfinite(base):
            base_side="OVER" if base>line else "UNDER"
            tent_side="OVER" if tentative>line else "UNDER"
            final_side=tent_side
            flip_guard="NO_FLIP"
            if tent_side!=base_side:
                agree=pos if total_adj>0 else neg
                if abs(total_adj)<0.30 or agree<3:
                    final_side=base_side
                    flip_guard="ORIGINAL_SIDE_PROTECTED"
                else:
                    flip_guard="FLIP_ALLOWED_3_SIGNAL_CONFIRMATION"

        # Risk/upside classification.
        if pos>=3 and neg<=1:
            cls="UPSIDE CONFIRMED"
        elif neg>=3 and pos<=1:
            cls="‼️ DANGER"
        elif pos>neg:
            cls="UPSIDE LEAN"
        elif neg>pos:
            cls="RISK LEAN"
        else:
            cls="NEUTRAL"

        rows.append({
            "APP88 Original BASE_K":base,
            "APP88 Batter Lineup K%": lineup_k*100 if _a88_np.isfinite(lineup_k) else _a88_np.nan,
            "APP88 Batter Count":len(batter_ks),
            "APP88 Lineup K Adjustment":lineup_adj,
            "APP88 Team K Environment Adjustment":team_env_adj,
            "APP88 Arsenal Matchup Score":arsenal_score,
            "APP88 Arsenal Adjustment":arsenal_adj,
            "APP88 PutAway Rate":putaway*100 if _a88_np.isfinite(putaway) else _a88_np.nan,
            "APP88 Opponent Whiff%":opp_whiff*100 if _a88_np.isfinite(opp_whiff) else _a88_np.nan,
            "APP88 Whiff Interaction Adjustment":whiff_adj,
            "APP88 BF P10":bf_p10,
            "APP88 BF P90":bf_p90,
            "APP88 Workload Risk":workload_risk,
            "APP88 Workload Adjustment":workload_adj,
            "APP88 Recent Skill Adjustment":recent_adj,
            "APP88 Historical Line Adjustment":hist_adj,
            "APP88 Market Agreement Adjustment":market_adj,
            "APP88 Line Difficulty":line_diff_flag,
            "APP88 Line Difficulty Adjustment":line_adj,
            "APP88 BF-to-K Adjustment":bfk_adj,
            "APP88 Total K Adjustment":total_adj,
            "APP88 Final K Projection":tentative,
            "APP88 Final Side":final_side,
            "APP88 Side Flip Guard":flip_guard,
            "APP88 Active Positive Signals":pos,
            "APP88 Active Negative Signals":neg,
            "APP88 Active Signal Count":active,
            "APP88 Risk/Upside Class":cls,
        })

    audit=_a88_pd.DataFrame(rows,index=out.index)
    for c in audit.columns:
        out[c]=audit[c]

    # Promote active K projection only. Pitching Outs is untouched.
    if "K PROJ" in out.columns:
        out["K PROJ"]=out["APP88 Final K Projection"]
    if "Final K Projection" in out.columns:
        out["Final K Projection"]=out["APP88 Final K Projection"]

    return out

try:
    _a88_prev_build_kproj_table=build_kproj_table
    def build_kproj_table(*args,**kwargs):
        return _a88_apply(_a88_prev_build_kproj_table(*args,**kwargs))
except Exception:
    pass



# =============================================================================
# APP95 SHARED FINAL-LAYER UTILITIES
#
# Legacy helpers remain for backward compatibility, but every new/canonical
# path below uses this single implementation.
# =============================================================================
def _safe_num(value, default=float("nan")):
    try:
        result = float(value)
        return result if np.isfinite(result) else default
    except (TypeError, ValueError):
        return default

def _safe_pct(value, default=float("nan")):
    result = _safe_num(value, default)
    if not np.isfinite(result):
        return default
    return result / 100.0 if result > 1.0 else result

def _safe_clip(value, low, high):
    result = _safe_num(value, 0.0)
    return max(float(low), min(float(high), result))

# =============================================================================
# APP89 — COPY/PASTE SLATE USES THE TRUE ACTIVE FINAL K PROJECTION
#
# Fixes a display-only mismatch:
# The old copy/paste builder still read "Line-Aware Smart Final K Projection",
# which could show stale pre-App88 numbers and stale Over/Under directions.
#
# This override uses:
#   APP88 Final K Projection
#   APP88 Final Side
#   current Underdog line
# and falls back safely only when an App88 field is unavailable.
#
# Projection math and Pitching Outs are untouched.
# =============================================================================

def build_copy_paste_k_slate(df, show_pass_notes=False, force_all_players_ou=False):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return ""

        d = df.copy()

        # Underdog only.
        if "Line Source" in d.columns:
            d = d[d["Line Source"].astype(str).str.upper().eq("UNDERDOG")].copy()

        # Normalize the active line column.
        if "UD/Line" not in d.columns:
            d["UD/Line"] = d.get("Line")
        d = d[~d["UD/Line"].astype(str).str.upper().isin(
            ["NO LINE", "NO_UD_LINE", "", "NAN", "NONE"]
        )].copy()

        # One current/primary row per pitcher.
        d = _owp_one_final_row_per_pitcher(d)

        lines = []
        for matchup, g in d.groupby("Matchup", sort=False):
            block = []

            for _, r in g.iterrows():
                line = safe_float(r.get("UD/Line"), None)

                # TRUE active projection priority.
                proj = safe_float(r.get("APP88 Final K Projection"), None)
                if proj is None:
                    proj = safe_float(r.get("K PROJ"), None)
                if proj is None:
                    proj = safe_float(r.get("Final K Projection"), None)
                if proj is None:
                    proj = safe_float(r.get("Line-Aware Smart Final K Projection"), None)

                # TRUE active side priority.
                side = str(r.get("APP88 Final Side") or "").upper().strip()
                if side not in {"OVER", "UNDER"} and proj is not None and line is not None:
                    side = "OVER" if proj > line else "UNDER"

                if side not in {"OVER", "UNDER"}:
                    if not show_pass_notes:
                        continue
                    symbol = "PASS"
                    edge = None
                else:
                    edge = None if proj is None or line is None else proj - line
                    abs_edge = abs(edge) if edge is not None else 0.0

                    # Match the user's clean slate style.
                    prefix = "O" if side == "OVER" else "U"
                    if abs_edge >= 1.00:
                        symbol = f"🔥 {prefix}"
                    elif abs_edge < 0.65:
                        symbol = f"⚠️ {prefix}"
                    else:
                        symbol = prefix

                ip = safe_float(r.get("IP Floor"), None)
                if ip is None:
                    ip = safe_float(r.get("IP PROJ"), None)
                if ip is None:
                    ip = safe_float(r.get("Projected IP"), None)

                line_txt = "NO LINE" if line is None else f"{line:.1f}"
                proj_txt = "—" if proj is None else f"{proj:.2f}"
                ip_txt = "—" if ip is None else f"{ip:.2f}"

                block.append(
                    f"• {r.get('Pitcher')} — {symbol} {line_txt} — {proj_txt} K — IP {ip_txt}"
                )

            if block:
                lines.append(str(matchup))
                lines.extend(block)
                lines.append("")

        return "\n".join(lines).strip()

    except Exception as e:
        return f"Slate builder unavailable: {e}"


# =============================================================================
# APP95 CANONICAL PUBLIC PIPELINE
#
# The historical wrapper chain is preserved internally for output parity.
# All UI/export consumers below this point use this one public entry point.
# RAW BASE_K is immutable and never reconstructed from a mid-pipeline field.
# Strikeout-line and Pitching-Outs line parsers are not modified here.
# =============================================================================
_APP95_COMPATIBILITY_K_PIPELINE = build_kproj_table

def build_kproj_table(board):
    """Canonical public K table.

    Runs the existing compatibility pipeline once, then normalizes the final
    output while preserving the immutable RAW BASE_K snapshot.
    """
    df = _APP95_COMPATIBILITY_K_PIPELINE(board)
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    out = df.copy()

    # Compatibility only: old cached objects may not contain the new snapshot.
    if "RAW BASE_K" not in out.columns:
        for candidate in ["Pre-App70 K PROJ", "Original K PROJ", "K PROJ"]:
            if candidate in out.columns:
                out["RAW BASE_K"] = pd.to_numeric(out[candidate], errors="coerce")
                break

    # Resolve the currently active final projection without changing the math.
    final_col = next(
        (
            c for c in [
                "APP88 Final K Projection",
                "Line-Aware Smart Final K Projection",
                "WRS Final K Projection",
                "TPS Final K Projection",
                "K PROJ",
            ]
            if c in out.columns
        ),
        None,
    )
    if final_col is not None:
        final_values = pd.to_numeric(out[final_col], errors="coerce")
        out["K PROJ"] = final_values
        out["Final K Projection"] = final_values
        out["Official K PROJ"] = final_values

    if "UD/Line" in out.columns and "K PROJ" in out.columns:
        live_line = pd.to_numeric(out["UD/Line"], errors="coerce")
        final_k = pd.to_numeric(out["K PROJ"], errors="coerce")
        out["Official K Edge"] = (final_k - live_line).round(2)

    out["Active K Pipeline"] = "APP95_CANONICAL"
    return out


# One final formatter only. It does not alter K lines, Outs lines, or projections.
def build_copy_paste_k_slate(df, show_pass_notes=False, force_all_players_ou=False):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return ""

        d = df.copy()
        if "Line Source" in d.columns:
            d = d[d["Line Source"].astype(str).str.upper().eq("UNDERDOG")].copy()

        if "UD/Line" not in d.columns:
            d["UD/Line"] = d.get("Line")
        d["UD/Line"] = pd.to_numeric(d["UD/Line"], errors="coerce")
        d = d[d["UD/Line"].notna()].copy()
        d = _owp_one_final_row_per_pitcher(d)

        projection_col = next(
            (
                c for c in [
                    "APP88 Final K Projection",
                    "K PROJ",
                    "Final K Projection",
                    "Line-Aware Smart Final K Projection",
                ]
                if c in d.columns
            ),
            None,
        )
        if projection_col is None:
            return ""

        output = []
        for matchup, group in d.groupby("Matchup", sort=False):
            block = []
            for _, row in group.iterrows():
                line = _safe_num(row.get("UD/Line"))
                proj = _safe_num(row.get(projection_col))
                if not np.isfinite(line) or not np.isfinite(proj):
                    continue

                side = str(row.get("APP88 Final Side") or "").upper().strip()
                if side not in {"OVER", "UNDER"}:
                    side = "OVER" if proj > line else "UNDER"

                edge = abs(proj - line)
                prefix = "O" if side == "OVER" else "U"
                symbol = (
                    f"🔥 {prefix}"
                    if edge >= 1.00
                    else (f"⚠️ {prefix}" if edge < 0.65 else prefix)
                )

                ip = float("nan")
                for column in ["IP Floor", "IP PROJ", "Projected IP"]:
                    if column in row.index:
                        candidate = _safe_num(row.get(column))
                        if np.isfinite(candidate):
                            ip = candidate
                            break

                ip_text = "—" if not np.isfinite(ip) else f"{ip:.2f}"
                block.append(
                    f"• {row.get('Pitcher')} — {symbol} {line:.1f} — "
                    f"{proj:.2f} K — IP {ip_text}"
                )

            if block:
                output.append(str(matchup))
                output.extend(block)
                output.append("")

        return "\n".join(output).strip()
    except Exception as exc:
        return f"Slate builder unavailable: {exc}"


def app95_pipeline_audit():
    """Internal architecture/version check."""
    return {
        "version": "APP95_REFACTOR_STAGE1_TRUE_RAW_BASE_SAFE",
        "raw_anchor": "RAW BASE_K",
        "public_k_entrypoint": "build_kproj_table",
        "copy_paste": "single canonical final formatter",
        "strikeout_line_parser_changed": False,
        "pitching_outs_line_parser_changed": False,
        "official_card_guard": "try/finally",
    }


# =============================================================================
# FILE 33 K PROJECTION MATCH LAYER
#
# Keep app (32).py as the base because it contains the Pitching Outs beta work,
# but make the public K projection match app (33).py. In app (32), the projection
# that exists at app (33)'s endpoint is preserved before the later App70/App75/
# App78/App82/App85/App88 layers begin as "Pre-App70 K PROJ".
#
# This layer only normalizes K projection display/export fields. It does not
# change Pitching Outs math, Pitching Outs line parsing, or any outs tabs.
# =============================================================================
FILE33_PROJECTION_MATCH_VERSION = "FILE33_PROJECTION_MATCH_2026_07_21"
_FILE33_MATCHED_K_PIPELINE = build_kproj_table


def _file33_match_num(value, default=np.nan):
    try:
        if value in (None, "", "—", "-", "None", "nan", "NaN", "NO LINE", "NO_UD_LINE"):
            return default
        result = float(value)
        return result if np.isfinite(result) else default
    except Exception:
        return default


def _file33_match_line(row):
    for column in ["UD/Line", "UD Line", "Line", "line", "K Line"]:
        if column in row.index:
            value = _file33_match_num(row.get(column))
            if np.isfinite(value):
                return value
    return np.nan


def _file33_match_projection(row):
    for column in [
        "Pre-App70 K PROJ",
        "Pre-App78 K PROJ",
        "Original K PROJ",
        "Matchup Intelligence Final K Projection",
        "Line-Aware Smart Final K Projection",
        "K PROJ",
        "Final K Projection",
    ]:
        if column in row.index:
            value = _file33_match_num(row.get(column))
            if np.isfinite(value):
                return value, column
    return np.nan, ""


def _file33_match_decision(projection, line, fallback=""):
    if not np.isfinite(projection):
        return fallback or "NO PROJECTION"
    if not np.isfinite(line):
        return fallback or "NO UD LINE"
    side = "OVER" if projection > line else "UNDER" if projection < line else "PUSH"
    if side == "PUSH":
        return "PASS"
    edge = abs(projection - line)
    if edge >= 1.00:
        return f"🔥 {side}"
    if edge >= 0.65:
        return f"⚠️ {side} LEAN"
    return f"🚫 PASS - {side} THIN EDGE"


def _file33_match_apply(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df

    out = df.copy()
    matched_projection = []
    matched_source = []
    matched_edge = []
    matched_side = []
    matched_decision = []

    for _, row in out.iterrows():
        projection, source = _file33_match_projection(row)
        line = _file33_match_line(row)
        fallback_decision = str(row.get("Pre-App70 Decision") or row.get("Decision") or "")

        matched_projection.append(np.nan if not np.isfinite(projection) else round(projection, 2))
        matched_source.append(source or "")

        if np.isfinite(projection) and np.isfinite(line):
            edge = round(projection - line, 2)
            matched_edge.append(edge)
            matched_side.append("OVER" if edge > 0 else "UNDER" if edge < 0 else "PUSH")
            matched_decision.append(_file33_match_decision(projection, line, fallback_decision))
        else:
            matched_edge.append(np.nan)
            matched_side.append("")
            matched_decision.append(fallback_decision or "NO LINE/PROJECTION")

    matched_series = pd.Series(matched_projection, index=out.index, dtype="float64")
    existing_k = pd.to_numeric(out["K PROJ"], errors="coerce") if "K PROJ" in out.columns else pd.Series(np.nan, index=out.index)
    final_projection = matched_series.where(matched_series.notna(), existing_k)

    out["File33 Matched K Projection"] = final_projection.round(2)
    out["File33 Projection Source"] = matched_source
    out["File33 Match Version"] = FILE33_PROJECTION_MATCH_VERSION

    # File33/legacy projection is now REFERENCE ONLY.  It must never overwrite the
    # active APP88/current matchup projection, edges, or decisions.
    out["File33 Reference Edge"] = pd.Series(matched_edge, index=out.index)
    out["File33 Reference Side"] = matched_side
    out["File33 Reference Decision"] = matched_decision
    out["Active K Pipeline"] = "CURRENT_MATCHUP_PIPELINE_WITH_FILE33_REFERENCE_ONLY"
    return out


def build_kproj_table(board):
    return _file33_match_apply(_FILE33_MATCHED_K_PIPELINE(board))


def build_copy_paste_k_slate(df, show_pass_notes=False, force_all_players_ou=False):
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return ""

        d = _file33_match_apply(df.copy())
        if "Line Source" in d.columns:
            d = d[d["Line Source"].astype(str).str.upper().eq("UNDERDOG")].copy()

        if "UD/Line" not in d.columns:
            d["UD/Line"] = d.get("Line")
        d["UD/Line"] = pd.to_numeric(d["UD/Line"], errors="coerce")
        d = d[d["UD/Line"].notna()].copy()
        d = _owp_one_final_row_per_pitcher(d)

        output = []
        for matchup, group in d.groupby("Matchup", sort=False):
            block = []
            for _, row in group.iterrows():
                line = _file33_match_num(row.get("UD/Line"))
                proj = _file33_match_num(row.get("File33 Matched K Projection"))
                if not np.isfinite(line) or not np.isfinite(proj):
                    continue

                side = "OVER" if proj > line else "UNDER" if proj < line else "PUSH"
                if side == "PUSH":
                    if not show_pass_notes:
                        continue
                    symbol = "PASS"
                else:
                    edge = abs(proj - line)
                    if edge < 0.65 and not show_pass_notes:
                        continue
                    prefix = "O" if side == "OVER" else "U"
                    symbol = f"🔥 {prefix}" if edge >= 1.00 else (f"⚠️ {prefix}" if edge < 0.65 else prefix)

                ip = float("nan")
                for column in ["IP Floor", "IP PROJ", "Projected IP"]:
                    if column in row.index:
                        candidate = _file33_match_num(row.get(column))
                        if np.isfinite(candidate):
                            ip = candidate
                            break

                ip_text = "—" if not np.isfinite(ip) else f"{ip:.2f}"
                block.append(f"• {row.get('Pitcher')} — {symbol} {line:.1f} — {proj:.2f} K — IP {ip_text}")

            if block:
                output.append(str(matchup))
                output.extend(block)
                output.append("")

        return "\n".join(output).strip()
    except Exception as exc:
        return f"Slate builder unavailable: {exc}"


# =============================================================================
# MONEYLINE TRUE-WIN-RATE GATE
#
# Final moneyline post-processor. It does not change projected scores or model
# probabilities. It only downgrades/labels rows where the current ML board has
# known loss ingredients:
# - thin projected score edge
# - high game volatility
# - missing/duplicate SP identity
# - model pick disagrees with projected-score pick
# - market value is missing or weak
# =============================================================================
MONEYLINE_TRUE_WIN_GATE_VERSION = "MONEYLINE_TRUE_WIN_GATE_2026_07_21"
_ML_TRUE_WIN_PREV_BUILD_BOARD = ml_build_board if "ml_build_board" in globals() else None


def _mltw_num(value, default=np.nan):
    try:
        if value in (None, "", "—", "-", "None", "nan", "NaN"):
            return default
        result = float(value)
        return result if np.isfinite(result) else default
    except Exception:
        return default


def _mltw_pick_side(row):
    pick = str(row.get("Pick") or row.get("ML Final Pick") or "").upper().strip()
    score_pick = str(row.get("Score Pick") or row.get("Run Differential Pick") or "").upper().strip()
    sim_pick = str(row.get("ML Sim Pick") or "").upper().strip()
    return pick, score_pick, sim_pick


def _mltw_data_issues(row):
    issues = []
    away_sp = str(row.get("Away SP") or "").strip()
    home_sp = str(row.get("Home SP") or "").strip()
    if not away_sp or away_sp == "—":
        issues.append("AWAY_SP_MISSING")
    if not home_sp or home_sp == "—":
        issues.append("HOME_SP_MISSING")
    if away_sp and home_sp and away_sp == home_sp:
        issues.append("DUPLICATE_SP")
    if str(row.get("ML Data Quality") or "").upper() in {"REVIEW", "WEAK", "BAD"}:
        issues.append("DATA_REVIEW")
    return issues


def _mltw_market_edge(row, pick):
    edge = _mltw_num(row.get("ML Sim Market Edge %"), np.nan)
    if np.isfinite(edge):
        return edge
    edge = _mltw_num(row.get("ML Edge %"), np.nan)
    if np.isfinite(edge):
        return edge
    try:
        matchup = str(row.get("Matchup") or "")
        away, home = [x.strip().upper() for x in matchup.split("@", 1)]
        away_model = _mltw_num(row.get("Away Model %"), np.nan)
        home_model = _mltw_num(row.get("Home Model %"), np.nan)
        away_market = _mltw_num(row.get("Away Market %"), np.nan)
        home_market = _mltw_num(row.get("Home Market %"), np.nan)
        if pick == away and np.isfinite(away_model) and np.isfinite(away_market):
            return round(away_model - away_market, 1)
        if pick == home and np.isfinite(home_model) and np.isfinite(home_market):
            return round(home_model - home_market, 1)
    except Exception:
        pass
    return np.nan


def _mltw_gate_row(row):
    pick, score_pick, sim_pick = _mltw_pick_side(row)
    score_edge = _mltw_num(row.get("Score Edge"), _mltw_num(row.get("Expected Run Differential"), np.nan))
    score_edge_abs = abs(score_edge) if np.isfinite(score_edge) else np.nan
    model_gap = abs((_mltw_num(row.get("Away Model %"), 50.0) or 50.0) - (_mltw_num(row.get("Home Model %"), 50.0) or 50.0))
    market_edge = _mltw_market_edge(row, pick)
    volatility_label = str(row.get("Game Volatility") or "").upper()
    volatility_score = _mltw_num(row.get("Volatility Score"), np.nan)
    issues = _mltw_data_issues(row)
    reasons = []

    if score_pick and pick and score_pick != pick:
        reasons.append("score_pick_disagrees")
    if sim_pick and pick and sim_pick != pick:
        reasons.append("simulation_disagrees")
    if np.isfinite(score_edge_abs) and score_edge_abs < 0.45:
        reasons.append("thin_score_edge")
    if model_gap < 8.0:
        reasons.append("thin_model_gap")
    if np.isfinite(market_edge) and market_edge < 3.0:
        reasons.append("weak_market_edge")
    if not np.isfinite(market_edge):
        reasons.append("no_market_edge")
    if volatility_label == "HIGH" or (np.isfinite(volatility_score) and volatility_score >= 63):
        reasons.append("high_game_volatility")
    if issues:
        reasons.extend(issues)

    strong_ok = (
        pick
        and not issues
        and (not score_pick or score_pick == pick)
        and np.isfinite(score_edge_abs) and score_edge_abs >= 0.65
        and model_gap >= 10.0
        and np.isfinite(market_edge) and market_edge >= 5.0
        and "high_game_volatility" not in reasons
    )
    lean_ok = (
        pick
        and not issues
        and (not score_pick or score_pick == pick)
        and np.isfinite(score_edge_abs) and score_edge_abs >= 0.45
        and model_gap >= 8.0
        and np.isfinite(market_edge) and market_edge >= 3.0
    )

    if strong_ok:
        status = "PLAYABLE"
        grade = f"🔥 ML EDGE — {pick}"
    elif lean_ok:
        status = "LEAN"
        grade = f"✅ ML LEAN — {pick}"
    else:
        status = "PASS"
        grade = f"🚫 PASS ML — {pick or 'NO PICK'}"

    confidence = 50.0
    if np.isfinite(market_edge):
        confidence += min(14.0, max(0.0, market_edge) * 2.0)
    confidence += min(8.0, max(0.0, model_gap - 6.0) * 0.8)
    if np.isfinite(score_edge_abs):
        confidence += min(7.0, score_edge_abs * 5.5)
    confidence -= 5.0 * len([r for r in reasons if r in {"score_pick_disagrees", "simulation_disagrees", "high_game_volatility"}])
    confidence -= 4.0 * len(issues)
    if status == "PASS":
        confidence = min(confidence, 57.0)
    confidence = round(float(clamp(confidence, 35.0, 82.0)), 1)

    return status, grade, confidence, "; ".join(dict.fromkeys(reasons)) or "signals aligned", market_edge


def ml_build_board(board):
    if _ML_TRUE_WIN_PREV_BUILD_BOARD is None:
        return pd.DataFrame()
    df = _ML_TRUE_WIN_PREV_BUILD_BOARD(board)
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df

    out = df.copy()
    statuses = []
    grades = []
    confidences = []
    notes = []
    value_edges = []
    for _, rr in out.iterrows():
        status, grade, conf, note, value_edge = _mltw_gate_row(rr.to_dict())
        statuses.append(status)
        grades.append(grade)
        confidences.append(conf)
        notes.append(note)
        value_edges.append(value_edge if np.isfinite(value_edge) else "")

    out["Pre-Gate ML Status"] = out.get("Status", "")
    out["Pre-Gate ML Grade"] = out.get("ML Grade", "")
    out["Status"] = statuses
    out["ML Grade"] = grades
    out["ML True Win Confidence %"] = confidences
    out["ML True Win Gate Note"] = notes
    out["ML Value Edge %"] = value_edges
    out["Moneyline Gate Version"] = MONEYLINE_TRUE_WIN_GATE_VERSION

    order = {"PLAYABLE": 0, "LEAN": 1, "PASS": 2}
    out["_mltw_sort"] = out["Status"].astype(str).map(lambda x: order.get(x, 9))
    edge_sort = pd.to_numeric(out.get("ML Value Edge %", out.get("ML Edge %", 0)), errors="coerce")
    out["_mltw_edge_sort"] = edge_sort.fillna(-999)
    out = out.sort_values(["_mltw_sort", "_mltw_edge_sort"], ascending=[True, False]).drop(columns=["_mltw_sort", "_mltw_edge_sort"])
    return out


_ML_TRUE_WIN_PREV_RENDER = render_moneyline_edge_tab if "render_moneyline_edge_tab" in globals() else None


def render_moneyline_edge_tab(board, dates=None):
    if _ML_TRUE_WIN_PREV_RENDER is None:
        st.markdown("### 💰 Moneyline Edge")
    else:
        _ML_TRUE_WIN_PREV_RENDER(board, dates)

    try:
        df = ml_build_board(board)
        if df is None or df.empty:
            return
        st.markdown('<div class="section-title-pro">Moneyline True Win Gate</div>', unsafe_allow_html=True)
        cols = [c for c in [
            "Matchup", "Pick", "Status", "ML Grade", "ML True Win Confidence %",
            "ML Value Edge %", "Score Edge", "Game Volatility", "ML True Win Gate Note",
            "Projected Score", "Score Pick", "Away SP", "Home SP", "Moneyline Gate Version"
        ] if c in df.columns]
        st.dataframe(df[cols] if cols else df, use_container_width=True, hide_index=True)
    except Exception as e:
        st.info(f"Moneyline true-win gate unavailable: {e}")


# =============================================================================
# MONEYLINE REAL-DATA QUALITY / SELECTOR UPGRADE
# Audit-only final layer for Moneyline. It does not touch K, PO, or slates.
# =============================================================================
MONEYLINE_DATA_QUALITY_VERSION = "MONEYLINE_DATA_QUALITY_2026_07_22"
_MLDQ_PREV_BUILD_BOARD = ml_build_board if "ml_build_board" in globals() else None
_MLDQ_PREV_RENDER = render_moneyline_edge_tab if "render_moneyline_edge_tab" in globals() else None


def _mldq_num(value, default=np.nan):
    try:
        if value in (None, "", "—", "-", "None", "nan", "NaN"):
            return default
        v = float(str(value).replace("%", "").replace(",", "").strip())
        if pd.isna(v):
            return default
        return v
    except Exception:
        return default


def _mldq_pick(row, keys, default=""):
    row = row if isinstance(row, dict) else {}
    for key in keys:
        value = row.get(key)
        if value not in (None, "", "—"):
            return value
    return default


def _mldq_pick_side(row):
    pick = str(_mldq_pick(row, ["Pick", "ML Final Pick", "Score Pick"], "") or "").upper().strip()
    matchup = str(row.get("Matchup") or "")
    away, home = "", ""
    try:
        if "@" in matchup:
            away, home = [x.strip().upper() for x in matchup.split("@", 1)]
    except Exception:
        pass
    side = "AWAY" if pick and pick == away else "HOME" if pick and pick == home else ""
    return pick, side, away, home


def _mldq_side_value(row, side, away_keys, home_keys, default=np.nan):
    keys = away_keys if side == "AWAY" else home_keys if side == "HOME" else away_keys + home_keys
    return _mldq_num(_mldq_pick(row, keys, default), default)


def _mldq_opp_side(side):
    return "HOME" if side == "AWAY" else "AWAY" if side == "HOME" else ""


def _mldq_moneyline_profile(row):
    pick, side, away, home = _mldq_pick_side(row)
    opp = _mldq_opp_side(side)
    reasons = []
    supports = []
    missing = []

    score_edge = abs(_mldq_num(row.get("Score Edge"), _mldq_num(row.get("Expected Run Differential"), np.nan)))
    value_edge = _mldq_num(row.get("ML Value Edge %"), _mldq_num(row.get("ML Sim Market Edge %"), _mldq_num(row.get("ML Edge %"), np.nan)))
    true_conf = _mldq_num(row.get("ML True Win Confidence %"), _mldq_num(row.get("ML Final Confidence %"), _mldq_num(row.get("ML Confidence %"), np.nan)))
    sim_pick = str(row.get("ML Sim Pick") or "").upper().strip()
    score_pick = str(row.get("Score Pick") or "").upper().strip()
    volatility = str(row.get("Game Volatility") or "").upper()
    vol_score = _mldq_num(row.get("Volatility Score"), np.nan)

    pick_sp = _mldq_side_value(row, side, ["Away SP Strength"], ["Home SP Strength"])
    opp_sp = _mldq_side_value(row, opp, ["Away SP Strength"], ["Home SP Strength"])
    pick_bp = _mldq_side_value(row, side, ["Away Bullpen"], ["Home Bullpen"])
    opp_bp = _mldq_side_value(row, opp, ["Away Bullpen"], ["Home Bullpen"])
    pick_wrc = _mldq_side_value(row, side, ["Away Team wRC+", "Away wRC+"], ["Home Team wRC+", "Home wRC+"])
    opp_wrc = _mldq_side_value(row, opp, ["Away Team wRC+", "Away wRC+"], ["Home Team wRC+", "Home wRC+"])
    pick_lineup = _mldq_side_value(row, side, ["Away Lineup Strength"], ["Home Lineup Strength"])
    opp_lineup = _mldq_side_value(row, opp, ["Away Lineup Strength"], ["Home Lineup Strength"])
    pick_rest = _mldq_side_value(row, side, ["Away Rest"], ["Home Rest"], 0.0)
    opp_rest = _mldq_side_value(row, opp, ["Away Rest"], ["Home Rest"], 0.0)
    park = _mldq_num(row.get("Park Factor"), np.nan)

    if side == "":
        missing.append("pick_side")
    if not np.isfinite(score_edge):
        missing.append("score_edge")
    if not np.isfinite(true_conf):
        missing.append("true_win_confidence")
    if not np.isfinite(pick_sp) or not np.isfinite(opp_sp):
        missing.append("starting_pitcher_strength")
    if not np.isfinite(pick_bp) or not np.isfinite(opp_bp):
        missing.append("bullpen_strength")
    if not np.isfinite(pick_wrc) or not np.isfinite(opp_wrc):
        missing.append("team_wrc_split")
    if not np.isfinite(pick_lineup) or not np.isfinite(opp_lineup):
        missing.append("confirmed_lineup_strength")
    if not np.isfinite(park):
        missing.append("park_factor")
    if not np.isfinite(value_edge):
        missing.append("market_value_edge")

    sp_gap = pick_sp - opp_sp if np.isfinite(pick_sp) and np.isfinite(opp_sp) else np.nan
    bp_gap = pick_bp - opp_bp if np.isfinite(pick_bp) and np.isfinite(opp_bp) else np.nan
    wrc_gap = pick_wrc - opp_wrc if np.isfinite(pick_wrc) and np.isfinite(opp_wrc) else np.nan
    lineup_gap = pick_lineup - opp_lineup if np.isfinite(pick_lineup) and np.isfinite(opp_lineup) else np.nan
    rest_gap = pick_rest - opp_rest if np.isfinite(pick_rest) and np.isfinite(opp_rest) else 0.0

    if np.isfinite(score_edge) and score_edge >= 0.65:
        supports.append("score edge")
    elif np.isfinite(score_edge) and score_edge < 0.45:
        reasons.append("thin score edge")
    if np.isfinite(value_edge) and value_edge >= 5.0:
        supports.append("market value")
    elif np.isfinite(value_edge) and value_edge < 3.0:
        reasons.append("weak market value")
    if np.isfinite(sp_gap):
        if sp_gap >= 4.0:
            supports.append("SP edge")
        elif sp_gap <= -4.0:
            reasons.append("SP disadvantage")
    if np.isfinite(bp_gap):
        if bp_gap >= 4.0:
            supports.append("bullpen edge")
        elif bp_gap <= -4.0:
            reasons.append("bullpen disadvantage")
    if np.isfinite(wrc_gap):
        if wrc_gap >= 5.0:
            supports.append("offense split edge")
        elif wrc_gap <= -5.0:
            reasons.append("offense split disadvantage")
    if np.isfinite(lineup_gap):
        if lineup_gap >= 4.0:
            supports.append("lineup edge")
        elif lineup_gap <= -4.0:
            reasons.append("lineup disadvantage")
    if rest_gap <= -1.0:
        reasons.append("rest/travel disadvantage")
    elif rest_gap >= 1.0:
        supports.append("rest edge")
    if volatility == "HIGH" or (np.isfinite(vol_score) and vol_score >= 63):
        reasons.append("high volatility")
    if sim_pick and pick and sim_pick != pick:
        reasons.append("simulation disagrees")
    if score_pick and pick and score_pick != pick:
        reasons.append("score pick disagrees")

    data_items = ["score_edge", "true_win_confidence", "starting_pitcher_strength", "bullpen_strength", "team_wrc_split", "confirmed_lineup_strength", "park_factor"]
    completeness = int(round((len(data_items) - len([x for x in missing if x in data_items])) / len(data_items) * 100))
    risk_penalty = min(22, len(reasons) * 4)
    support_bonus = min(18, len(supports) * 3)
    base = true_conf if np.isfinite(true_conf) else 55.0
    quality_score = int(round(clamp(base + support_bonus - risk_penalty + (completeness - 70) * 0.12, 35, 92)))

    if quality_score >= 78 and len(reasons) <= 1 and completeness >= 75:
        tier = "OFFICIAL ML"
    elif quality_score >= 68 and len(reasons) <= 3:
        tier = "PLAYABLE ML"
    elif quality_score >= 58:
        tier = "LEAN / TRACK ML"
    else:
        tier = "PASS ML"

    return {
        "ML Official Tier": tier,
        "ML Quality Score": quality_score,
        "ML Data Completeness %": completeness,
        "ML Missing Data": "; ".join(dict.fromkeys(missing)),
        "ML Risk Reasons": "; ".join(dict.fromkeys(reasons)) or "signals aligned",
        "ML Support Signals": "; ".join(dict.fromkeys(supports)),
        "ML SP Gap": "" if not np.isfinite(sp_gap) else round(float(sp_gap), 1),
        "ML Bullpen Gap": "" if not np.isfinite(bp_gap) else round(float(bp_gap), 1),
        "ML Offense Split Gap": "" if not np.isfinite(wrc_gap) else round(float(wrc_gap), 1),
        "ML Lineup Gap": "" if not np.isfinite(lineup_gap) else round(float(lineup_gap), 1),
        "ML Rest Gap": "" if not np.isfinite(rest_gap) else round(float(rest_gap), 1),
        "Moneyline Data Quality Version": MONEYLINE_DATA_QUALITY_VERSION,
    }


def _mldq_apply(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    rows = []
    for _, rr in df.iterrows():
        row = rr.to_dict()
        try:
            row.update(_mldq_moneyline_profile(row))
        except Exception as e:
            row["ML Official Tier"] = "ML AUDIT ERROR"
            row["ML Risk Reasons"] = str(e)[:120]
            row["Moneyline Data Quality Version"] = MONEYLINE_DATA_QUALITY_VERSION
        rows.append(row)
    out = pd.DataFrame(rows)
    try:
        order = {"OFFICIAL ML": 0, "PLAYABLE ML": 1, "LEAN / TRACK ML": 2, "PASS ML": 3, "ML AUDIT ERROR": 4}
        out["_mldq_sort"] = out["ML Official Tier"].astype(str).map(lambda x: order.get(x, 9))
        out["_mldq_score_sort"] = pd.to_numeric(out.get("ML Quality Score"), errors="coerce").fillna(-999)
        out = out.sort_values(["_mldq_sort", "_mldq_score_sort"], ascending=[True, False]).drop(columns=["_mldq_sort", "_mldq_score_sort"])
    except Exception:
        pass
    return out


def ml_build_board(board):
    if _MLDQ_PREV_BUILD_BOARD is None:
        return pd.DataFrame()
    return _mldq_apply(_MLDQ_PREV_BUILD_BOARD(board))


def render_moneyline_edge_tab(board, dates=None):
    if _MLDQ_PREV_RENDER is not None:
        _MLDQ_PREV_RENDER(board, dates)
    else:
        st.markdown("### 💰 Moneyline Edge")
    try:
        df = ml_build_board(board)
        if df is None or df.empty:
            return
        st.markdown('<div class="section-title-pro">Moneyline Official Selector / Missing Data</div>', unsafe_allow_html=True)
        cols = [c for c in [
            "Matchup", "Pick", "ML Official Tier", "ML Quality Score", "ML Data Completeness %",
            "Status", "ML Grade", "ML True Win Confidence %", "ML Value Edge %",
            "ML SP Gap", "ML Bullpen Gap", "ML Offense Split Gap", "ML Lineup Gap", "ML Rest Gap",
            "ML Support Signals", "ML Risk Reasons", "ML Missing Data",
            "Projected Score", "Score Pick", "Away SP", "Home SP", "Moneyline Data Quality Version"
        ] if c in df.columns]
        if cols:
            st.dataframe(df[cols], use_container_width=True, hide_index=True)
        else:
            st.dataframe(df, use_container_width=True, hide_index=True)
    except Exception as e:
        st.info(f"Moneyline official selector unavailable: {e}")


# =============================================================================
# MONEYLINE SAVE / AFTER-GRADE RELIABILITY FIX
# Handles newer ML Official Tier fields plus older ML Final Status rows.
# =============================================================================
MONEYLINE_AFTER_GRADE_FIX_VERSION = "MONEYLINE_AFTER_GRADE_FIX_2026_07_22"


def _mlag_norm_team(x):
    s = str(x or "").upper().strip().replace(".", "")
    aliases = {
        "WSN": "WSH", "WAS": "WSH",
        "CHW": "CWS", "CHISOX": "CWS",
        "KCR": "KC",
        "OAK": "ATH", "ATHLETICS": "ATH",
        "ARZ": "AZ",
        "SFG": "SF",
        "SDP": "SD",
        "TBR": "TB",
        "LAA": "LAA", "ANA": "LAA",
        "LAD": "LAD",
        "NYM": "NYM", "NYMETS": "NYM",
        "NYY": "NYY",
    }
    return aliases.get(s, s)


def _mlag_matchup_keys(matchup):
    keys = set()
    s = str(matchup or "").upper().strip()
    if not s:
        return keys
    for sep in [" @ ", "@", " VS ", "VS"]:
        if sep in s:
            try:
                a, h = [x.strip() for x in s.split(sep, 1)]
                a, h = _mlag_norm_team(a), _mlag_norm_team(h)
                if a and h:
                    keys.add(f"{a} @ {h}")
                    keys.add(f"{a}@{h}")
                break
            except Exception:
                pass
    keys.add(s)
    return keys


def _mlag_pick_from_row(row):
    pick = _tpl_first(row, ["ML Official Pick", "ML Final Pick", "ML Sim Pick", "Pick", "Score Pick"], "")
    return _mlag_norm_team(pick)


def _mlag_should_save(row):
    tier = str(row.get("ML Official Tier") or "").upper()
    status = str(row.get("ML Final Status") or row.get("Status") or "").upper()
    grade = str(row.get("ML Grade") or "").upper()
    if any(x in tier for x in ["OFFICIAL ML", "PLAYABLE ML"]):
        return True
    if any(x in status for x in ["STRONG", "LEAN", "MODEL LEAN", "PLAYABLE"]):
        return True
    if any(x in grade for x in ["ML EDGE", "ML LEAN", "MODEL ML LEAN"]):
        return True
    return False


def _ow_save_moneyline_board(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return {"saved": 0, "reason": "empty_board", "version": MONEYLINE_AFTER_GRADE_FIX_VERSION}
    existing = load_json(ML_PICK_LOG, [])
    if not isinstance(existing, list):
        existing = []
    today = _ow_line_source_date() if "_ow_line_source_date" in globals() else datetime.now().strftime("%Y-%m-%d")
    added = 0
    skipped = 0
    for _, rr in df.iterrows():
        r = rr.to_dict()
        if not _mlag_should_save(r):
            skipped += 1
            continue
        matchup = str(r.get("Matchup") or "").upper().strip()
        pick = _mlag_pick_from_row(r)
        if not matchup or not pick:
            skipped += 1
            continue
        key = f"{today}|{matchup}|{pick}|{r.get('ML Official Tier') or r.get('ML Final Status') or r.get('Status')}"
        if any(str(x.get("ml_key")) == key for x in existing if isinstance(x, dict)):
            skipped += 1
            continue
        r.update({
            "date": today,
            "ml_key": key,
            "graded_result": "PENDING",
            "saved_at": datetime.now().isoformat(),
            "Saved ML Pick": pick,
            "Saved ML Matchup": matchup,
            "ML Save Version": MONEYLINE_AFTER_GRADE_FIX_VERSION,
        })
        existing.append(r)
        added += 1
    save_json(ML_PICK_LOG, existing)
    return {"saved": added, "skipped": skipped, "total_saved_rows": len(existing), "path": ML_PICK_LOG, "version": MONEYLINE_AFTER_GRADE_FIX_VERSION}


def _ow_fetch_final_scores_for_dates(date_list):
    scores = {}
    for d in date_list or []:
        if not d:
            continue
        try:
            url = f"https://statsapi.mlb.com/api/v1/schedule?sportId=1&date={d}"
            data = requests.get(url, timeout=12).json()
            for day in data.get("dates", []):
                for g in day.get("games", []):
                    status = str((g.get("status") or {}).get("detailedState", ""))
                    if "Final" not in status and status not in ["Game Over", "Completed Early"]:
                        continue
                    teams = g.get("teams") or {}
                    away_team = (((teams.get("away") or {}).get("team") or {}).get("abbreviation"))
                    home_team = (((teams.get("home") or {}).get("team") or {}).get("abbreviation"))
                    away_score = (teams.get("away") or {}).get("score")
                    home_score = (teams.get("home") or {}).get("score")
                    if away_team and home_team and away_score is not None and home_score is not None:
                        away_team = _mlag_norm_team(away_team)
                        home_team = _mlag_norm_team(home_team)
                        winner = away_team if int(away_score) > int(home_score) else home_team
                        rec = {
                            "away": away_team,
                            "home": home_team,
                            "away_score": int(away_score),
                            "home_score": int(home_score),
                            "winner": winner,
                            "game_pk": g.get("gamePk"),
                            "status": status,
                        }
                        for key in _mlag_matchup_keys(f"{away_team} @ {home_team}"):
                            scores[key] = rec
        except Exception as e:
            scores[f"ERROR_{d}"] = {"error": str(e)[:160]}
            continue
    return scores


def _ow_grade_moneyline_saved():
    picks = load_json(ML_PICK_LOG, [])
    if not isinstance(picks, list) or not picks:
        return {"graded": 0, "saved": 0, "reason": "no_saved_moneyline_picks", "version": MONEYLINE_AFTER_GRADE_FIX_VERSION}
    dates_to_check = sorted({str(p.get("date") or "") for p in picks if isinstance(p, dict) and str(p.get("graded_result") or "PENDING").upper() == "PENDING"})
    scores = _ow_fetch_final_scores_for_dates(dates_to_check)
    score_keys = sorted([k for k in scores.keys() if not str(k).startswith("ERROR_")])
    results = load_json(ML_RESULT_LOG, [])
    if not isinstance(results, list):
        results = []
    graded = 0
    unmatched = []
    pending = 0
    for p in picks:
        if not isinstance(p, dict) or str(p.get("graded_result") or "PENDING").upper() != "PENDING":
            continue
        pending += 1
        matchup = str(p.get("Saved ML Matchup") or p.get("Matchup") or "").upper().strip()
        sc = None
        for key in _mlag_matchup_keys(matchup):
            sc = scores.get(key)
            if sc:
                break
        if not sc:
            unmatched.append(matchup)
            continue
        pick = _mlag_pick_from_row(p)
        result = "WIN" if pick and pick == sc.get("winner") else "LOSS"
        p["graded_result"] = result
        p["actual_winner"] = sc.get("winner")
        p["final_score"] = f"{sc.get('away')} {sc.get('away_score')} - {sc.get('home')} {sc.get('home_score')}"
        p["graded_at"] = datetime.now().isoformat()
        p["ML Grade Version"] = MONEYLINE_AFTER_GRADE_FIX_VERSION
        results.append(dict(p))
        graded += 1
    save_json(ML_PICK_LOG, picks)
    save_json(ML_RESULT_LOG, results)
    return {
        "graded": graded,
        "pending_before": pending,
        "unmatched": len(unmatched),
        "unmatched_matchups": unmatched[:20],
        "pending_checked_dates": dates_to_check,
        "final_scores_found": len(score_keys),
        "score_keys_sample": score_keys[:20],
        "pick_log": ML_PICK_LOG,
        "result_log": ML_RESULT_LOG,
        "version": MONEYLINE_AFTER_GRADE_FIX_VERSION,
    }


# =============================================================================
# MONEYLINE REAL DATA OVERRIDES / SOURCE GUIDE
# Lets daily bullpen, lineup, weather, odds, injury, and starter-confirmation data
# feed the Moneyline board when the user pastes or uploads it.
# =============================================================================
MONEYLINE_REAL_DATA_VERSION = "MONEYLINE_REAL_DATA_OVERRIDES_2026_07_22"
ML_REAL_DATA_FILE = os.path.join(STORAGE_DIR, "moneyline_real_data_overrides.csv")
_ML_REAL_DATA_PREV_BUILD_BOARD = ml_build_board if "ml_build_board" in globals() else None
_ML_REAL_DATA_PREV_RENDER = render_moneyline_edge_tab if "render_moneyline_edge_tab" in globals() else None


ML_REAL_DATA_TEMPLATE_COLUMNS = [
    "Matchup", "Away Lineup Confirmed", "Home Lineup Confirmed",
    "Away Bullpen Available", "Home Bullpen Available",
    "Away Closer Available", "Home Closer Available",
    "Away High Leverage Available", "Home High Leverage Available",
    "Away Bullpen Pitches 1D", "Home Bullpen Pitches 1D",
    "Away Bullpen Pitches 3D", "Home Bullpen Pitches 3D",
    "Away Starter Confirmed", "Home Starter Confirmed",
    "Away SP Role Flag", "Home SP Role Flag",
    "Away wRC+ vs Hand", "Home wRC+ vs Hand",
    "Away OPS vs Hand", "Home OPS vs Hand",
    "Away ISO vs Hand", "Home ISO vs Hand",
    "Away HardHit% vs Hand", "Home HardHit% vs Hand",
    "Away Defense Rating", "Home Defense Rating",
    "Away Baserunning Rating", "Home Baserunning Rating",
    "Park Weather Factor", "Temperature", "Wind MPH", "Wind Direction", "Roof",
    "Away Open ML", "Home Open ML", "Away Current ML", "Home Current ML",
    "Away Injury Flag", "Home Injury Flag", "Notes"
]


def _mlrd_bool(value):
    s = str(value or "").strip().upper()
    if s in ["Y", "YES", "TRUE", "1", "AVAILABLE", "CONFIRMED", "OPEN"]:
        return True
    if s in ["N", "NO", "FALSE", "0", "UNAVAILABLE", "OUT", "LIMITED", "CLOSED"]:
        return False
    return None


def _mlrd_load_overrides():
    try:
        if os.path.exists(ML_REAL_DATA_FILE):
            return pd.read_csv(ML_REAL_DATA_FILE)
    except Exception:
        pass
    return pd.DataFrame()


def _mlrd_save_overrides(df):
    try:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return {"saved": 0, "path": ML_REAL_DATA_FILE}
        out = df.copy()
        if "Matchup" not in out.columns:
            return {"saved": 0, "error": "Missing Matchup column", "path": ML_REAL_DATA_FILE}
        out["_mlrd_key"] = out["Matchup"].astype(str).map(lambda x: sorted(_mlag_matchup_keys(x))[0] if _mlag_matchup_keys(x) else str(x).upper())
        old = _mlrd_load_overrides()
        if isinstance(old, pd.DataFrame) and not old.empty:
            old["_mlrd_key"] = old["Matchup"].astype(str).map(lambda x: sorted(_mlag_matchup_keys(x))[0] if _mlag_matchup_keys(x) else str(x).upper())
            out = pd.concat([old, out], ignore_index=True, sort=False)
            out = out.drop_duplicates("_mlrd_key", keep="last")
        out = out.drop(columns=["_mlrd_key"], errors="ignore")
        out.to_csv(ML_REAL_DATA_FILE, index=False)
        return {"saved": len(out), "path": ML_REAL_DATA_FILE, "version": MONEYLINE_REAL_DATA_VERSION}
    except Exception as e:
        return {"saved": 0, "error": str(e)[:160], "path": ML_REAL_DATA_FILE}


def _mlrd_parse_uploaded(uploaded_file=None, text=""):
    frames = []
    try:
        if uploaded_file is not None:
            frames.append(pd.read_csv(uploaded_file))
    except Exception:
        pass
    try:
        if text and str(text).strip():
            from io import StringIO
            frames.append(pd.read_csv(StringIO(str(text).strip())))
    except Exception:
        pass
    if not frames:
        return pd.DataFrame()
    return pd.concat(frames, ignore_index=True, sort=False)


def _mlrd_get_override(row, overrides):
    if overrides is None or not isinstance(overrides, pd.DataFrame) or overrides.empty:
        return {}
    matchup = str(row.get("Matchup") or "")
    keys = _mlag_matchup_keys(matchup)
    if not keys:
        return {}
    try:
        d = overrides.copy()
        d["_keyset"] = d["Matchup"].astype(str).map(lambda x: _mlag_matchup_keys(x))
        for _, rr in d.iterrows():
            if keys.intersection(rr.get("_keyset") or set()):
                return rr.drop(labels=["_keyset"], errors="ignore").to_dict()
    except Exception:
        return {}
    return {}


def _mlrd_side_prefix(row, side):
    return "Away" if side == "AWAY" else "Home" if side == "HOME" else ""


def _mlrd_apply_row(row, override):
    if not override:
        row["ML Real Data Override"] = "NO"
        row["ML Real Data Version"] = MONEYLINE_REAL_DATA_VERSION
        return row
    out = dict(row)
    pick, side, away, home = _mldq_pick_side(out) if "_mldq_pick_side" in globals() else ("", "", "", "")
    opp = _mldq_opp_side(side) if "_mldq_opp_side" in globals() else ""
    pfx = _mlrd_side_prefix(out, side)
    opfx = _mlrd_side_prefix(out, opp)
    used = []
    reasons = []
    supports = []

    for col in ML_REAL_DATA_TEMPLATE_COLUMNS:
        if col in override and override.get(col) not in (None, "", "—"):
            out[f"ML Real {col}"] = override.get(col)

    for p in ["Away", "Home"]:
        lineup = _mlrd_bool(override.get(f"{p} Lineup Confirmed"))
        bp = _mlrd_bool(override.get(f"{p} Bullpen Available"))
        closer = _mlrd_bool(override.get(f"{p} Closer Available"))
        lev = _mlrd_bool(override.get(f"{p} High Leverage Available"))
        starter = _mlrd_bool(override.get(f"{p} Starter Confirmed"))
        if lineup is not None:
            used.append(f"{p} lineup")
            out[f"{p} Lineup Confirmed Override"] = "YES" if lineup else "NO"
        if bp is not None:
            used.append(f"{p} bullpen")
            out[f"{p} Bullpen Available Override"] = "YES" if bp else "NO"
        if closer is not None:
            used.append(f"{p} closer")
            out[f"{p} Closer Available Override"] = "YES" if closer else "NO"
        if lev is not None:
            used.append(f"{p} high leverage")
            out[f"{p} High Leverage Available Override"] = "YES" if lev else "NO"
        if starter is not None:
            used.append(f"{p} starter")
            out[f"{p} Starter Confirmed Override"] = "YES" if starter else "NO"

    if pfx:
        if _mlrd_bool(override.get(f"{pfx} Lineup Confirmed")) is False:
            reasons.append("pick lineup not confirmed")
        elif _mlrd_bool(override.get(f"{pfx} Lineup Confirmed")) is True:
            supports.append("pick lineup confirmed")
        if _mlrd_bool(override.get(f"{pfx} Bullpen Available")) is False:
            reasons.append("pick bullpen not available")
        elif _mlrd_bool(override.get(f"{pfx} Bullpen Available")) is True:
            supports.append("pick bullpen available")
        if _mlrd_bool(override.get(f"{pfx} Closer Available")) is False:
            reasons.append("pick closer unavailable")
        if _mlrd_bool(override.get(f"{pfx} High Leverage Available")) is False:
            reasons.append("pick high leverage arms unavailable")
        if _mlrd_bool(override.get(f"{pfx} Starter Confirmed")) is False:
            reasons.append("pick starter not confirmed")
        elif _mlrd_bool(override.get(f"{pfx} Starter Confirmed")) is True:
            supports.append("pick starter confirmed")
        role_flag = str(override.get(f"{pfx} SP Role Flag") or "").strip()
        if role_flag:
            reasons.append(f"pick SP role flag: {role_flag}")

    if opfx:
        if _mlrd_bool(override.get(f"{opfx} Bullpen Available")) is False:
            supports.append("opponent bullpen short")
        if _mlrd_bool(override.get(f"{opfx} Starter Confirmed")) is False:
            supports.append("opponent starter uncertainty")

    weather_factor = _mldq_num(override.get("Park Weather Factor"), np.nan) if "_mldq_num" in globals() else np.nan
    wind_mph = _mldq_num(override.get("Wind MPH"), np.nan) if "_mldq_num" in globals() else np.nan
    roof = str(override.get("Roof") or "").strip()
    if np.isfinite(weather_factor):
        used.append("park/weather factor")
        out["Park Factor"] = weather_factor
        if weather_factor >= 1.08:
            reasons.append("hitter weather/park volatility")
        elif weather_factor <= 0.94:
            supports.append("pitcher-friendly run environment")
    if np.isfinite(wind_mph):
        used.append("wind")
    if roof:
        used.append("roof")

    for p in ["Away", "Home"]:
        current = _mldq_num(override.get(f"{p} Current ML"), np.nan) if "_mldq_num" in globals() else np.nan
        opened = _mldq_num(override.get(f"{p} Open ML"), np.nan) if "_mldq_num" in globals() else np.nan
        if np.isfinite(current):
            used.append(f"{p} current ML")
            out[f"{p} Current ML Override"] = current
        if np.isfinite(opened):
            used.append(f"{p} open ML")
            out[f"{p} Open ML Override"] = opened

    old_risk = str(out.get("ML Risk Reasons") or "")
    old_support = str(out.get("ML Support Signals") or "")
    out["ML Risk Reasons"] = "; ".join([x for x in [old_risk] + reasons if x])
    out["ML Support Signals"] = "; ".join([x for x in [old_support] + supports if x])
    out["ML Real Data Override"] = "YES"
    out["ML Real Data Used"] = "; ".join(dict.fromkeys(used))
    out["ML Real Data Version"] = MONEYLINE_REAL_DATA_VERSION
    return out


def _mlrd_apply_overrides(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    overrides = _mlrd_load_overrides()
    if overrides is None or overrides.empty:
        out = df.copy()
        out["ML Real Data Override"] = "NO"
        out["ML Real Data Version"] = MONEYLINE_REAL_DATA_VERSION
        return out
    rows = []
    for _, rr in df.iterrows():
        row = rr.to_dict()
        row = _mlrd_apply_row(row, _mlrd_get_override(row, overrides))
        rows.append(row)
    out = pd.DataFrame(rows)
    try:
        if "_mldq_apply" in globals():
            out = _mldq_apply(out)
    except Exception:
        pass
    return out


def ml_build_board(board):
    if _ML_REAL_DATA_PREV_BUILD_BOARD is None:
        return pd.DataFrame()
    return _mlrd_apply_overrides(_ML_REAL_DATA_PREV_BUILD_BOARD(board))


def _mlrd_source_guide_table():
    return pd.DataFrame([
        {"Data Need": "Probable/confirmed starters + final scores", "Good Source": "MLB Stats API schedule/game feed", "Why It Helps": "SP confirmation, grading, postponed/final game state"},
        {"Data Need": "Team expected stats, xwOBA, hard hit", "Good Source": "Baseball Savant Statcast leaderboards/search", "Why It Helps": "Offense quality and pitcher contact quality"},
        {"Data Need": "Bullpen ERA/FIP/xFIP/rest", "Good Source": "FanGraphs/team bullpen tables or MLB game logs", "Why It Helps": "Late-game win probability and blown lead risk"},
        {"Data Need": "Daily park/weather/roof/wind", "Good Source": "BallparkPal or trusted park/weather board", "Why It Helps": "Run environment and volatility"},
        {"Data Need": "Current/opening moneylines", "Good Source": "Odds API / sportsbook consensus", "Why It Helps": "No-vig value and market disagreement"},
        {"Data Need": "Confirmed starting lineups/injuries", "Good Source": "MLB lineups feed / RotoWire-style lineup page", "Why It Helps": "Real offense strength instead of projected lineup"},
    ])


def _mlrd_json(url, params=None, timeout=14):
    try:
        if "safe_get_json" in globals():
            return safe_get_json(url, params=params, timeout=timeout)
    except Exception:
        pass
    try:
        return requests.get(url, params=params, timeout=timeout, headers={"User-Agent": "Mozilla/5.0"}).json()
    except Exception:
        return {}


def _mlrd_dates(dates=None):
    try:
        vals = [str(x) for x in (dates or []) if str(x).strip()]
        if vals:
            return vals
    except Exception:
        pass
    try:
        return [datetime.now().strftime("%Y-%m-%d")]
    except Exception:
        return []


def _mlrd_boxscore(game_pk):
    if not game_pk:
        return {}
    return _mlrd_json(f"https://statsapi.mlb.com/api/v1/game/{game_pk}/boxscore", timeout=14)


def _mlrd_team_batting_order_count(box, side):
    try:
        team_box = (((box.get("teams") or {}).get(side) or {}))
        order = team_box.get("battingOrder") or []
        return len(order)
    except Exception:
        return 0


def _mlrd_pitcher_pitches_from_box(box, side):
    try:
        team_box = ((box.get("teams") or {}).get(side) or {})
        players = team_box.get("players") or {}
        rows = []
        for _, pdata in players.items():
            pitching = ((pdata.get("stats") or {}).get("pitching") or {})
            if not pitching:
                continue
            pc = _mldq_num(pitching.get("numberOfPitches") or pitching.get("pitchesThrown") or pitching.get("pitchCount"), np.nan)
            ip_raw = pitching.get("inningsPitched")
            ip = _tpl_num(ip_raw, np.nan) if "_tpl_num" in globals() else np.nan
            gs = _mldq_num(pitching.get("gamesStarted"), 0)
            rows.append({"pitches": pc, "ip": ip, "gs": gs})
        if not rows:
            return 0
        relievers = [r for r in rows if np.isfinite(r.get("pitches", np.nan)) and not (_mldq_num(r.get("gs"), 0) >= 1)]
        if not relievers:
            # Fallback for boxscores that do not expose gamesStarted: skip the longest IP row.
            sorted_rows = sorted([r for r in rows if np.isfinite(r.get("pitches", np.nan))], key=lambda x: _mldq_num(x.get("ip"), 0), reverse=True)
            relievers = sorted_rows[1:] if len(sorted_rows) > 1 else []
        return int(sum(_mldq_num(r.get("pitches"), 0) for r in relievers))
    except Exception:
        return 0


def _mlrd_recent_bullpen_usage(team_abbr, as_of_date, days=3):
    team_abbr = _mlag_norm_team(team_abbr)
    try:
        dt = datetime.strptime(str(as_of_date), "%Y-%m-%d")
    except Exception:
        dt = datetime.now()
    start = (dt - timedelta(days=int(days))).strftime("%Y-%m-%d")
    end = (dt - timedelta(days=1)).strftime("%Y-%m-%d")
    data = _mlrd_json(
        "https://statsapi.mlb.com/api/v1/schedule",
        params={"sportId": 1, "startDate": start, "endDate": end, "hydrate": "team"},
        timeout=14,
    )
    pitches_by_day = {}
    games_checked = 0
    try:
        for day in data.get("dates", []) or []:
            dstr = day.get("date") or ""
            for g in day.get("games", []) or []:
                teams = g.get("teams") or {}
                away = _mlag_norm_team((((teams.get("away") or {}).get("team") or {}).get("abbreviation")))
                home = _mlag_norm_team((((teams.get("home") or {}).get("team") or {}).get("abbreviation")))
                if team_abbr not in [away, home]:
                    continue
                state = str(((g.get("status") or {}).get("detailedState") or ""))
                if "Final" not in state and state not in ["Game Over", "Completed Early"]:
                    continue
                side = "away" if team_abbr == away else "home"
                box = _mlrd_boxscore(g.get("gamePk"))
                pitches = _mlrd_pitcher_pitches_from_box(box, side)
                pitches_by_day[dstr] = pitches_by_day.get(dstr, 0) + pitches
                games_checked += 1
    except Exception:
        pass
    one_day = pitches_by_day.get(end, 0)
    three_day = sum(pitches_by_day.values())
    return {
        "pitches_1d": int(one_day),
        "pitches_3d": int(three_day),
        "games_checked": int(games_checked),
        "bullpen_available": "YES" if one_day <= 65 and three_day <= 150 else "NO",
        "closer_available": "YES" if one_day <= 42 else "NO",
        "high_leverage_available": "YES" if one_day <= 55 and three_day <= 130 else "NO",
    }


def _mlrd_auto_pull_mlb_data(dates=None):
    rows = []
    diagnostics = []
    for d in _mlrd_dates(dates):
        data = _mlrd_json(
            "https://statsapi.mlb.com/api/v1/schedule",
            params={"sportId": 1, "date": d, "hydrate": "probablePitcher,venue"},
            timeout=16,
        )
        try:
            games = []
            for day in data.get("dates", []) or []:
                games.extend(day.get("games", []) or [])
            diagnostics.append({"date": d, "games": len(games)})
            for g in games:
                teams = g.get("teams") or {}
                away = _mlag_norm_team((((teams.get("away") or {}).get("team") or {}).get("abbreviation")))
                home = _mlag_norm_team((((teams.get("home") or {}).get("team") or {}).get("abbreviation")))
                if not away or not home:
                    continue
                matchup = f"{away} @ {home}"
                game_pk = g.get("gamePk")
                away_prob = (((teams.get("away") or {}).get("probablePitcher") or {}).get("fullName") or "")
                home_prob = (((teams.get("home") or {}).get("probablePitcher") or {}).get("fullName") or "")
                venue = (g.get("venue") or {}).get("name") or ""
                state = str(((g.get("status") or {}).get("detailedState") or ""))
                box = _mlrd_boxscore(game_pk)
                away_order = _mlrd_team_batting_order_count(box, "away")
                home_order = _mlrd_team_batting_order_count(box, "home")
                away_bp = _mlrd_recent_bullpen_usage(away, d, days=3)
                home_bp = _mlrd_recent_bullpen_usage(home, d, days=3)
                row = {col: "" for col in ML_REAL_DATA_TEMPLATE_COLUMNS}
                row.update({
                    "Matchup": matchup,
                    "Away Lineup Confirmed": "YES" if away_order >= 9 else "NO",
                    "Home Lineup Confirmed": "YES" if home_order >= 9 else "NO",
                    "Away Bullpen Available": away_bp.get("bullpen_available"),
                    "Home Bullpen Available": home_bp.get("bullpen_available"),
                    "Away Closer Available": away_bp.get("closer_available"),
                    "Home Closer Available": home_bp.get("closer_available"),
                    "Away High Leverage Available": away_bp.get("high_leverage_available"),
                    "Home High Leverage Available": home_bp.get("high_leverage_available"),
                    "Away Bullpen Pitches 1D": away_bp.get("pitches_1d"),
                    "Home Bullpen Pitches 1D": home_bp.get("pitches_1d"),
                    "Away Bullpen Pitches 3D": away_bp.get("pitches_3d"),
                    "Home Bullpen Pitches 3D": home_bp.get("pitches_3d"),
                    "Away Starter Confirmed": "YES" if away_prob else "NO",
                    "Home Starter Confirmed": "YES" if home_prob else "NO",
                    "Away SP Role Flag": "" if away_prob else "PROBABLE_MISSING",
                    "Home SP Role Flag": "" if home_prob else "PROBABLE_MISSING",
                    "Roof": "UNKNOWN",
                    "Notes": f"Auto MLB pull {d}; gamePk {game_pk}; venue {venue}; status {state}; away SP {away_prob or 'missing'}; home SP {home_prob or 'missing'}; lineup counts {away_order}/{home_order}; bullpen games checked {away_bp.get('games_checked')}/{home_bp.get('games_checked')}",
                    "Auto Pull Date": d,
                    "Auto Pull Source": "MLB Stats API schedule + boxscore",
                    "Auto Pull Version": MONEYLINE_REAL_DATA_VERSION,
                })
                rows.append(row)
        except Exception as e:
            diagnostics.append({"date": d, "error": str(e)[:160]})
    df = pd.DataFrame(rows)
    save_status = _mlrd_save_overrides(df) if not df.empty else {"saved": 0, "path": ML_REAL_DATA_FILE}
    return {"rows": len(df), "save_status": save_status, "diagnostics": diagnostics, "version": MONEYLINE_REAL_DATA_VERSION}, df


