# =============================================================================
# K / PO REAL DATA OVERRIDES
# Daily feed for the missing inputs that decide wins: umpire/zone, pitch mix,
# leash/pitch limits, injury/role, and damage/traffic risk. This is applied
# before APP99 so the Right-Wins gate can use it.
# =============================================================================
K_REAL_DATA_VERSION = "K_PO_REAL_DATA_OVERRIDES_2026_07_26"
K_REAL_DATA_FILE = os.path.join(STORAGE_DIR, "k_po_real_data_overrides.csv")

K_REAL_DATA_TEMPLATE_COLUMNS = [
    "Pitcher", "Matchup", "Umpire", "Umpire K Factor", "Umpire Note",
    "Called Strike Rate", "Walk Rate", "Zone K Boost",
    "Pitch Mix Matchup", "Pitch Mix Matchup Score", "Pitch Mix Note",
    "Top Pitch", "Top Pitch Usage", "Opponent Whiff vs Top Pitch",
    "Whiff%", "CSW%", "SwStr%", "Chase%", "Velocity Delta",
    "Leash Score", "Pitch Count Limit", "Expected Pitch Count",
    "Role Flag", "Injury Flag", "Pitch Limit Flag", "Manager Hook Note",
    "Damage Risk Label", "Damage Risk Score", "Damage Risk Note",
    "Bullpen Status", "Bullpen Pitches 1D", "Bullpen Pitches 3D",
    "Confirmed Lineup", "Confirmed Batter Count", "Notes"
]


def _kreal_norm(value):
    try:
        return normalize_name(value)
    except Exception:
        return str(value or "").strip().lower()


def _kreal_load_overrides():
    try:
        if os.path.exists(K_REAL_DATA_FILE):
            return pd.read_csv(K_REAL_DATA_FILE)
    except Exception:
        pass
    return pd.DataFrame()


def _kreal_save_overrides(df):
    try:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return {"saved": 0, "path": K_REAL_DATA_FILE}
        out = df.copy()
        if "Pitcher" not in out.columns:
            return {"saved": 0, "error": "Missing Pitcher column", "path": K_REAL_DATA_FILE}
        if "Matchup" not in out.columns:
            out["Matchup"] = ""
        out["_kreal_key"] = out["Pitcher"].astype(str).map(_kreal_norm) + "|" + out["Matchup"].astype(str).str.upper().str.strip()
        old = _kreal_load_overrides()
        if isinstance(old, pd.DataFrame) and not old.empty and "Pitcher" in old.columns:
            if "Matchup" not in old.columns:
                old["Matchup"] = ""
            old["_kreal_key"] = old["Pitcher"].astype(str).map(_kreal_norm) + "|" + old["Matchup"].astype(str).str.upper().str.strip()
            out = pd.concat([old, out], ignore_index=True, sort=False).drop_duplicates("_kreal_key", keep="last")
        out = out.drop(columns=["_kreal_key"], errors="ignore")
        out.to_csv(K_REAL_DATA_FILE, index=False)
        return {"saved": len(out), "path": K_REAL_DATA_FILE, "version": K_REAL_DATA_VERSION}
    except Exception as e:
        return {"saved": 0, "error": str(e)[:160], "path": K_REAL_DATA_FILE}


def _kreal_parse_uploaded(uploaded_file=None, text=""):
    frames = []
    try:
        if uploaded_file is not None:
            frames.append(pd.read_csv(uploaded_file))
    except Exception:
        pass
    try:
        if text and str(text).strip():
            from io import StringIO
            frames.append(pd.read_csv(StringIO(str(text).strip())))
    except Exception:
        pass
    if not frames:
        return pd.DataFrame()
    return pd.concat(frames, ignore_index=True, sort=False)


def _kreal_get_override(row, overrides):
    if overrides is None or not isinstance(overrides, pd.DataFrame) or overrides.empty:
        return {}
    pitcher = _kreal_norm(row.get("Pitcher") or row.get("pitcher") or row.get("Player"))
    matchup = str(row.get("Matchup") or row.get("matchup") or "").upper().strip()
    if not pitcher:
        return {}
    try:
        d = overrides.copy()
        if "Pitcher" not in d.columns:
            return {}
        if "Matchup" not in d.columns:
            d["Matchup"] = ""
        d["_pitcher"] = d["Pitcher"].astype(str).map(_kreal_norm)
        d["_matchup"] = d["Matchup"].astype(str).str.upper().str.strip()
        exact = d[(d["_pitcher"] == pitcher) & (d["_matchup"] == matchup)]
        if not exact.empty:
            return exact.tail(1).iloc[0].drop(labels=["_pitcher", "_matchup"], errors="ignore").to_dict()
        loose = d[d["_pitcher"] == pitcher]
        if not loose.empty:
            return loose.tail(1).iloc[0].drop(labels=["_pitcher", "_matchup"], errors="ignore").to_dict()
    except Exception:
        return {}
    return {}


def _kreal_first(override, keys):
    for key in keys:
        if key in override and override.get(key) not in (None, "", "—", "nan", "NaN"):
            return override.get(key)
    return None


def _kreal_apply_row(row, override):
    if not override:
        row["K Real Data Override"] = "NO"
        row["K Real Data Version"] = K_REAL_DATA_VERSION
        return row
    out = dict(row)
    used = []

    mapping = {
        "Umpire": ["Umpire"],
        "Umpire Factor": ["Umpire K Factor", "Zone K Boost"],
        "Umpire Note": ["Umpire Note"],
        "Called Strike Rate": ["Called Strike Rate"],
        "Walk Rate": ["Walk Rate"],
        "Pitch Mix Matchup": ["Pitch Mix Matchup", "Pitch Mix Note"],
        "Pitch Mix Matchup Score": ["Pitch Mix Matchup Score"],
        "Pitch Mix Matchup Label": ["Pitch Mix Matchup"],
        "Pitch-Type Note": ["Pitch Mix Note"],
        "Pitch Arsenal Top Pitch Used": ["Top Pitch"],
        "Pitch Arsenal Top Usage Used": ["Top Pitch Usage"],
        "Opponent Whiff%": ["Opponent Whiff vs Top Pitch"],
        "Whiff%": ["Whiff%", "SwStr%"],
        "Recent SwStr%": ["SwStr%"],
        "Recent CSW%": ["CSW%"],
        "Recent Chase%": ["Chase%"],
        "Fastball Velo Delta": ["Velocity Delta"],
        "Leash Score": ["Leash Score"],
        "Pitch Count Limit": ["Pitch Count Limit"],
        "Projected Pitch Count": ["Expected Pitch Count"],
        "Role": ["Role Flag"],
        "Injury Note": ["Injury Flag"],
        "Pitch Limit Flag": ["Pitch Limit Flag", "Pitch Count Limit"],
        "Role Note": ["Manager Hook Note", "Role Flag"],
        "Manager Pull Risk": ["Manager Hook Note", "Role Flag", "Pitch Limit Flag"],
        "Damage Risk Label": ["Damage Risk Label"],
        "Damage Risk Score": ["Damage Risk Score"],
        "Damage Risk Note": ["Damage Risk Note"],
        "Bullpen Status": ["Bullpen Status"],
        "Bullpen Pitches 1D": ["Bullpen Pitches 1D"],
        "Bullpen Pitches 3D": ["Bullpen Pitches 3D"],
        "Confirmed Batter Count": ["Confirmed Batter Count"],
        "Lineup Source": ["Confirmed Lineup"],
    }
    for target, sources in mapping.items():
        val = _kreal_first(override, sources)
        if val is not None:
            out[target] = val
            used.append(target)

    confirmed = str(override.get("Confirmed Lineup") or "").strip().upper()
    if confirmed in {"Y", "YES", "TRUE", "1", "CONFIRMED"}:
        out["APP97 Lineup Status"] = "CONFIRMED_REAL_DATA_OVERRIDE"
    elif confirmed in {"N", "NO", "FALSE", "0", "PROJECTED"}:
        out["APP97 Lineup Status"] = out.get("APP97 Lineup Status") or "PROJECTED_REAL_DATA_OVERRIDE"

    out["K Real Data Override"] = "YES"
    out["K Real Data Used"] = "; ".join(dict.fromkeys(used))
    out["K Real Data Notes"] = override.get("Notes", "")
    out["K Real Data Version"] = K_REAL_DATA_VERSION
    return out


def _kreal_apply_overrides(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    overrides = _kreal_load_overrides()
    if overrides is None or overrides.empty:
        out = df.copy()
        out["K Real Data Override"] = "NO"
        out["K Real Data Version"] = K_REAL_DATA_VERSION
        return out
    rows = []
    for _, rr in df.iterrows():
        row = rr.to_dict()
        rows.append(_kreal_apply_row(row, _kreal_get_override(row, overrides)))
    return pd.DataFrame(rows)


_KREAL_PREV_BUILD_K = build_kproj_table if "build_kproj_table" in globals() else None


def build_kproj_table(board):
    if _KREAL_PREV_BUILD_K is None:
        return pd.DataFrame()
    return _kreal_apply_overrides(_KREAL_PREV_BUILD_K(board))


# =============================================================================
# OFFICIAL BASEBALL SAVANT INPUTS
# Pulls official MLB/Baseball Savant Statcast data into the final K board.
# Projection stays on the legacy/internal path; these fields support APP99,
# bad-game risk, PO damage risk, and audit sanity.
# =============================================================================
OFFICIAL_SAVANT_INPUT_VERSION = "OFFICIAL_BASEBALL_SAVANT_INPUTS_2026_07_26"


def _savant_num(value, default=np.nan):
    try:
        if value in (None, "", "—", "nan", "NaN"):
            return default
        v = float(str(value).replace("%", "").replace(",", "").strip())
        return v if np.isfinite(v) else default
    except Exception:
        return default


def _savant_pct_to_display(value):
    v = _savant_num(value, np.nan)
    if not np.isfinite(v):
        return ""
    return round(v * 100.0 if abs(v) <= 1 else v, 1)


def _savant_pitcher_id_from_row(row):
    for key in ["APP97 Pitcher Player ID", "Pitcher ID", "pitcher_id", "player_id", "MLB ID"]:
        try:
            v = row.get(key)
            if v not in (None, "", "—") and np.isfinite(float(v)):
                return int(float(v))
        except Exception:
            pass
    name = str(row.get("Pitcher") or row.get("pitcher") or row.get("Player") or "").strip()
    if name and "_mlb_search_player_id_by_name" in globals():
        try:
            return _mlb_search_player_id_by_name(name)
        except Exception:
            return None
    return None


def _savant_support_label(profile):
    if not isinstance(profile, dict) or not profile.get("available"):
        return "SAVANT_MISSING"
    support = 0
    caution = 0
    whiff = _savant_num(profile.get("whiff"), np.nan)
    csw = _savant_num(profile.get("csw"), np.nan)
    chase = _savant_num(profile.get("chase"), np.nan)
    first = _savant_num(profile.get("first_strike_pct"), np.nan)
    k_pct = _savant_num(profile.get("savant_k_pct"), np.nan)
    if np.isfinite(whiff):
        if whiff >= 0.295: support += 1
        elif whiff < 0.235: caution += 1
    if np.isfinite(csw):
        if csw >= 0.305: support += 1
        elif csw < 0.265: caution += 1
    if np.isfinite(chase):
        if chase >= 0.315: support += 1
        elif chase < 0.255: caution += 1
    if np.isfinite(first):
        if first >= 0.635: support += 1
        elif first < 0.585: caution += 1
    if np.isfinite(k_pct):
        if k_pct >= 0.27: support += 1
        elif k_pct < 0.19: caution += 1
    if support >= 3 and caution <= 1:
        return "SAVANT_K_SUPPORT"
    if caution >= 3 and support <= 1:
        return "SAVANT_K_CAUTION"
    if support > caution:
        return "SAVANT_SLIGHT_SUPPORT"
    if caution > support:
        return "SAVANT_SLIGHT_CAUTION"
    return "SAVANT_NEUTRAL"


def _savant_damage_label(profile):
    if not isinstance(profile, dict) or not profile.get("available"):
        return "SAVANT_DAMAGE_UNKNOWN"
    risk = 0
    hard = _savant_num(profile.get("hard_hit_pct"), np.nan)
    barrel = _savant_num(profile.get("barrel_pct"), np.nan)
    xwoba = _savant_num(profile.get("xwoba"), np.nan)
    ev = _savant_num(profile.get("avg_exit_velocity"), np.nan)
    if np.isfinite(hard) and hard >= 0.43: risk += 2
    elif np.isfinite(hard) and hard >= 0.39: risk += 1
    if np.isfinite(barrel) and barrel >= 0.095: risk += 2
    elif np.isfinite(barrel) and barrel >= 0.075: risk += 1
    if np.isfinite(xwoba) and xwoba >= 0.345: risk += 2
    elif np.isfinite(xwoba) and xwoba >= 0.320: risk += 1
    if np.isfinite(ev) and ev >= 91.0: risk += 1
    if risk >= 5:
        return "SAVANT_HIGH_DAMAGE_RISK"
    if risk >= 3:
        return "SAVANT_MED_DAMAGE_RISK"
    if risk >= 1:
        return "SAVANT_MILD_DAMAGE_RISK"
    return "SAVANT_DAMAGE_OK"


def _savant_apply_official_inputs(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    out_rows = []
    for _, rr in df.iterrows():
        row = rr.to_dict()
        pid = _savant_pitcher_id_from_row(row)
        profile = get_statcast_pitch_profile(pid, days=365) if pid else {"available": False, "message": "missing MLB pitcher id"}
        row["Official Savant Source"] = profile.get("official_source", "Baseball Savant Statcast CSV")
        row["Official Savant Status"] = "SUCCESS" if profile.get("available") else str(profile.get("message") or "UNAVAILABLE")[:120]
        row["Official Savant Rows"] = profile.get("rows", 0)
        row["Official Savant K%"] = _savant_pct_to_display(profile.get("savant_k_pct"))
        row["Official Savant BB%"] = _savant_pct_to_display(profile.get("savant_bb_pct"))
        row["Official Savant Whiff%"] = _savant_pct_to_display(profile.get("whiff"))
        row["Official Savant CSW%"] = _savant_pct_to_display(profile.get("csw"))
        row["Official Savant Chase%"] = _savant_pct_to_display(profile.get("chase"))
        row["Official Savant First Strike%"] = _savant_pct_to_display(profile.get("first_strike_pct"))
        row["Official Savant Swing%"] = _savant_pct_to_display(profile.get("swing_pct"))
        row["Official Savant Zone%"] = _savant_pct_to_display(profile.get("zone_pct"))
        row["Official Savant HardHit%"] = _savant_pct_to_display(profile.get("hard_hit_pct"))
        row["Official Savant Barrel%"] = _savant_pct_to_display(profile.get("barrel_pct"))
        row["Official Savant SweetSpot%"] = _savant_pct_to_display(profile.get("sweet_spot_pct"))
        row["Official Savant Avg EV"] = profile.get("avg_exit_velocity", "")
        row["Official Savant Avg LA"] = profile.get("avg_launch_angle", "")
        row["Official Savant xwOBA"] = profile.get("xwoba", "")
        row["Official Savant wOBA"] = profile.get("woba", "")
        row["Official Savant FB Velo"] = profile.get("fastball_velo_season", "")
        row["Official Savant FB Velo Recent"] = profile.get("fastball_velo_recent", "")
        row["Official Savant FB Velo Delta"] = profile.get("fastball_velo_delta", "")
        row["Official Savant K Skill Signal"] = _savant_support_label(profile)
        row["Official Savant Damage Signal"] = _savant_damage_label(profile)
        row["Official Savant Version"] = OFFICIAL_SAVANT_INPUT_VERSION

        # Feed existing generic audit fields only when they are blank/missing.
        if row.get("Whiff%") in (None, "", "—", "nan", "NaN") and row["Official Savant Whiff%"] != "":
            row["Whiff%"] = row["Official Savant Whiff%"]
        if row.get("Recent CSW%") in (None, "", "—", "nan", "NaN") and row["Official Savant CSW%"] != "":
            row["Recent CSW%"] = row["Official Savant CSW%"]
        if row.get("Recent Chase%") in (None, "", "—", "nan", "NaN") and row["Official Savant Chase%"] != "":
            row["Recent Chase%"] = row["Official Savant Chase%"]
        if row.get("First Strike %") in (None, "", "—", "nan", "NaN") and row["Official Savant First Strike%"] != "":
            row["First Strike %"] = row["Official Savant First Strike%"]
        if row.get("Damage Risk Label") in (None, "", "—", "nan", "NaN"):
            row["Damage Risk Label"] = row["Official Savant Damage Signal"]
        if row.get("Damage Risk Note") in (None, "", "—", "nan", "NaN"):
            row["Damage Risk Note"] = f"Official Savant: hard-hit {row['Official Savant HardHit%']} | barrel {row['Official Savant Barrel%']} | xwOBA {row['Official Savant xwOBA']} | EV {row['Official Savant Avg EV']}"
        out_rows.append(row)
    return pd.DataFrame(out_rows)


_SAVANT_PREV_BUILD_K = build_kproj_table if "build_kproj_table" in globals() else None


def build_kproj_table(board):
    if _SAVANT_PREV_BUILD_K is None:
        return pd.DataFrame()
    return _savant_apply_official_inputs(_SAVANT_PREV_BUILD_K(board))


# =============================================================================
# BASEBALL SAVANT CUSTOM PITCHER LEADERBOARD
# Uses the official custom leaderboard URL for season-level pitcher K%, BB%,
# whiff, xwOBA, barrel, hard-hit, and swing context.
# =============================================================================
SAVANT_CUSTOM_PITCHER_VERSION = "SAVANT_CUSTOM_PITCHER_LEADERBOARD_2026_07_26"
SAVANT_CUSTOM_PITCHER_URL = (
    "https://baseballsavant.mlb.com/leaderboard/custom?"
    "year={year}&type=pitcher&filter=&min={min_filter}&"
    "selections=pa%2Ck_percent%2Cbb_percent%2Cwoba%2Cxwoba%2Csweet_spot_percent%2C"
    "barrel_batted_rate%2Chard_hit_percent%2Cavg_best_speed%2Cavg_hyper_speed%2C"
    "whiff_percent%2Cswing_percent&chart=false&x=pa&y=pa&r=no&chartType=beeswarm&"
    "sort=xwoba&sortDir=asc"
)


def _svcustom_season_year():
    try:
        y = int(datetime.now().year)
        return max(2026, y)
    except Exception:
        return 2026


def _svcustom_norm_col(col):
    return str(col or "").strip().lower().replace(" ", "_").replace("-", "_").replace(".", "").replace("%", "_percent")


def _svcustom_norm_name(name):
    try:
        return normalize_name(name)
    except Exception:
        return str(name or "").lower().strip()


def _svcustom_first_col(df, candidates):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    norm_map = {_svcustom_norm_col(c): c for c in df.columns}
    for c in candidates:
        if _svcustom_norm_col(c) in norm_map:
            return norm_map[_svcustom_norm_col(c)]
    for c in df.columns:
        nc = _svcustom_norm_col(c)
        if any(_svcustom_norm_col(x) in nc for x in candidates):
            return c
    return None


def _svcustom_csv_from_url(url):
    try:
        headers = {
            "User-Agent": "Mozilla/5.0 MLBKPropEngine SavantCustom",
            "Accept": "text/csv,text/plain,*/*",
            "Referer": "https://baseballsavant.mlb.com/leaderboard/custom",
        }
        for suffix in ["&csv=true", "&csv=1", ""]:
            r = requests.get(url + suffix, headers=headers, timeout=22)
            if r.status_code != 200:
                continue
            text = str(r.text or "").strip()
            if not text or "<html" in text[:250].lower():
                continue
            try:
                parsed = pd.read_csv(io.StringIO(text))
            except Exception:
                continue
            if isinstance(parsed, pd.DataFrame) and not parsed.empty and len(parsed.columns) >= 4:
                return parsed
    except Exception as e:
        try:
            log_source_request(url, "SAVANT_CUSTOM_ERROR", str(e)[:220])
        except Exception:
            pass
    return pd.DataFrame()


@st.cache_data(ttl=21600, show_spinner=False)
def get_savant_custom_pitcher_leaderboard(year=None):
    """Official Baseball Savant custom leaderboard, with a wider low-min fallback."""
    year = int(year or _svcustom_season_year())
    frames = []
    for min_filter in ["q", "0"]:
        url = SAVANT_CUSTOM_PITCHER_URL.format(year=year, min_filter=min_filter)
        df = _svcustom_csv_from_url(url)
        if isinstance(df, pd.DataFrame) and not df.empty:
            df = df.copy()
            df["Savant Custom Min Filter"] = min_filter
            frames.append(df)
    if not frames:
        return pd.DataFrame()
    out = pd.concat(frames, ignore_index=True, sort=False)
    id_col = _svcustom_first_col(out, ["player_id", "mlb_id", "entity_id", "pitcher_id"])
    name_col = _svcustom_first_col(out, ["player_name", "name", "last_name, first_name", "last_name_first_name"])
    if name_col:
        out["_svcustom_name_norm"] = out[name_col].map(_svcustom_norm_name)
    if id_col:
        out["_svcustom_player_id"] = pd.to_numeric(out[id_col], errors="coerce")
        out = out.sort_values("Savant Custom Min Filter").drop_duplicates("_svcustom_player_id", keep="first")
    elif name_col:
        out = out.sort_values("Savant Custom Min Filter").drop_duplicates("_svcustom_name_norm", keep="first")
    return out


def _svcustom_match_pitcher(row, table):
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return None
    pid = _savant_pitcher_id_from_row(row)
    if pid is not None and "_svcustom_player_id" in table.columns:
        matches = table[pd.to_numeric(table["_svcustom_player_id"], errors="coerce").eq(float(pid))]
        if not matches.empty:
            return matches.iloc[0].to_dict()
    name = str(row.get("Pitcher") or row.get("pitcher") or row.get("Player") or "").strip()
    n = _svcustom_norm_name(name)
    if n and "_svcustom_name_norm" in table.columns:
        exact = table[table["_svcustom_name_norm"].astype(str).eq(n)]
        if not exact.empty:
            return exact.iloc[0].to_dict()
        scores = []
        for idx, val in table["_svcustom_name_norm"].astype(str).items():
            try:
                scores.append((name_score(n, val), idx))
            except Exception:
                scores.append((0, idx))
        if scores:
            best_score, best_idx = max(scores, key=lambda x: x[0])
            if best_score >= 0.90:
                return table.loc[best_idx].to_dict()
    return None


def _svcustom_get_stat(rec, candidates):
    if not isinstance(rec, dict):
        return np.nan
    norm_lookup = {_svcustom_norm_col(k): k for k in rec.keys()}
    for c in candidates:
        key = norm_lookup.get(_svcustom_norm_col(c))
        if key is not None:
            v = _savant_num(rec.get(key), np.nan)
            if np.isfinite(v):
                return v * 100.0 if abs(v) <= 1 and "percent" in _svcustom_norm_col(c) else v
    return np.nan


def _svcustom_set_if_real(row, key, value):
    if np.isfinite(_savant_num(value, np.nan)):
        row[key] = round(float(value), 3)


def _svcustom_blank(value):
    return value in (None, "", "—", "nan", "NaN") or (isinstance(value, float) and not np.isfinite(value))


def _svcustom_apply_pitcher_leaderboard(df):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    table = get_savant_custom_pitcher_leaderboard(_svcustom_season_year())
    out_rows = []
    for _, rr in df.iterrows():
        row = rr.to_dict()
        rec = _svcustom_match_pitcher(row, table)
        row["Savant Custom Version"] = SAVANT_CUSTOM_PITCHER_VERSION
        if not rec:
            row["Savant Custom Status"] = "NO_MATCH"
            row["Savant Custom Source"] = "Baseball Savant Custom Leaderboard"
            out_rows.append(row)
            continue

        stats = {
            "Savant Custom PA": _svcustom_get_stat(rec, ["pa"]),
            "Savant Custom K%": _svcustom_get_stat(rec, ["k_percent", "k%"]),
            "Savant Custom BB%": _svcustom_get_stat(rec, ["bb_percent", "bb%"]),
            "Savant Custom wOBA": _svcustom_get_stat(rec, ["woba"]),
            "Savant Custom xwOBA": _svcustom_get_stat(rec, ["xwoba"]),
            "Savant Custom SweetSpot%": _svcustom_get_stat(rec, ["sweet_spot_percent", "sweet_spot%"]),
            "Savant Custom Barrel%": _svcustom_get_stat(rec, ["barrel_batted_rate", "barrel_percent", "barrel%"]),
            "Savant Custom HardHit%": _svcustom_get_stat(rec, ["hard_hit_percent", "hard_hit%"]),
            "Savant Custom Avg Best Speed": _svcustom_get_stat(rec, ["avg_best_speed"]),
            "Savant Custom Avg Hyper Speed": _svcustom_get_stat(rec, ["avg_hyper_speed"]),
            "Savant Custom Whiff%": _svcustom_get_stat(rec, ["whiff_percent", "whiff%"]),
            "Savant Custom Swing%": _svcustom_get_stat(rec, ["swing_percent", "swing%"]),
        }
        row["Savant Custom Status"] = "SUCCESS"
        row["Savant Custom Source"] = "Baseball Savant Custom Leaderboard"
        row["Savant Custom Min Filter"] = rec.get("Savant Custom Min Filter", "")
        for key, val in stats.items():
            _svcustom_set_if_real(row, key, val)

        official_k = _savant_num(row.get("Savant Custom K%"), np.nan)
        current_k = _savant_num(row.get("APP97 Raw MLB Season Pitcher K%"), np.nan)
        if np.isfinite(official_k) and (not np.isfinite(current_k) or abs(current_k - official_k) >= 1.5 or _svcustom_blank(row.get("APP97 Pitcher K Source"))):
            row["APP97 Raw MLB Season Pitcher K%"] = round(float(official_k), 1)
            row["APP97 Pitcher K Source"] = "SAVANT_CUSTOM_LEADERBOARD"
            row["APP97 Pitcher K% Warning"] = "OK"
        if _svcustom_blank(row.get("Pitcher K% Used")) and np.isfinite(official_k):
            row["Pitcher K% Used"] = round(float(official_k), 1)
        for generic, custom in [
            ("Official Savant K%", "Savant Custom K%"),
            ("Official Savant BB%", "Savant Custom BB%"),
            ("Official Savant Whiff%", "Savant Custom Whiff%"),
            ("Official Savant Swing%", "Savant Custom Swing%"),
            ("Official Savant HardHit%", "Savant Custom HardHit%"),
            ("Official Savant Barrel%", "Savant Custom Barrel%"),
            ("Official Savant SweetSpot%", "Savant Custom SweetSpot%"),
            ("Official Savant xwOBA", "Savant Custom xwOBA"),
            ("Official Savant wOBA", "Savant Custom wOBA"),
        ]:
            if _svcustom_blank(row.get(generic)) and not _svcustom_blank(row.get(custom)):
                row[generic] = row.get(custom)
        if _svcustom_blank(row.get("Whiff%")) and not _svcustom_blank(row.get("Savant Custom Whiff%")):
            row["Whiff%"] = row.get("Savant Custom Whiff%")
        out_rows.append(row)
    return pd.DataFrame(out_rows)


_SVCUSTOM_PREV_BUILD_K = build_kproj_table if "build_kproj_table" in globals() else None


def build_kproj_table(board):
    if _SVCUSTOM_PREV_BUILD_K is None:
        return pd.DataFrame()
    return _svcustom_apply_pitcher_leaderboard(_SVCUSTOM_PREV_BUILD_K(board))


def _kreal_render_panel():
    st.markdown("#### K / PO Real Data Overrides")
    st.caption("Optional daily feed for umpire, pitch mix, leash, role/injury, damage risk, and bullpen context. Used by APP99; copy/paste slate stays clean.")
    template = pd.DataFrame([{col: "" for col in K_REAL_DATA_TEMPLATE_COLUMNS}])
    st.download_button("Download K/PO real-data template CSV", template.to_csv(index=False), file_name="k_po_real_data_template.csv", mime="text/csv", key="download_kreal_template")
